let LANG = "en";
function t(key){ return (I18N[LANG] && I18N[LANG][key]) || (I18N.es[key]) || key; }
const SITE_CONTENT = {"methodology":{"en":"<h4>What the risk score is</h4><p>The risk score is a single number from <b>0 to 1</b>. <b>0</b> means Bitcoin looks historically <b>cheap</b> relative to its own on-chain and market history; <b>1</b> means historically <b>stretched</b>. It is a context tool for long-term accumulation — not a price prediction, a trading signal, or financial advice. Alongside it sits a <b>confidence score (0–10)</b> that reports how strongly the underlying signals agree.</p><h4>The signals</h4><p>The score blends <b>eleven signals</b> organised into <b>five factor families</b>, so that no single metric can dominate the verdict:</p><p>- <b>Valuation</b> — price relative to on-chain cost basis and long-term trend (for example MVRV   and the Mayer Multiple). - <b>Miner economics</b> — mining revenue and network security effort (Puell-style measures,   hashrate and difficulty). - <b>Security-adjusted valuation</b> — valuation tempered by cumulative security spend   (thermocap-style). - <b>Holder behaviour</b> — how long-term and short-term holders are positioned, and whether coins   are moving at a profit or a loss. - <b>Network demand</b> — real on-chain usage: active addresses, transaction activity, and fees.</p><p>Both price-trend metrics and pure on-chain metrics are included on purpose, because they fail in different situations; blending them cancels out individual blind spots.</p><h4>From raw metric to score</h4><p>Each signal is measured on its own scale, then mapped onto a common 0–1 range with a <b>logistic (sigmoid) transform</b>. Every transform has a <b>centre</b> (the value treated as neutral, which contributes 0.5) and a <b>scale</b> (how quickly the contribution moves away from neutral). The transformed signals are <b>weighted and blended</b> into a single composite, which is then <b>lightly smoothed</b> with an exponential moving average to remove day-to-day noise and data revisions without adding meaningful lag.</p><h4>Confidence score</h4><p>The confidence score (0–10) is derived from how tightly the signals <b>agree</b> (dispersion) and how <b>decisive</b> they are (extremity). A broad, unanimous, decisive reading earns high confidence; a mixed or lukewarm one earns low confidence. A risk reading of 0.85 with high confidence means something quite different from 0.85 with low confidence, so the two are always shown together.</p><h4>Proxy signals (disclosure)</h4><p>Four of the eleven signals — those in the holder-behaviour family — ideally want coin-age and detailed cost-basis data that is not freely available. They are reconstructed as <b>transparent proxies</b> from the public data on hand, deliberately kept at <b>low weight</b> so they nudge rather than drive the score, and <b>flagged in the interface with a proxy badge</b>. Where a signal is an approximation, it is labelled as one rather than presented as a measured fact.</p><h4>Data and updates</h4><p>On-chain metrics come from <b>Coin Metrics community data</b>, read in a hybrid way — a deep historical dataset for cycle-long context, plus a live top-up for the most recent days. Price and market-capitalisation data come from public market sources. The score is recomputed <b>once per day (around 06:00 UTC)</b> by an automated pipeline. If the freshest data point is more than a few days old — for example during an upstream outage — the pipeline <b>refuses to publish</b>, so a stale reading is never shown as current; the last good value keeps serving until fresh data is available.</p><h4>Transparency and limitations</h4><p>The dashboard is transparent about <b>what drives the score</b>: the components table lists all eleven signals grouped by factor family, with how each is normalized, and every proxy is clearly flagged. The exact signal formulas, weights, and parameter values are part of the model's internal implementation and are not published, so the score is explainable but not independently reproducible from the outside.</p><p>Every part of this is a <b>lens, not a forecast</b>:</p><p>- Bitcoin has lived through only a handful of full cycles, so all \"historically cheap / stretched\"   judgements rest on a small sample. - Markets adapt; relationships that held in the past can weaken (reflexivity, regime change, new   sources of demand such as ETFs). - Four signals are proxies, and proxies can be wrong. - The neutral centres and weights are modelling choices; reasonable alternatives would shift the   series somewhat. - The score describes present conditions relative to history — it does <b>not</b> predict price or   call tops and bottoms.</p><p><b>Nothing here is investment, legal, or tax advice.</b> Bitcoin can lose a large share of its value, and the past behaviour of any metric does not guarantee future results. Always do your own research and consider a qualified professional before acting.</p><p>---</p>","es":"<h4>Qué es el índice de riesgo</h4><p>El índice de riesgo es un único número de <b>0 a 1</b>. <b>0</b> significa que Bitcoin se encuentra históricamente <b>barato</b> en relación con su propio historial on-chain y de mercado; <b>1</b> significa históricamente <b>tensionado</b>. Es una herramienta de contexto para la acumulación a largo plazo — no es una predicción de precio, una señal de trading ni asesoramiento financiero. Junto a él se muestra una <b>puntuación de confianza (0–10)</b> que indica hasta qué punto coinciden las señales subyacentes.</p><h4>Las señales</h4><p>El índice combina <b>once señales</b> organizadas en <b>cinco familias de factores</b>, de modo que ninguna métrica por sí sola pueda dominar el resultado:</p><p>- <b>Valoración</b> — precio respecto al coste base on-chain y a la tendencia de largo plazo (por   ejemplo, MVRV y el Múltiplo de Mayer). - <b>Economía de los mineros</b> — ingresos de la minería y esfuerzo de seguridad de la red (medidas al   estilo Puell, hashrate y dificultad). - <b>Valoración ajustada por seguridad</b> — valoración moderada por el gasto acumulado en seguridad   (estilo thermocap). - <b>Comportamiento de los holders</b> — cómo están posicionados los holders de largo y corto plazo, y si   las monedas se mueven en ganancia o en pérdida. - <b>Demanda de la red</b> — uso real de la cadena: direcciones activas, actividad de transacciones y   comisiones.</p><p>Se incluyen a propósito tanto métricas de tendencia de precio como métricas puramente on-chain, porque fallan en situaciones distintas; combinarlas cancela los puntos ciegos de cada una.</p><h4>De la métrica en bruto al índice</h4><p>Cada señal se mide en su propia escala y luego se traslada a un rango común de 0 a 1 mediante una <b>transformación logística (sigmoide)</b>. Cada transformación tiene un <b>centro</b> (el valor considerado neutral, que aporta 0,5) y una <b>escala</b> (con qué rapidez la aportación se aleja de lo neutral). Las señales transformadas se <b>ponderan y combinan</b> en un único índice compuesto, que después se <b>suaviza ligeramente</b> con una media móvil exponencial para eliminar el ruido diario y las revisiones de datos sin añadir un retardo significativo.</p><h4>Puntuación de confianza</h4><p>La puntuación de confianza (0–10) se obtiene a partir de cuánto <b>coinciden</b> las señales (dispersión) y cuán <b>contundentes</b> son (extremidad). Una lectura amplia, unánime y contundente obtiene alta confianza; una lectura mixta o tibia obtiene baja confianza. Un riesgo de 0,85 con alta confianza significa algo muy distinto de 0,85 con baja confianza, por lo que ambos se muestran siempre juntos.</p><h4>Señales proxy (divulgación)</h4><p>Cuatro de las once señales — las de la familia de comportamiento de los holders — requerirían idealmente datos de antigüedad de las monedas y de coste base detallado que no están disponibles de forma gratuita. Se reconstruyen como <b>proxies transparentes</b> a partir de los datos públicos disponibles, se mantienen deliberadamente con <b>bajo peso</b> para que orienten y no dominen el índice, y se <b>señalan en la interfaz con una etiqueta proxy</b>. Cuando una señal es una aproximación, se etiqueta como tal en lugar de presentarse como un dato medido.</p><h4>Datos y actualizaciones</h4><p>Las métricas on-chain provienen de los <b>datos de la comunidad de Coin Metrics</b>, leídos de forma híbrida: un conjunto histórico profundo para el contexto de ciclo completo, más una actualización en vivo de los días más recientes. Los datos de precio y capitalización provienen de fuentes públicas de mercado. El índice se recalcula <b>una vez al día (en torno a las 06:00 UTC)</b> mediante un proceso automatizado. Si el dato más reciente tiene más de unos pocos días — por ejemplo, durante una caída de la fuente — el proceso <b>se niega a publicar</b>, de modo que nunca se muestra una lectura obsoleta como actual; el último valor válido se sigue sirviendo hasta que haya datos frescos.</p><h4>Transparencia y limitaciones</h4><p>El panel es transparente sobre <b>qué mueve el índice</b>: la tabla de componentes muestra las once señales agrupadas por familia de factores, con cómo se normaliza cada una, y cada proxy está claramente señalado. Las fórmulas exactas de las señales, los pesos y los valores de los parámetros forman parte de la implementación interna del modelo y no se publican, por lo que el índice es explicable pero no reproducible de forma independiente desde el exterior.</p><p>Todo esto es una <b>lente, no un pronóstico</b>:</p><p>- Bitcoin solo ha vivido unos pocos ciclos completos, así que todo juicio de \"históricamente barato /   tensionado\" se basa en una muestra pequeña. - Los mercados se adaptan; relaciones que se cumplieron en el pasado pueden debilitarse (reflexividad,   cambios de régimen, nuevas fuentes de demanda como los ETF). - Cuatro señales son proxies, y los proxies pueden equivocarse. - Los centros neutrales y los pesos son decisiones de modelado; alternativas razonables desplazarían algo la   serie. - El índice describe las condiciones actuales en relación con la historia — <b>no</b> predice el precio ni marca   techos y suelos.</p><p><b>Nada de esto constituye asesoramiento de inversión, legal ni fiscal.</b> Bitcoin puede perder una gran parte de su valor, y el comportamiento pasado de cualquier métrica no garantiza resultados futuros. Investiga siempre por tu cuenta y considera consultar a un profesional cualificado antes de actuar.</p>"},"faq":[{"cat":{"en":"Getting Started & Overview","es":"Primeros pasos y visión general"},"items":[{"n":"1","q":{"en":"1. What exactly is the Bitcoin Risk Dashboard, and what problem does it solve for Bitcoin holders?","es":"1. ¿Qué es exactamente el Bitcoin Risk Dashboard y qué problema resuelve para los holders de Bitcoin?"},"a":{"en":"<p>The dashboard condenses many well-known Bitcoin valuation and on-chain health indicators into a single, easy-to-read number — the <b>risk score</b> — that runs from <b>0 (historically cheap)</b> to <b>1 (historically stretched)</b>. Around that score it wraps a small toolkit: an interactive price and risk chart, a strategy backtester, forward-looking Monte-Carlo simulations, and an optional email alert service.</p> <p>The problem it addresses is <b>signal overload and emotion</b>. A holder trying to decide whether now is a sensible time to accumulate faces a wall of noise: price is loud and emotional, while the genuinely informative on-chain metrics (MVRV, the Mayer Multiple, the Puell Multiple, hashrate trends, and so on) each live in different tools, use different scales, and each has real blind spots. Relying on any single indicator invites being whipsawed when that one metric misfires.</p> <p>The dashboard's answer is <b>aggregation and translation</b>. It combines eleven signals, organised into five factor families, so that no single metric can dominate the verdict, then translates the blended result into plain accumulation guidance: lean into buying when risk is historically low, and ease off — or simply keep steady — when risk is historically high. This is essentially a disciplined, evidence-informed version of what thoughtful long-term buyers try to do by instinct.</p> <p>Just as important is what it is <b>not</b>. It is not a price predictor, a trading bot, or a promise of returns. It is a context tool that answers a narrow, useful question — \"relative to its own history, is Bitcoin cheap or expensive right now, and how confident is that read?\" — while being transparent about its own uncertainty. The service is free, and the dashboard is transparent about what drives the score — it lays out every signal grouped by factor family, with how each is normalized, and clearly flags which signals are proxies.</p>","es":"<p>El panel condensa muchos indicadores conocidos de valoración y salud on-chain de Bitcoin en un único número fácil de leer — la <b>puntuación de riesgo</b> — que va de 0 (históricamente barato) a 1 (históricamente sobrevalorado). Alrededor de esa puntuación envuelve un pequeño conjunto de herramientas: un gráfico interactivo de precio y riesgo, un backtester de estrategias, simulaciones Monte-Carlo prospectivas y un servicio opcional de alertas por correo electrónico.</p><p>El problema que aborda es la sobrecarga de señales y la emoción. Un holder que intenta decidir si ahora es un momento sensato para acumular se enfrenta a un muro de ruido: el precio es ruidoso y emocional, mientras que las métricas on-chain genuinamente informativas (MVRV, el Mayer Multiple, el Puell Multiple, tendencias de hashrate, etc.) viven en herramientas diferentes, usan escalas distintas y cada una tiene puntos ciegos reales. Confiar en un solo indicador invita a ser azotado cuando ese indicador falla.</p><p>La respuesta del panel es <b>agregación y traducción</b>. Combina once señales, organizadas en cinco familias de factores, para que ninguna métrica única pueda dominar el veredicto, y luego traduce el resultado combinado en una guía de acumulación clara: inclínate hacia la compra cuando el riesgo es históricamente bajo, y relájate — o simplemente mantén la disciplina — cuando el riesgo es históricamente alto. Esto es esencialmente una versión disciplinada e informada por evidencia de lo que los compradores reflexivos a largo plazo intentan hacer por instinto.</p><p>Igualmente importante es lo que <b>no</b> es. No es un predictor de precio, un bot de trading ni una promesa de rendimientos. Es una herramienta de contexto que responde a una pregunta estrecha y útil — \"en relación con su propia historia, ¿está Bitcoin barato o caro ahora mismo, y cuán confiable es esa lectura?\" — mientras es transparente sobre su propia incertidumbre. El servicio es gratuito, y el panel es transparente sobre lo que impulsa la puntuación — muestra cada señal agrupada por familia de factores, con cómo se normaliza cada una, y marca claramente qué señales son proxies.</p>"}},{"n":"2","q":{"en":"2. How should a new user interpret the main risk score that ranges from 0 (historically cheap) to 1 (historically stretched)?","es":"2. ¿Cómo debe un nuevo usuario interpretar la puntuación principal de riesgo que va de 0 (históricamente barato) a 1 (históricamente sobrevalorado)?"},"a":{"en":"<p>Read the score as a <b>percentile-like position within Bitcoin's own history</b>, not as a probability of a crash or a price target. A reading near <b>0</b> means the blended signals sit where they have historically sat when Bitcoin was unusually cheap relative to its fundamentals; a reading near <b>1</b> means they sit where they have historically sat when Bitcoin was unusually stretched. The middle of the range is ordinary, unremarkable territory.</p> <p>A simple way to internalise the bands:</p> <ul> <li><b>0.00–0.25 — historically cheap.</b> Conditions that, in past cycles, preceded strong long-term accumulation opportunities. Higher-conviction buying zone for a DCA investor.</li> <li><b>0.25–0.50 — below average.</b> Reasonable, unhurried accumulation.</li> <li><b>0.50–0.75 — above average.</b> Getting warm; steady, disciplined buying rather than leaning in.</li> <li><b>0.75–1.00 — historically stretched.</b> Conditions that, in past cycles, often preceded elevated risk of drawdowns. A signal to temper enthusiasm, not necessarily to sell.</li> </ul> <p>Three cautions keep the interpretation honest. <b>It is relative, not absolute:</b> \"cheap\" means cheap versus Bitcoin's past, and history is a short, cycle-driven sample. <b>It is not timing:</b> a high score can persist and grind higher for months, and a low score can go lower before it turns — the score describes conditions, not the moment of reversal. <b>Pair it with the confidence score:</b> a risk read of 0.85 with high confidence (signals agreeing) means something quite different from 0.85 with low confidence (signals disagreeing). Treat the number as one well-constructed input into your own plan, sized to your own risk tolerance and time horizon.</p>","es":"<p>Lee la puntuación como una posición similar a un percentil dentro de la propia historia de Bitcoin, no como una probabilidad de crash o un objetivo de precio. Una lectura cerca de 0 significa que las señales combinadas se sitúan donde históricamente se han situado cuando Bitcoin estaba inusualmente barato en relación con sus fundamentales; una lectura cerca de 1 significa que se sitúan donde históricamente se han situado cuando Bitcoin estaba inusualmente sobrevalorado. El medio del rango es territorio ordinario, sin nada destacable.</p><p>Una forma sencilla de internalizar las bandas:</p><ul><li><b>0.00–0.25</b> — históricamente barato. Condiciones que, en ciclos pasados, precedieron fuertes oportunidades de acumulación a largo plazo. Zona de compra de mayor convicción para un inversor DCA.</li><li><b>0.25–0.50</b> — por debajo de la media. Acumulación razonable, sin prisas.</li><li><b>0.50–0.75</b> — por encima de la media. Calentando; compra constante y disciplinada en lugar de inclinarse.</li><li><b>0.75–1.00</b> — históricamente sobrevalorado. Condiciones que, en ciclos pasados, a menudo precedieron un riesgo elevado de drawdowns. Una señal para moderar el entusiasmo, no necesariamente para vender.</li></ul><p>Tres cautelas mantienen la interpretación honesta. Es <b>relativa</b>, no absoluta: \"barato\" significa barato versus el pasado de Bitcoin, y la historia es una muestra corta y impulsada por ciclos. <b>No es timing</b>: una puntuación alta puede persistir y subir durante meses, y una baja puede bajar más antes de girar — la puntuación describe condiciones, no el momento de reversión. Combínala con la puntuación de confianza: una lectura de riesgo de 0.85 con alta confianza (señales de acuerdo) significa algo muy distinto de 0.85 con baja confianza (señales en desacuerdo). Trata el número como una entrada bien construida en tu propio plan, dimensionada a tu tolerancia al riesgo y horizonte temporal.</p>"}},{"n":"3","q":{"en":"3. Is this tool designed primarily for long-term DCA investors, or can short-term traders also benefit?","es":"3. ¿Está esta herramienta diseñada principalmente para inversores DCA a largo plazo, o también pueden beneficiarse los traders de corto plazo?"},"a":{"en":"<p>It is designed <b>first and foremost for long-term, dollar-cost-averaging accumulators</b>, and that is where it is on its strongest footing. The underlying metrics — cost-basis ratios, miner economics, holder behaviour, network demand — move on the timescale of <b>weeks, months, and market cycles</b>, and the daily update cadence matches that rhythm. The whole design goal is to help someone accumulating over years decide <i>how hard to lean in</i> at a given time, which is exactly the DCA question.</p> <p>Short-term traders <b>can</b> draw value, but in a supporting role rather than as a trade trigger. The risk score is a useful <b>regime and context filter</b>: knowing you are in a historically cheap or historically stretched environment can shape position sizing, bias, and how much drawdown to expect. What it will not do is generate intraday or swing entries and exits — it carries no order-book, momentum, or short-timeframe structure, and it updates once a day, so it is simply the wrong instrument for fast decisions.</p> <p>A candid way to put it: the dashboard tells you <b>where you are standing in the cycle</b>, not <b>what price will do this week</b>. A trader who blends that cycle context with their own faster tooling is using it well; a trader expecting it to call tops and bottoms to the day is asking it for something it was never built to provide. The features reflect the priority — the backtester compares accumulation strategies, and the alerts are geared to risk levels and price zones rather than rapid-fire signals.</p>","es":"<p>Está diseñada ante todo para acumuladores a largo plazo con dollar-cost-averaging, y ahí es donde tiene su punto más fuerte. Las métricas subyacentes — ratios de cost-basis, economía de mineros, comportamiento de holders, demanda de red — se mueven en la escala de semanas, meses y ciclos de mercado, y el ritmo de actualización diario coincide con ese ritmo. Todo el diseño tiene como objetivo ayudar a alguien que acumula durante años a decidir cuánto inclinarse en un momento dado, que es exactamente la pregunta del DCA.</p><p>Los traders de corto plazo pueden extraer valor, pero en un papel de apoyo más que como disparador de trades. La puntuación de riesgo es un útil filtro de régimen y contexto: saber que estás en un entorno históricamente barato o sobrevalorado puede moldear el tamaño de posición, el sesgo y cuánto drawdown esperar. Lo que no hará es generar entradas y salidas intradía o swing — no lleva order-book, momentum ni estructura de corto plazo, y se actualiza una vez al día, así que es simplemente el instrumento equivocado para decisiones rápidas.</p><p>Una forma franca de decirlo: el panel te dice <b>dónde estás parado en el ciclo</b>, no qué hará el precio esta semana. Un trader que combina ese contexto de ciclo con sus propias herramientas más rápidas lo está usando bien; un trader que espera que llame tops y bottoms al día le está pidiendo algo para lo que nunca fue construido. Las características reflejan la prioridad — el backtester compara estrategias de acumulación, y las alertas están orientadas a niveles de riesgo y zonas de precio más que a señales de fuego rápido.</p>"}},{"n":"4","q":{"en":"4. Do I need to create an account or log in to access the live charts, backtest, and forward-test features?","es":"4. ¿Necesito crear una cuenta o iniciar sesión para acceder a los gráficos en vivo, el backtest y las características de forward-test?"},"a":{"en":"<p><b>No.</b> The core of the dashboard is deliberately open and login-free. The live price and risk chart, the factor breakdown, the interactive backtester, the risk–price matrix, and the Monte-Carlo forward simulations all run <b>directly in your browser</b> with no account, no sign-up, and no paywall. You can open the site and use every analytical feature immediately.</p> <p>This is a design choice as much as a convenience. Because the heavy computation — backtests and simulations — executes client-side on data the page has already loaded, there is nothing to gate behind a login, and the tool stays fast and private for casual visitors. It also lowers the barrier for the audience the project cares about: a newcomer should be able to explore the risk signal without committing anything.</p> <p>The <b>only</b> place any personal information enters is the <b>optional email alert service</b>. If — and only if — you want digests or triggered notifications delivered to your inbox, you provide an email address and confirm it through a double opt-in step. That is a subscription, not an account: there is no password, no profile, and no dashboard login. Everything you can do while signed out remains fully available; subscribing simply adds a delivery channel for the same public information. If you never want email, you never need to enter anything at all.</p>","es":"<p>No. El núcleo del panel es deliberadamente abierto y sin login. El gráfico en vivo de precio y riesgo, el desglose de factores, el backtester interactivo, la matriz riesgo-precio y las simulaciones Monte-Carlo forward se ejecutan directamente en tu navegador sin cuenta, sin registro y sin paywall. Puedes abrir el sitio y usar todas las características analíticas inmediatamente.</p><p>Esta es una elección de diseño tanto como una conveniencia. Porque el cálculo pesado — backtests y simulaciones — se ejecuta del lado del cliente en los datos que la página ya ha cargado, no hay nada que bloquear detrás de un login, y la herramienta se mantiene rápida y privada para visitantes casuales. También baja la barrera para la audiencia a la que le importa el proyecto: un recién llegado debería poder explorar la señal de riesgo sin comprometer nada.</p><p>El único lugar donde entra información personal es el servicio opcional de alertas por correo electrónico. Si — y solo si — quieres que resúmenes o notificaciones activadas te lleguen al buzón, proporcionas una dirección de correo y la confirmas mediante un paso de doble opt-in. Eso es una suscripción, no una cuenta: no hay contraseña, no hay perfil y no hay login al panel. Todo lo que puedes hacer mientras estás desconectado sigue estando totalmente disponible; suscribirte simplemente añade un canal de entrega para la misma información pública. Si nunca quieres correo, nunca necesitas introducir nada.</p>"}},{"n":"5","q":{"en":"5. How often is the risk score recalculated and the dashboard data refreshed?","es":"5. ¿Con qué frecuencia se recalcula la puntuación de riesgo y se actualizan los datos del panel?"},"a":{"en":"<p>Once per day. An automated job runs on a <b>daily schedule (around 06:00 UTC)</b>, pulls the latest available price and on-chain data, recomputes all eleven signals and the blended risk score, regenerates the data file the site reads, and publishes it. Because the underlying metrics evolve slowly, a daily cadence captures essentially all of the meaningful movement without adding noise.</p> <p>Concretely, the refresh pipeline does the following each day:</p> <ul> <li>fetches fresh market and on-chain data from the public data sources;</li> <li>recalculates every signal, applies the logistic transforms, blends and lightly smooths the composite;</li> <li>recomputes the confidence score and the 7-day and 30-day ranges;</li> <li>writes an updated <code>data.json</code>/<code>data.js</code> and deploys the site automatically.</li> </ul> <p>One honest caveat about freshness: on-chain data providers publish with their own short lag, so the most recent point typically reflects the <b>prior completed day</b> rather than the live minute — which is appropriate, since a daily-close view is exactly what these cycle metrics are meant to convey. As a safeguard, the pipeline <b>refuses to publish or broadcast a stale reading</b>: if the newest data point is more than a few days old (an upstream outage, say), the automation aborts rather than presenting an out-of-date score as current. So when you see a number, it is either genuinely recent or the system has deliberately held back — it will not quietly show you last week's risk as though it were today's.</p>","es":"<p>Una vez al día. Un trabajo automatizado se ejecuta en un horario diario (alrededor de las 06:00 UTC), extrae los últimos datos de precio y on-chain disponibles, recalcula las once señales y la puntuación de riesgo combinada, regenera el archivo de datos que lee el sitio y lo publica. Porque las métricas subyacentes evolucionan lentamente, un ritmo diario captura esencialmente todo el movimiento significativo sin añadir ruido.</p><p>Concretamente, el pipeline de actualización hace lo siguiente cada día:</p><ul><li>Extrae datos frescos de mercado y on-chain de las fuentes públicas;</li><li>Recalcula cada señal, aplica las transformaciones logísticas, combina y suaviza ligeramente el compuesto;</li><li>Recalcula la puntuación de confianza y los rangos de 7 y 30 días;</li><li>Escribe un data.json / data.js actualizado y despliega el sitio automáticamente.</li></ul><p>Una advertencia honesta sobre la frescura: los proveedores de datos on-chain publican con su propio retraso corto, así que el punto más reciente normalmente refleja el día completado anterior más que el minuto en vivo — lo cual es apropiado, ya que una vista de cierre diario es exactamente lo que estas métricas de ciclo pretenden transmitir. Como salvaguarda, el pipeline se niega a publicar o difundir una lectura obsoleta: si el punto de datos más nuevo tiene más de unos pocos días de antigüedad (una interrupción aguas arriba, digamos), la automatización aborta en lugar de presentar una puntuación desactualizada como actual. Así que cuando ves un número, o es genuinamente reciente o el sistema lo ha retenido deliberadamente — no te mostrará silenciosamente el riesgo de la semana pasada como si fuera el de hoy.</p>"}},{"n":"6","q":{"en":"6. What is the quickest way for a complete beginner to start using the risk signal for their Bitcoin accumulation?","es":"6. ¿Cuál es la forma más rápida para que un principiante completo empiece a usar la señal de riesgo para su acumulación de Bitcoin?"},"a":{"en":"<p>Start small and let the score shape <b>intensity</b>, not existence, of your buying. A sensible first routine:</p> <ul> <li><b>Open the dashboard and read two numbers</b> — today's risk score and its confidence. That single glance already tells you whether Bitcoin is historically cheap, ordinary, or stretched, and how much the signals agree.</li> <li><b>Keep a baseline DCA.</b> Decide on a fixed amount you can comfortably invest on a regular schedule (weekly or monthly). This is your default, regardless of the score.</li> <li><b>Tilt with the bands.</b> When risk is low (roughly under 0.25), consider leaning in a little harder; when risk is high (roughly over 0.75), consider easing back toward your baseline or pausing extra buys. The risk–price matrix can help you translate a target risk band into a rough price zone for a limit order.</li> <li><b>Optionally subscribe to a digest</b> so you are nudged when conditions shift, instead of having to check daily.</li> </ul> <p>Two beginner guardrails matter more than any tactic. <b>Do not wait in cash for a perfect zero.</b> Historically cheap readings are rare and uncomfortable to buy into, and holding out for them often means missing years of steady accumulation; a consistent DCA that merely <i>tilts</i> with risk beats an all-or-nothing bet on perfect timing. And <b>only invest what you can afford to lose</b> — Bitcoin's drawdowns are severe and the score does not remove that risk, it only helps you understand where you stand within it. Before committing real money, spend a few minutes in the backtester to see how a risk-tilted DCA behaved historically, and read the limitations section of this document so you are acting with eyes open.</p>","es":"<p>Empieza pequeño y deja que la puntuación moldee la <b>intensidad</b>, no la existencia, de tus compras. Una rutina sensata inicial:</p><ul><li>Abre el panel y lee dos números — la puntuación de riesgo de hoy y su confianza. Esa sola mirada ya te dice si Bitcoin está históricamente barato, ordinario o sobrevalorado, y cuánto coinciden las señales.</li><li>Mantén un DCA base. Decide una cantidad fija que puedas invertir cómodamente en un horario regular (semanal o mensual). Este es tu default, independientemente de la puntuación.</li><li>Inclínate con las bandas. Cuando el riesgo es bajo (aproximadamente por debajo de 0.25), considera inclinarte un poco más; cuando el riesgo es alto (aproximadamente por encima de 0.75), considera retroceder hacia tu baseline o pausar compras extra. La matriz riesgo-precio puede ayudarte a traducir una banda de riesgo objetivo en una zona de precio aproximada para una orden límite.</li><li>Opcionalmente suscríbete a un resumen para que te avisen cuando las condiciones cambien, en lugar de tener que comprobar diariamente.</li></ul><p>Dos guardarraíles para principiantes importan más que cualquier táctica. <b>No esperes en efectivo por un cero perfecto</b>. Las lecturas históricamente baratas son raras e incómodas de comprar, y esperarlas a menudo significa perder años de acumulación constante; un DCA consistente que simplemente se inclina con el riesgo supera una apuesta todo-o-nada por el timing perfecto. Y <b>solo invierte lo que puedas permitirte perder</b> — los drawdowns de Bitcoin son severos y la puntuación no elimina ese riesgo, solo te ayuda a entender dónde te sitúas dentro de él. Antes de comprometer dinero real, pasa unos minutos en el backtester para ver cómo se comportó históricamente un DCA inclinado al riesgo, y lee la sección de limitaciones de este documento para que actúes con los ojos abiertos.</p>"}}]},{"cat":{"en":"The Risk Metric Explained","es":"El indicador de riesgo explicado"},"items":[{"n":"7","q":{"en":"7. What are the main factors and individual signals combined to produce the final risk score?","es":"7. ¿Cuáles son los principales factores y señales individuales combinados para producir la puntuación final de riesgo?"},"a":{"en":"<p>The score blends <b>eleven signals organised into five factor families</b>. Each family looks at Bitcoin's valuation and health from a different angle, so that a distortion in one area cannot single-handedly swing the verdict:</p> <ul> <li><b>Valuation</b> — how price compares with on-chain notions of \"fair value.\" This is where classic cost-basis and trend ratios live, such as market-value-to-realised-value (MVRV) and the Mayer Multiple (price relative to its long-term moving average).</li> <li><b>Miner economics</b> — the health and stress of the mining industry, via revenue-versus-history measures in the spirit of the Puell Multiple, plus hashrate and difficulty behaviour.</li> <li><b>Security-adjusted valuation</b> — valuation viewed through the lens of cumulative security spend (thermocap-style), which tempers raw price ratios with how much work has been committed to the network.</li> <li><b>Holder behaviour</b> — how long-term and short-term holders are positioned and whether coins are moving at a profit or loss. Because the richest data here is not freely available, this family relies on transparent proxies (see Q12).</li> <li><b>Network demand</b> — real usage of the chain: active addresses, transaction activity, and fee pressure.</li> </ul> <p>Each of the eleven signals is first turned into a 0–1 contribution through a logistic transform (Q9), then the contributions are weighted and blended, and the result is lightly smoothed (Q11) to produce the final risk line. A separate confidence score (Q10) reports how much the signals agree.</p> <div class=\"faq-note\"><b>On precision.</b>The families above describe the architecture faithfully. The exact signal definitions, individual weights, and neutral centres are part of the model's internal implementation; what the components table shows is the structure: which signals feed each factor family and how each is normalized. This document intentionally does not freeze specific weights, which may be revised over time (see Q13).</div>","es":"<p>La puntuación combina once señales organizadas en cinco familias de factores. Cada familia mira la valoración y salud de Bitcoin desde un ángulo diferente, para que una distorsión en un área no pueda inclinar el veredicto por sí sola:</p><ul><li><b>Valoración</b> — cómo el precio se compara con nociones on-chain de \"valor justo\". Aquí viven los ratios clásicos de cost-basis y tendencia, como market-value-to-realised-value (MVRV) y el Mayer Multiple (precio relativo a su media móvil de largo plazo).</li><li><b>Economía de mineros</b> — la salud y estrés de la industria minera, a través de medidas de ingresos versus historia en el espíritu del Puell Multiple, más comportamiento de hashrate y dificultad.</li><li><b>Valoración ajustada por seguridad</b> — valoración vista a través de la lente del gasto acumulado en seguridad (estilo thermocap), que templa los ratios de precio crudos con cuánto trabajo se ha comprometido con la red.</li><li><b>Comportamiento de holders</b> — cómo están posicionados los holders de largo y corto plazo y si las monedas se mueven con ganancia o pérdida. Como los datos más ricos aquí no están disponibles gratuitamente, esta familia se basa en proxies transparentes (ver Q12).</li><li><b>Demanda de red</b> — uso real de la cadena: direcciones activas, actividad de transacciones y presión de fees.</li></ul><p>Cada una de las once señales se convierte primero en una contribución 0-1 a través de una transformación logística (Q9), luego las contribuciones se ponderan y combinan, y el resultado se suaviza ligeramente (Q11) para producir la línea de riesgo final. Una puntuación de confianza separada (Q10) informa cuánto coinciden las señales.</p><div class=\"faq-note\"><b>NOTA SOBRE PRECISIÓN.</b> Las familias anteriores describen la arquitectura fielmente. Las definiciones exactas de señales, pesos individuales y centros neutrales forman parte de la implementación interna del modelo; lo que muestra la tabla de componentes es la estructura: qué señales alimentan cada familia de factores y cómo se normaliza cada una. Este documento intencionalmente no congela pesos específicos, que pueden revisarse con el tiempo (ver Q13).</div>"}},{"n":"8","q":{"en":"8. Why does the model deliberately combine both pure price-trend metrics and on-chain metrics instead of relying on price alone?","es":"8. ¿Por qué el modelo combina deliberadamente métricas puras de tendencia de precio y métricas on-chain en lugar de depender solo del precio?"},"a":{"en":"<p>Because <b>price alone is both the loudest signal and the most easily misread</b>, and because price-based and on-chain metrics fail in different situations — so combining them cancels out individual blind spots.</p> <p>Pure <b>price-trend</b> metrics (for example, the Mayer Multiple, which is price divided by its 200-day moving average) are valuable precisely because they are simple, reactive, and reflect what the market is actually paying. But they are also reflexive: in a mania, price and its moving average can both climb together, and a purely price-based read can look \"not that extreme\" even as froth builds. Trend metrics can also be fooled by sharp, liquidity-driven moves that have no fundamental backing.</p> <p><b>On-chain</b> metrics look underneath price at behaviour and cost basis: what holders paid (realised value), whether coins are moving at profit or loss, how stressed miners are, how much the network is actually being used. These capture positioning and conviction that price cannot show. Their weakness is the mirror image — some are slow, some are noisy, and a few depend on data that must be approximated.</p> <p>Blending the two is a <b>diversification argument applied to indicators</b>. When a stretched price-trend read is confirmed by stretched cost-basis and euphoric holder behaviour and strained miner economics, the composite speaks with conviction (and the confidence score rises). When they disagree — say price looks hot but on-chain demand is cooling — the composite moderates and confidence falls, which is exactly the honest response to a mixed picture. No single metric can quietly dominate, and the false signals that plague single-indicator tools are dampened by requiring agreement across independent lines of evidence.</p>","es":"<p>Porque el precio solo es tanto la señal más ruidosa como la más fácilmente malinterpretada, y porque las métricas basadas en precio y las on-chain fallan en situaciones diferentes — así que combinarlas cancela los puntos ciegos individuales.</p><p>Las métricas puras de tendencia de precio (por ejemplo, el Mayer Multiple, que es el precio dividido por su media móvil de 200 días) son valiosas precisamente porque son simples, reactivas y reflejan lo que el mercado está pagando realmente. Pero también son reflexivas: en una manía, el precio y su media móvil pueden subir juntos, y una lectura puramente basada en precio puede parecer \"no tan extrema\" incluso mientras se construye espuma. Las métricas de tendencia también pueden ser engañadas por movimientos bruscos impulsados por liquidez que no tienen respaldo fundamental.</p><p>Las métricas on-chain miran debajo del precio al comportamiento y cost-basis: qué pagaron los holders (valor realizado), si las monedas se mueven con ganancia o pérdida, qué tan estresados están los mineros, cuánto se está usando realmente la red. Estas capturan posicionamiento y convicción que el precio no puede mostrar. Su debilidad es la imagen espejo — algunas son lentas, algunas ruidosas, y algunas dependen de datos que deben aproximarse.</p><p>Combinar las dos es un argumento de diversificación aplicado a indicadores. Cuando una lectura de tendencia de precio sobrevalorada se confirma por cost-basis sobrevalorado, comportamiento eufórico de holders y economía de mineros tensa, el compuesto habla con convicción (y la puntuación de confianza sube). Cuando discrepan — digamos que el precio parece caliente pero la demanda on-chain se está enfriando — el compuesto se modera y la confianza cae, que es exactamente la respuesta honesta a un panorama mixto. Ninguna métrica única puede dominar silenciosamente, y las señales falsas que plagan las herramientas de indicador único se amortiguan al requerir acuerdo a través de líneas de evidencia independientes.</p>"}},{"n":"9","q":{"en":"9. How does the logistic (sigmoid) transformation turn raw metric values into a 0–1 contribution for each signal?","es":"9. ¿Cómo transforma la función logística (sigmoide) los valores crudos de las métricas en una contribución 0-1 para cada señal?"},"a":{"en":"<p>Each signal produces a raw number on its own scale — an MVRV of 2.4, a Mayer Multiple of 1.1, and so on. Those numbers are not comparable to one another and have no natural ceiling, so before blending, every raw value is passed through a <b>logistic (sigmoid) function</b> that maps it onto a common 0–1 scale.</p> <p>The logistic curve has the familiar S-shape defined by <code>f(x) = 1 / (1 + e^(-k·(x − c)))</code>, and it uses two parameters per signal:</p> <ul> <li><b>the centre (c)</b> — the raw value treated as <i>neutral</i>. When a signal sits exactly at its centre, it contributes 0.5, i.e. \"neither cheap nor stretched.\" Centres are chosen from each metric's historical behaviour.</li> <li><b>the scale/steepness (k)</b> — how quickly the contribution moves away from 0.5 as the raw value departs from the centre. A steeper curve reacts sharply to small deviations; a gentler curve responds more gradually.</li> </ul> <p>This transform earns its place for three reasons. It is <b>bounded</b>: outputs are always between 0 and 1, so no single runaway metric can push the composite past its limits. It is <b>saturating</b>: at genuine extremes the curve flattens, so an already-euphoric metric getting slightly more euphoric barely moves the needle — which matches intuition and blunts the influence of outliers. And it makes signals <b>commensurable</b>: once everything is on the same 0–1 footing, weighting and averaging them is meaningful. The cost, disclosed plainly, is that the centres and steepness values are modelling choices; they are set conservatively and reviewed rather than tuned to flatter the historical record (see Q13).</p>","es":"<p>Cada señal produce un número crudo en su propia escala — un MVRV de 2.4, un Mayer Multiple de 1.1, etc. Esos números no son comparables entre sí y no tienen techo natural, así que antes de combinar, cada valor crudo pasa por una función logística (sigmoide) que lo mapea a una escala común 0-1.</p><p>La curva logística tiene la forma familiar de S definida por f(x) = 1 / (1 + e^(-k·(x − c))), y usa dos parámetros por señal:</p><ul><li><b>el centro (c)</b> — el valor crudo tratado como neutral. Cuando una señal está exactamente en su centro, contribuye 0.5, es decir \"ni barato ni sobrevalorado\". Los centros se eligen del comportamiento histórico de cada métrica.</li><li><b>la escala/pendiente (k)</b> — qué tan rápido se aleja la contribución de 0.5 a medida que el valor crudo se aleja del centro. Una curva más empinada reacciona bruscamente a pequeñas desviaciones; una más suave responde más gradualmente.</li></ul><p>Esta transformación gana su lugar por tres razones. Está <b>acotada</b>: las salidas siempre están entre 0 y 1, así que ninguna métrica desbocada puede empujar el compuesto más allá de sus límites. Es <b>saturante</b>: en extremos genuinos la curva se aplana, así que una métrica ya eufórica volviéndose ligeramente más eufórica apenas mueve la aguja — lo que coincide con la intuición y amortigua la influencia de valores atípicos. Y hace las señales <b>conmensurables</b>: una vez que todo está en el mismo pie 0-1, ponderarlas y promediarlas tiene sentido. El costo, declarado claramente, es que los centros y valores de pendiente son elecciones de modelado; se establecen de forma conservadora y se revisan en lugar de ajustarse para halagar el registro histórico (ver Q13).</p>"}},{"n":"10","q":{"en":"10. What is the purpose of the separate confidence score (0–10), and how is it derived from signal dispersion and extremity?","es":"10. ¿Cuál es el propósito de la puntuación de confianza separada (0–10), y cómo se deriva de la dispersión y extremidad de las señales?"},"a":{"en":"<p>The risk score tells you <b>where</b> Bitcoin sits; the confidence score tells you <b>how much to trust that read</b>. They answer different questions, and showing them together prevents a common mistake — treating a shaky, mixed signal with the same seriousness as a unanimous one.</p> <p>Confidence is built from two ingredients:</p> <ul> <li><b>Dispersion (agreement).</b> If the eleven signals cluster tightly — most pointing the same way — the read is coherent and confidence is high. If they are scattered, with some calling \"cheap\" and others \"stretched,\" the composite is an average over genuine disagreement, and confidence is low.</li> <li><b>Extremity.</b> Signals sitting decisively near the ends of their range carry a clearer message than signals loitering around neutral. A picture that is both unanimous <i>and</i> decisive earns the most confidence; one that is mixed and lukewarm earns the least.</li> </ul> <p>The practical value is calibration. A risk read of <b>0.85 with high confidence</b> means the evidence is broad and one-sided — froth is visible across valuation, holder behaviour, and miner economics at once. A read of <b>0.85 with low confidence</b> means the average happens to land high, but the signals are quarrelling, so the conclusion is fragile and deserves more caution and less conviction. Used well, confidence stops you from over-reacting to a number that only <i>looks</i> decisive. It is a companion to the risk score, never a substitute — a low score with high confidence is a very different situation from a low score with low confidence, and the dashboard shows both so you can tell them apart.</p>","es":"<p>La puntuación de riesgo te dice dónde está Bitcoin; la puntuación de confianza te dice cuánto confiar en esa lectura. Responden preguntas diferentes, y mostrarlas juntas previene un error común — tratar una señal temblorosa y mixta con la misma seriedad que una unánime.</p><p>La confianza se construye de dos ingredientes:</p><ul><li><b>Dispersión (acuerdo)</b>. Si las once señales se agrupan estrechamente — la mayoría apuntando en la misma dirección — la lectura es coherente y la confianza es alta. Si están dispersas, con algunas llamando \"barato\" y otras \"sobrevalorado\", el compuesto es un promedio sobre desacuerdo genuino, y la confianza es baja.</li><li><b>Extremidad</b>. Las señales que se sitúan decisivamente cerca de los extremos de su rango llevan un mensaje más claro que las que merodean alrededor de lo neutral. Una imagen que es tanto unánime como decisiva gana la mayor confianza; una que es mixta y tibia gana la menor.</li></ul><p>El valor práctico es la calibración. Una lectura de riesgo de 0.85 con alta confianza significa que la evidencia es amplia y unilateral — la espuma es visible a través de valoración, comportamiento de holders y economía de mineros al mismo tiempo. Una lectura de 0.85 con baja confianza significa que el promedio resulta alto, pero las señales están peleando, así que la conclusión es frágil y merece más cautela y menos convicción. Usada bien, la confianza te impide sobre-reaccionar a un número que solo parece decisivo. Es un compañero de la puntuación de riesgo, nunca un sustituto — una puntuación baja con alta confianza es una situación muy distinta de una puntuación baja con baja confianza, y el panel muestra ambas para que puedas distinguirlas.</p>"}},{"n":"11","q":{"en":"11. Why is a light EMA smoothing applied to the blended raw score before displaying the final risk line?","es":"11. ¿Por qué se aplica un suavizado EMA ligero a la puntuación cruda combinada antes de mostrar la línea final de riesgo?"},"a":{"en":"<p>Several of the inputs are inherently jittery. On-chain series carry day-to-day noise, providers occasionally revise recent data points as blocks settle, and raw ratios can twitch on a single volatile session. Plotting the blended raw score directly would inherit all of that flicker, producing a line that jumps around for reasons that have nothing to do with a real change in conditions.</p> <p>A <b>light exponential moving average (EMA)</b> addresses this by giving more weight to recent values while letting older ones fade smoothly. The result is a cleaner, more legible risk line whose movements are more likely to reflect genuine shifts than one-day artefacts. An EMA is preferred over a simple moving average because it responds faster to real turns while still damping noise.</p> <p>The key word is <b>light</b>. Smoothing always trades responsiveness for stability: too much and the line would lag badly, arriving at \"stretched\" only after the market had already told you so. The span is kept deliberately short, so the smoothing removes hair-trigger jitter and the visual sawtooth of data revisions without meaningfully delaying the signal. This is disclosed rather than hidden, because it is a genuine modelling choice: the displayed risk line is a lightly smoothed view of the raw composite, chosen so that what you see is steady enough to act on but still timely.</p>","es":"<p>Varias de las entradas son inherentemente nerviosas. Las series on-chain llevan ruido día a día, los proveedores ocasionalmente revisan puntos de datos recientes a medida que los bloques se asientan, y los ratios crudos pueden saltar en una sola sesión volátil. Graficar la puntuación cruda combinada directamente heredaría todo ese parpadeo, produciendo una línea que salta por razones que no tienen nada que ver con un cambio real en las condiciones.</p><p>Un promedio móvil exponencial (EMA) ligero aborda esto dando más peso a los valores recientes mientras deja que los más antiguos se desvanezcan suavemente. El resultado es una línea de riesgo más limpia y legible cuyos movimientos son más probables que reflejen cambios genuinos que artefactos de un día. Se prefiere un EMA sobre un promedio móvil simple porque responde más rápido a giros reales mientras sigue amortiguando el ruido.</p><p>La palabra clave es <b>ligero</b>. El suavizado siempre intercambia respuesta por estabilidad: demasiado y la línea retrasaría mucho, llegando a \"sobrevalorado\" solo después de que el mercado ya te lo hubiera dicho. El span se mantiene deliberadamente corto, así que el suavizado elimina el jitter de gatillo fácil y el diente de sierra visual de las revisiones de datos sin retrasar significativamente la señal. Esto se divulga en lugar de ocultarse, porque es una elección de modelado genuina: la línea de riesgo mostrada es una vista ligeramente suavizada del compuesto crudo, elegida para que lo que ves sea lo suficientemente estable como para actuar pero aún oportuno.</p>"}},{"n":"12","q":{"en":"12. Several signals are transparent proxies because certain Glassnode-style data is not freely available — how much weight do these proxies carry? <span class=\"src-pill proxy\">proxy</span>","es":"12. Varias señales son proxies transparentes porque ciertos datos estilo Glassnode no están disponibles gratuitamente — ¿cuánto peso llevan estos proxies?"},"a":{"en":"<p>Four of the eleven signals — those in the <b>holder-behaviour</b> family that ideally want coin-age and detailed cost-basis data (the kind of long-term-holder supply, dormancy, and profit/loss series associated with paid providers like Glassnode) — are <b>reconstructed as transparent proxies</b> from the freely available data the project does have. They approximate the intent of the ideal metric using observable quantities, rather than leaving those dimensions of the market unmeasured.</p> <p>Because a proxy is an approximation, it is treated with appropriate humility in three ways:</p> <ul> <li><b>Deliberately low weight.</b> The proxy signals are down-weighted relative to signals built on directly observed data, so they <i>nudge</i> the composite rather than drive it. If a proxy is wrong, its influence on the final score is limited by design.</li> <li><b>Visible labelling.</b> Each proxy carries an orange <span class=\"src-pill proxy\">proxy</span> badge in the interface, so you always know which contributions rest on approximation.</li> <li><b>Plain-language disclosure</b> (in both Spanish and English) explaining what the ideal metric would be and how the proxy stands in for it.</li> </ul> <p>On the exact figure: rather than quote a precise percentage here that could drift out of date, the honest answer is that the proxies collectively make up a <b>small share of total weight</b>, and the components table shows the full set of signals and how each is grouped and normalized, without exposing the individual weights. This transparency about which signals are approximated is a deliberate value of the project. Many popular tools quietly present modelled approximations as if they were measured facts; here, the approximated signals are flagged, down-weighted, and documented, so you can judge for yourself how much to lean on them.</p>","es":"<p>Cuatro de las once señales — las de la familia de comportamiento de holders que idealmente quieren datos de edad de monedas y cost-basis detallado (el tipo de series de suministro de holders de largo plazo, dormancia y ganancia/pérdida asociadas con proveedores pagos como Glassnode) — se reconstruyen como proxies transparentes a partir de los datos disponibles gratuitamente que el proyecto tiene. Aproximan la intención de la métrica ideal usando cantidades observables, en lugar de dejar esas dimensiones del mercado sin medir.</p><p>Porque un proxy es una aproximación, se trata con humildad apropiada de tres maneras:</p><ul><li><b>Peso deliberadamente bajo</b>. Las señales proxy tienen peso reducido en relación con las señales construidas sobre datos observados directamente, así que inclinan el compuesto en lugar de impulsarlo. Si un proxy está equivocado, su influencia en la puntuación final está limitada por diseño.</li><li><b>Etiquetado visible</b>. Cada proxy lleva una insignia naranja <b>PROXY</b> en la interfaz, así que siempre sabes qué contribuciones descansan en aproximación.</li><li><b>Divulgación en lenguaje claro</b> (tanto en español como en inglés) explicando qué sería la métrica ideal y cómo el proxy la sustituye.</li></ul><p>Sobre la cifra exacta: en lugar de citar un porcentaje preciso aquí que podría quedar desactualizado, la respuesta honesta es que los proxies colectivamente constituyen una pequeña parte del peso total, y la tabla de componentes muestra el conjunto completo de señales y cómo se agrupa y normaliza cada una, sin exponer los pesos individuales. Esta transparencia sobre qué señales se aproximan es un valor deliberado del proyecto. Muchas herramientas populares presentan silenciosamente aproximaciones modeladas como si fueran hechos medidos; aquí, las señales aproximadas están marcadas, con peso reducido y documentadas, para que puedas juzgar por ti mismo cuánto apoyarte en ellas.</p>"}},{"n":"13","q":{"en":"13. Are the centres and scales of the logistic functions fixed forever, or do they get reviewed and adjusted periodically?","es":"13. ¿Los centros y escalas de las funciones logísticas están fijos para siempre, o se revisan y ajustan periódicamente?"},"a":{"en":"<p>They are <b>intended to be stable, but they are reviewed periodically</b> — not silently refit to whatever would have made the past look tidiest. The distinction matters, because casually re-tuning parameters to fit history is one of the easiest ways for any model to fool itself and its users.</p> <p>The centres (neutral levels) and scales (steepness) are anchored to each metric's long-run historical behaviour and are meant to change rarely. When a review does happen — for example, because a metric's regime has genuinely shifted over a full cycle, or because a better data source becomes available — any change is <b>deliberate and documented</b>, so the evolution of the model is intentional rather than arbitrary.</p> <p>The guiding principle is <b>conservatism over cleverness</b>. Parameters are chosen to be defensible and robust rather than optimised to maximise a backtest, precisely because a model that has been over-tuned to the past tends to disappoint out of sample. This is also a stated limitation (see Q49): the risk series is somewhat sensitive to these choices, and a recalibration will nudge historical values. That is unavoidable in any model of this kind; the honest response is not to pretend the parameters are laws of nature, but to keep them stable and change them only deliberately when warranted. If you are comparing readings across a long span, it is worth remembering that the current parameter set is applied consistently to the whole history, so the series stays internally comparable.</p>","es":"<p>Están pensados para ser estables, pero se revisan periódicamente — no se reajustan silenciosamente a lo que habría hecho que el pasado se viera más ordenado. La distinción importa, porque reajustar parámetros casualmente para que encajen con la historia es una de las formas más fáciles en que cualquier modelo puede engañarse a sí mismo y a sus usuarios.</p><p>Los centros (niveles neutrales) y escalas (pendiente) están anclados al comportamiento histórico de largo plazo de cada métrica y están pensados para cambiar raramente. Cuando ocurre una revisión — por ejemplo, porque el régimen de una métrica ha cambiado genuinamente a lo largo de un ciclo completo, o porque una mejor fuente de datos se vuelve disponible — cualquier cambio es deliberado y documentado, así que la evolución del modelo es intencional en lugar de arbitraria.</p><p>El principio rector es <b>conservadurismo sobre inteligencia</b>. Los parámetros se eligen para ser defendibles y robustos en lugar de optimizados para maximizar un backtest, precisamente porque un modelo que ha sido sobreajustado al pasado tiende a decepcionar fuera de la muestra. Esto también es una limitación declarada (ver Q49): la serie de riesgo es algo sensible a estas elecciones, y una recalibración moverá los valores históricos. Eso es inevitable en cualquier modelo de este tipo; la respuesta honesta no es pretender que los parámetros son leyes de la naturaleza, sino mantenerlos estables y cambiarlos solo deliberadamente cuando esté justificado. Si estás comparando lecturas a lo largo de un periodo largo, vale la pena recordar que el conjunto de parámetros actual se aplica consistentemente a toda la historia, así que la serie permanece internamente comparable.</p>"}},{"n":"14","q":{"en":"14. Does the dashboard show a live breakdown of how much each factor is contributing to today's score?","es":"14. ¿Muestra el panel un desglose en vivo de cuánto contribuye cada factor a la puntuación de hoy?"},"a":{"en":"<p><b>Not as a live per-factor split.</b> The score is published as a single daily number, and the site does not display a real-time figure for how much valuation, miners, holders, or demand are each contributing on a given day. What the dashboard <i>does</i> give you is full transparency about <b>how that number is built</b>, so you can audit it rather than take it on faith.</p> <p>The <b>components table</b> lists all eleven signals grouped into their factor families — valuation, miner economics, security-adjusted valuation, holder behaviour, and network demand — and shows, for each one, what it measures, its data source, and how it is mapped onto the 0&ndash;1 scale. The methodology section then explains every signal in turn. Signals that rest on approximation carry the <span class=\"src-pill proxy\">proxy</span> badge, so the picture is honest about which inputs are directly measured and which are estimated.</p> <p>So the transparency here is structural: you can see exactly <i>which</i> signals go into the score and <i>how</i> each is normalized and grouped, even though the exact per-signal weights stay private and the site doesn't render a live per-family contribution figure. A live decomposition is a possible future addition.</p>","es":"<p><b>No como un desglose por factor en vivo.</b> La puntuación se publica como un único número diario, y el sitio no muestra una cifra en tiempo real de cuánto aportan la valoración, los mineros, los holders o la demanda en un día dado. Lo que el panel <i>sí</i> te da es transparencia total sobre <b>cómo se construye ese número</b>, para que puedas auditarlo en lugar de aceptarlo por fe.</p> <p>La <b>tabla de componentes</b> lista las once señales agrupadas en sus familias de factores — valoración, economía de los mineros, valoración ajustada por seguridad, comportamiento de los holders y demanda de la red — y muestra, para cada una, qué mide, su fuente de datos y cómo se mapea a la escala 0&ndash;1. La sección de metodología explica luego cada señal por turno. Las señales que descansan en aproximación llevan la insignia <span class=\"src-pill proxy\">proxy</span>, así que el panorama es honesto sobre qué entradas se miden directamente y cuáles se estiman.</p> <p>Así que la transparencia aquí es estructural: puedes ver exactamente <i>qué</i> señales entran en la puntuación y <i>cómo</i> se normaliza y agrupa cada una, aunque los pesos exactos por señal permanezcan privados y el sitio no renderice una cifra de contribución por familia en vivo. Un desglose en vivo es un posible añadido futuro.</p>"}}]},{"cat":{"en":"Data Sources & Methodology","es":"Fuentes de datos y metodología"},"items":[{"n":"15","q":{"en":"15. Which public data providers supply the price and on-chain metrics that power the model?","es":"15. ¿Qué proveedores públicos de datos suministran el precio y las métricas on-chain que alimentan el modelo?"},"a":{"en":"<p>The model runs entirely on <b>free, publicly available data</b>. The on-chain metrics — realised value, active addresses, transaction activity, miner revenue, hashrate, difficulty, and the series behind the valuation and demand factors — come primarily from <b>Coin Metrics' community data</b>. Price and market-capitalisation series come from the same public market-data ecosystem (Coin Metrics, with widely used public providers such as CoinGecko available for cross-checking market figures).</p> <p>One practical detail is worth explaining, because it shapes reliability. The project reads Coin Metrics in a <b>hybrid</b> way:</p> <ul> <li>a <b>bulk historical dataset</b> (a CSV covering many years) provides the deep history needed to place today's reading in cycle-long context; and</li> <li>a <b>community API \"top-up\"</b> fills in the most recent points that the bulk file may not yet include.</li> </ul> <p>This split exists because bulk exports and live endpoints update on different schedules; combining them keeps the series both long and current. It also came directly from experience — an earlier reliance on a single export that quietly stopped updating is exactly the failure the hybrid approach was built to prevent, which is why the pipeline also validates freshness on every run. The short version: reputable, public, no-cost sources for both price and on-chain data, deliberately read in a way that favours resilience.</p>","es":"<p>El modelo se ejecuta enteramente con datos gratuitos y públicamente disponibles. Las métricas on-chain — valor realizado, direcciones activas, actividad de transacciones, ingresos de mineros, hashrate, dificultad y las series detrás de los factores de valoración y demanda — provienen principalmente de los datos comunitarios de Coin Metrics. Las series de precio y capitalización de mercado provienen del mismo ecosistema público de datos de mercado (Coin Metrics, con proveedores públicos ampliamente usados como CoinGecko disponibles para verificación cruzada de cifras de mercado).</p><p>Un detalle práctico vale la pena explicar, porque moldea la fiabilidad. El proyecto lee Coin Metrics de forma <b>híbrida</b>:</p><ul><li>un conjunto de datos histórico masivo (un CSV que cubre muchos años) proporciona la historia profunda necesaria para situar la lectura de hoy en contexto de ciclo largo; y</li><li>una \"recarga\" de la API comunitaria llena los puntos más recientes que el archivo masivo puede no incluir aún.</li></ul><p>Esta división existe porque las exportaciones masivas y los endpoints en vivo se actualizan en horarios diferentes; combinarlos mantiene la serie tanto larga como actual. También surgió directamente de la experiencia — una dependencia anterior de una sola exportación que silenciosamente dejó de actualizarse es exactamente el fallo que el enfoque híbrido fue construido para prevenir, razón por la cual el pipeline también valida frescura en cada ejecución. La versión corta: fuentes reputadas, públicas y sin costo para precio y datos on-chain, leídas deliberadamente de una forma que favorece la resiliencia.</p>"}},{"n":"16","q":{"en":"16. Is the complete methodology — every formula, weight, and proxy definition — fully documented and reproducible by third parties?","es":"16. ¿Está la metodología completa — cada fórmula, peso y definición de proxy — totalmente documentada y reproducible por terceros?"},"a":{"en":"<p><b>Honestly, not fully — and it is worth being straight about that.</b> The dashboard is transparent about <i>what drives the score</i>: the components table lists all eleven signals grouped by factor family, with how each is normalized, and every proxy signal is clearly flagged and explained (see Q12 and Q14). The number is not a black box you are asked to take on faith, and the overall approach is described in plain terms throughout this document.</p> <p>What is <b>not</b> published is the implementation itself. The exact signal formulas, the individual weights, the logistic centres and scales, and the source code are kept in a <b>private repository</b>. That has a direct consequence:</p> <ul> <li>the input data is public and freely obtainable (Q15), but</li> <li>without the model code, a third party <b>cannot currently download it and reproduce the entire risk series byte-for-byte</b> — only an approximation can be rebuilt from the descriptions here.</li> </ul> <p>This is a deliberate, disclosed limitation rather than a hidden one. The visible components and the proxy disclosures give you enough to understand and sanity-check the score, while the precise recipe remains internal. If independent, code-level reproduction matters to you, that is a fair thing to want — publishing a full methodology write-up, or opening the model, is a possible future step — but it would be wrong to claim it exists today. In short: transparent about the <i>what</i> and the <i>why</i>, not fully open on the exact <i>how</i>.</p>","es":"<p>Honestamente, no totalmente — y vale la pena ser directo al respecto. El panel es transparente sobre lo que impulsa la puntuación: la tabla de componentes muestra las once señales agrupadas por familia de factores, con cómo se normaliza cada una, y cada señal proxy está claramente marcada y explicada (ver Q12 y Q14). El número no es una caja negra que se te pide aceptar por fe, y el enfoque general se describe en términos claros a lo largo de este documento.</p><p>Lo que <b>no</b> se publica es la implementación misma. Las fórmulas exactas de señales, los pesos individuales, los centros y escalas logísticas, y el código fuente se mantienen en un repositorio privado. Eso tiene una consecuencia directa:</p><ul><li>los datos de entrada son públicos y obtenibles gratuitamente (Q15), pero</li><li>sin el código del modelo, un tercero no puede actualmente descargarlos y reproducir la serie de riesgo completa byte por byte — solo se puede reconstruir una aproximación a partir de las descripciones aquí.</li></ul><p>Esto es una limitación deliberada y divulgada más que oculta. Los componentes visibles y las divulgaciones de proxies te dan suficiente para entender y verificar sanamente la puntuación, mientras que la receta precisa permanece interna. Si la reproducción a nivel de código independiente te importa, eso es algo justo de querer — publicar una documentación completa de metodología, o abrir el modelo, es un paso futuro posible — pero sería incorrecto afirmar que existe hoy. En resumen: transparente sobre el qué y el porqué, no totalmente abierto sobre el cómo exacto.</p>"}},{"n":"17","q":{"en":"17. How does the daily data pipeline handle missing values, API outages, or delayed on-chain reports?","es":"17. ¿Cómo maneja el pipeline diario de datos los valores faltantes, interrupciones de API o reportes on-chain retrasados?"},"a":{"en":"<p>Resilience is built in at several layers, because upstream data <i>will</i> occasionally be late, incomplete, or briefly unavailable, and the worst outcome would be silently presenting a broken or stale reading as if it were sound.</p> <ul> <li><b>Redundant reads.</b> The hybrid data approach (Q15) — a deep historical file plus a live top-up — means the series does not depend on a single endpoint being perfect on a given morning. If the top-up is briefly unavailable, the long history is still intact; if the bulk file lags, the top-up carries recent days.</li> <li><b>Sensible handling of gaps.</b> Short, isolated gaps in a slow-moving series are handled conservatively (for example by carrying the last valid observation) so a single missing point does not corrupt a ratio, while genuinely insufficient data is treated as insufficient rather than fabricated.</li> <li><b>A hard staleness guard.</b> If the newest usable data point is more than a few days old, the automation <b>aborts</b> the publish/broadcast step rather than shipping an out-of-date score. This is a non-negotiable safety rule.</li> <li><b>Fail-safe deployment.</b> The site serves the <b>last successfully generated</b> data file, so if a scheduled run errors out, visitors continue to see the last good reading (clearly dated) instead of a blank or corrupted page, and the next successful run simply supersedes it.</li> </ul> <p>The honest framing is that these mechanisms prioritise <b>not being wrong</b> over <b>always being current</b>. On a normal day the pipeline is fully up to date; on a bad upstream day it prefers to hold the last trustworthy value and, if necessary, skip a broadcast rather than mislead you. Given that the metrics move slowly, a one-day pause during an outage costs almost nothing, whereas a confidently displayed stale number could genuinely mislead.</p>","es":"<p>La resiliencia está construida en varias capas, porque los datos aguas arriba ocasionalmente llegarán tarde, incompletos o brevemente no disponibles, y el peor resultado sería presentar silenciosamente una lectura rota o obsoleta como si fuera sólida.</p><ul><li><b>Lecturas redundantes</b>. El enfoque híbrido de datos (Q15) — un archivo histórico profundo más una recarga en vivo — significa que la serie no depende de que un solo endpoint sea perfecto en una mañana dada. Si la recarga está brevemente no disponible, la historia larga sigue intacta; si el archivo masivo se retrasa, la recarga lleva los días recientes.</li><li><b>Manejo sensato de huecos</b>. Huecos cortos y aislados en una serie de movimiento lento se manejan conservadoramente (por ejemplo, llevando la última observación válida) para que un solo punto faltante no corrompa un ratio, mientras que datos genuinamente insuficientes se tratan como insuficientes en lugar de fabricados.</li><li><b>Guardia dura de obsolescencia</b>. Si el punto de datos utilizable más nuevo tiene más de unos pocos días de antigüedad, la automatización aborta el paso de publicar/difundir en lugar de enviar una puntuación desactualizada. Esta es una regla de seguridad no negociable.</li><li><b>Despliegue a prueba de fallos</b>. El sitio sirve el último archivo de datos generado exitosamente, así que si una ejecución programada falla, los visitantes siguen viendo la última lectura buena (claramente fechada) en lugar de una página en blanco o corrupta, y la siguiente ejecución exitosa simplemente la reemplaza.</li></ul><p>El encuadre honesto es que estos mecanismos priorizan <b>no estar equivocado</b> sobre estar siempre actualizado. En un día normal el pipeline está totalmente actualizado; en un mal día aguas arriba prefiere retener el último valor confiable y, si es necesario, saltar una difusión en lugar de engañarte. Dado que las métricas se mueven lentamente, una pausa de un día durante una interrupción cuesta casi nada, mientras que un número obsoleto mostrado con confianza podría genuinamente engañar.</p>"}},{"n":"18","q":{"en":"18. Can an independent researcher download the necessary public datasets and exactly reproduce the entire historical risk series?","es":"18. ¿Puede un investigador independiente descargar los conjuntos de datos públicos necesarios y reproducir exactamente toda la serie histórica de riesgo?"},"a":{"en":"<p><b>They can reproduce the inputs, but not the full risk series — and the honest reason is the model code.</b> The underlying data is genuinely public: the same Coin Metrics community data and public price series are freely obtainable by anyone (Q15). What is not public is the implementation that turns that data into the score — the signal formulas, weights, and transforms are kept in a private repository (Q16).</p> <p>So a researcher can download the raw data and, using the descriptions in this document, build <i>an approximation</i> of the model — but they cannot exactly regenerate the published risk series without the actual code and parameter values. Any reconstruction would diverge wherever their choices differ from the model's. Two further caveats apply even to the public inputs, and they are common to everyone:</p> <ul> <li><b>Data revisions and snapshot timing.</b> On-chain providers occasionally revise recent values, and bulk exports are captured at a point in time, so the most recent points can differ slightly between two people pulling the data on different days.</li> <li><b>Thin early data.</b> Bitcoin's earliest years are sparse and volatile, so the deep-history end of any analysis carries wider uncertainty (see Q24).</li> </ul> <p>The straight answer: public data in, but the exact transformation is internal, so faithful end-to-end reproduction of the historical series is not currently possible from the outside.</p>","es":"<p>Pueden reproducir las entradas, pero no la serie de riesgo completa — y la razón honesta es el código del modelo. Los datos subyacentes son genuinamente públicos: los mismos datos comunitarios de Coin Metrics y series de precio públicas son obtenibles gratuitamente por cualquiera (Q15). Lo que no es público es la implementación que convierte esos datos en la puntuación — las fórmulas de señales, pesos y transformaciones se mantienen en un repositorio privado (Q16).</p><p>Así que un investigador puede descargar los datos crudos y, usando las descripciones en este documento, construir una aproximación del modelo — pero no puede regenerar exactamente la serie de riesgo publicada sin el código y valores de parámetros reales. Cualquier reconstrucción divergiría donde sus elecciones difieran de las del modelo. Dos advertencias adicionales aplican incluso a las entradas públicas, y son comunes a todos:</p><ul><li><b>Revisiones de datos y momento de instantáneas</b>. Los proveedores on-chain ocasionalmente revisan valores recientes, y las exportaciones masivas se capturan en un punto en el tiempo, así que los puntos más recientes pueden diferir ligeramente entre dos personas extrayendo los datos en días diferentes.</li><li><b>Datos tempranos delgados</b>. Los primeros años de Bitcoin son escasos y volátiles, así que el extremo de historia profunda de cualquier análisis lleva mayor incertidumbre (ver Q24).</li></ul><p>La respuesta directa: datos públicos entran, pero la transformación exacta es interna, así que la reproducción fiel de extremo a extremo de la serie histórica no es actualmente posible desde fuera.</p>"}},{"n":"19","q":{"en":"19. Are any paid or private data feeds used that are not disclosed in the public methodology documentation?","es":"19. ¿Se usan feeds de datos pagos o privados que no se divulgan en la documentación pública de metodología?"},"a":{"en":"<p><b>No.</b> There are no undisclosed paid or private data feeds. The model is built deliberately on free, public sources, and the documented methodology reflects the whole data supply — there is no hidden premium ingredient behind the scenes.</p> <p>This is not an accident of budget so much as a design commitment, and it has a very visible consequence: it is the exact reason four of the signals are <b>proxies</b>. If the project quietly paid for premium coin-age and cost-basis data, those four holder-behaviour signals could be computed directly and would not need approximating. Instead, because the project restricts itself to freely available public data, those dimensions are estimated from what is available and clearly flagged with the <span class=\"src-pill proxy\">proxy</span> badge.</p> <p>The broader principle is that the model runs entirely on <b>free, public data that anyone could obtain</b>. Quietly adding a paid feed would contradict that, and it is not done. So the honest, complete answer to the question is that there are no undisclosed data sources: what feeds the model is public data, and the four holder-behaviour signals are approximated precisely because the premium data that would replace them is deliberately not used.</p>","es":"<p>No. No hay feeds de datos pagos o privados no divulgados. El modelo está construido deliberadamente sobre fuentes gratuitas y públicas, y la metodología documentada refleja toda la cadena de suministro de datos — no hay ingrediente premium oculto detrás de escena.</p><p>Esto no es un accidente de presupuesto tanto como un compromiso de diseño, y tiene una consecuencia muy visible: es exactamente la razón por la que cuatro de las señales son proxies. Si el proyecto pagara silenciosamente por datos premium de edad de monedas y cost-basis, esas cuatro señales de comportamiento de holders podrían computarse directamente y no necesitarían aproximarse. En su lugar, porque el proyecto se restringe a datos públicos disponibles gratuitamente, esas dimensiones se estiman a partir de lo disponible y se marcan claramente con la insignia <b>PROXY</b>.</p><p>El principio más amplio es que el modelo se ejecuta enteramente con datos gratuitos y públicos que cualquiera podría obtener. Añadir silenciosamente un feed pago contradiría eso, y no se hace. Así que la respuesta honesta y completa a la pregunta es que no hay fuentes de datos no divulgadas: lo que alimenta el modelo es datos públicos, y las cuatro señales de comportamiento de holders se aproximan precisamente porque los datos premium que las reemplazarían no se usan deliberadamente.</p>"}}]},{"cat":{"en":"Backtesting & Strategy Evaluation","es":"Backtesting y evaluación de estrategias"},"items":[{"n":"20","q":{"en":"20. What does the interactive backtest feature actually compare when users choose between standard weekly DCA and dynamic risk-based DCA?","es":"20. ¿Qué compara exactamente la característica de backtest interactivo cuando los usuarios eligen entre DCA semanal estándar y DCA dinámico basado en riesgo?"},"a":{"en":"<p>It runs <b>two accumulation strategies over the same historical price path</b> and compares the results, so you can see what the risk signal would have changed. Both strategies start with the same premise — you are steadily buying Bitcoin over time — and differ only in <i>how they decide the size of each buy</i>.</p> <ul> <li><b>Standard DCA</b> buys a <b>fixed amount at a fixed interval</b> (for example, the same sum every week), regardless of conditions. It is the disciplined, emotion-free baseline that DCA is famous for.</li> <li><b>Dynamic risk-based DCA</b> keeps the same rhythm but <b>scales each purchase by the risk score</b>: more when risk is historically low, less (or nothing) when risk is historically high, according to the threshold you choose.</li> </ul> <p>Because the two strategies see identical prices and differ only in timing/sizing, the comparison <b>isolates the value of the buy-timing rule</b> itself. The backtester typically reports the outcomes that matter to an accumulator — how much Bitcoin each strategy ended up holding, the average cost basis achieved, and the ending value for the same total capital deployed — so you are comparing like with like.</p> <p>The purpose is educational and honest rather than promotional: it lets you <i>see for yourself</i> how tilting buys toward low-risk periods behaved historically, instead of taking a claim on faith. It is a controlled experiment on the past — hold the price path and the total capital fixed, change only the rule, and observe the difference — which is the cleanest way to reason about whether the signal would have helped. Please read Q21 and Q22 immediately, because interpreting that difference correctly requires understanding both why the gap tends to look large and what the backtest does and does not include.</p>","es":"<p>Ejecuta dos estrategias de acumulación sobre el mismo camino histórico de precios y compara los resultados, para que puedas ver qué habría cambiado la señal de riesgo. Ambas estrategias comienzan con la misma premisa — estás comprando Bitcoin de forma constante con el tiempo — y difieren solo en cómo deciden el tamaño de cada compra.</p><ul><li><b>DCA estándar</b> compra una cantidad fija en un intervalo fijo (por ejemplo, la misma suma cada semana), independientemente de las condiciones. Es la línea base disciplinada y libre de emoción por la que el DCA es famoso.</li><li><b>DCA dinámico basado en riesgo</b> mantiene el mismo ritmo pero escala cada compra según la puntuación de riesgo: más cuando el riesgo es históricamente bajo, menos (o nada) cuando el riesgo es históricamente alto, según el umbral que elijas.</li></ul><p>Porque las dos estrategias ven precios idénticos y difieren solo en timing/tamaño, la comparación aísla el valor de la regla de timing de compra en sí. El backtester típicamente reporta los resultados que importan a un acumulador — cuánto Bitcoin terminó teniendo cada estrategia, el cost-basis promedio logrado y el valor final para el mismo capital total desplegado — así que estás comparando peras con peras.</p><p>El propósito es educativo y honesto más que promocional: te permite ver por ti mismo cómo se comportó históricamente el inclinar compras hacia períodos de bajo riesgo, en lugar de aceptar una afirmación por fe. Es un experimento controlado sobre el pasado — mantén el camino de precios y el capital total fijos, cambia solo la regla, y observa la diferencia — que es la forma más limpia de razonar sobre si la señal habría ayudado. Por favor lee Q21 y Q22 inmediatamente, porque interpretar esa diferencia correctamente requiere entender tanto por qué la brecha tiende a verse grande como qué incluye y no incluye el backtest.</p>"}},{"n":"21","q":{"en":"21. Why do the historical backtests usually show such a large performance gap in favour of buying only at low-risk readings?","es":"21. ¿Por qué los backtests históricos usualmente muestran una brecha de rendimiento tan grande a favor de comprar solo en lecturas de bajo riesgo?"},"a":{"en":"<p>Part of the gap is a genuine mechanism, and part of it is a well-known illusion. Being clear about both is essential, because this is exactly the number people are most tempted to over-trust.</p> <p><b>The real mechanism.</b> Historically, low-risk readings have clustered around cycle lows, when Bitcoin was cheap. Concentrating purchases into those windows means buying <b>more Bitcoin per dollar</b>, which lowers your average cost basis and, given Bitcoin's long-run uptrend so far, ends in more coins and higher value. Skipping the historically stretched periods avoids buying near local tops. That is a legitimate edge <i>if</i> the signal really does identify cheap periods.</p> <p><b>Why the gap is overstated.</b> Several honest caveats shrink it:</p> <ul> <li><b>Hindsight / in-sample fit.</b> The model's neutral levels are informed by the same history the backtest runs on, so the rule is being graded partly on the exam it studied. Out of sample — on the future — the advantage is very likely to be <b>smaller</b>.</li> <li><b>Cash drag and opportunity cost.</b> Waiting for low-risk readings can mean sitting in cash for long stretches during which price rises. Idealised backtests often understate this drag and the discipline it demands.</li> <li><b>One asset, one long uptrend.</b> The result leans on Bitcoin's specific historical trajectory; an asset that did not keep making higher cycle highs would reward \"buy the dip\" far less.</li> <li><b>Frictions and taxes.</b> Real fees, spreads, and (especially) taxes are not your personal figures in a generic backtest (Q22), and they erode edges.</li> </ul> <p>So the correct reading is: the low-risk strategy has a <b>plausible, intuitive advantage</b>, but the eye-catching size of the historical gap flatters it. Treat the backtest as evidence that tilting toward cheap periods is <i>reasonable</i>, not as a promise of the same margin going forward.</p>","es":"<p>Parte de la brecha es un mecanismo genuino, y parte es una ilusión bien conocida. Ser claro sobre ambas es esencial, porque este es exactamente el número al que la gente está más tentada a sobre-confiar.</p><p><b>El mecanismo real</b>. Históricamente, las lecturas de bajo riesgo se han agrupado alrededor de los mínimos de ciclo, cuando Bitcoin estaba barato. Concentrar compras en esas ventanas significa comprar más Bitcoin por dólar, lo que baja tu cost-basis promedio y, dado el largo rumbo ascendente de Bitcoin hasta ahora, termina en más monedas y mayor valor. Saltarse los períodos históricamente sobrevalorados evita comprar cerca de tops locales. Esa es una ventaja legítima si la señal realmente identifica períodos baratos.</p><p><b>Por qué la brecha está sobreestimada</b>. Varias advertencias honestas la reducen:</p><ul><li><b>Hindsight / ajuste dentro de la muestra</b>. Los niveles neutrales del modelo están informados por la misma historia en la que corre el backtest, así que la regla está siendo calificada parcialmente en el examen que estudió. Fuera de la muestra — en el futuro — la ventaja es muy probable que sea menor.</li><li><b>Arrastre de efectivo y costo de oportunidad</b>. Esperar lecturas de bajo riesgo puede significar estar en efectivo durante largos tramos durante los cuales el precio sube. Los backtests idealizados a menudo subestiman este arrastre y la disciplina que demanda.</li><li><b>Un activo, un largo rumbo ascendente</b>. El resultado se apoya en la trayectoria histórica específica de Bitcoin; un activo que no siguiera haciendo máximos de ciclo más altos recompensaría \"compra la caída\" mucho menos.</li><li><b>Fricciones e impuestos</b>. Las comisiones reales, spreads y (especialmente) impuestos no son tus cifras personales en un backtest genérico (Q22), y erosionan las ventajas.</li></ul><p>Así que la lectura correcta es: la estrategia de bajo riesgo tiene una ventaja plausible e intuitiva, pero el tamaño llamativo de la brecha histórica la halaga. Trata el backtest como evidencia de que inclinarte hacia períodos baratos es razonable, no como una promesa del mismo margen hacia adelante.</p>"}},{"n":"22","q":{"en":"22. Does the backtest engine include realistic trading fees, withdrawal costs, or tax implications?","es":"22. ¿Incluye el motor de backtest comisiones de trading realistas, costos de retiro o implicaciones fiscales?"},"a":{"en":"<p>The backtest is built to <b>isolate the effect of the buy-timing rule</b>, so its results are best read as <b>gross of your personal costs and taxes</b> unless the live tool states otherwise. This is an important honesty point, because omitted frictions always make any strategy look a little better than lived experience.</p> <ul> <li><b>Trading fees and spreads.</b> Check the assumptions shown alongside the live backtest for how fees are treated. Crucially, both strategies being compared are <i>buying</i> the same total capital, so a flat percentage fee affects them similarly and <b>largely cancels in the comparison</b> — it changes both ending values but not much the gap between them. Your real fees depend on your exchange and payment method.</li> <li><b>Withdrawal / on-chain costs.</b> Moving coins to self-custody carries network fees that a generic backtest does not know (they depend on how often you withdraw and network conditions). Budget for these yourself.</li> <li><b>Taxes.</b> Taxes are <b>not modelled</b>, and cannot be generically, because they are entirely personal — depending on your jurisdiction, holding period, income, and whether any disposals occur. A pure accumulation strategy may trigger little until you sell, but that is a matter for you and a qualified tax professional, not the backtester.</li> </ul> <p>The practical takeaway: use the backtest to compare <b>strategy against strategy</b>, where omitted costs mostly wash out, rather than as a forecast of your exact net return. Ending values are illustrative and pre-tax; your real outcome will be lower after fees and taxes, and those are yours to estimate for your own situation.</p>","es":"<p>El backtest está construido para aislar el efecto de la regla de timing de compra, así que sus resultados se leen mejor como brutos de tus costos y impuestos personales a menos que la herramienta en vivo indique lo contrario. Este es un punto de honestidad importante, porque las fricciones omitidas siempre hacen que cualquier estrategia se vea un poco mejor que la experiencia vivida.</p><ul><li><b>Comisiones de trading y spreads</b>. Revisa las suposiciones mostradas junto al backtest en vivo para cómo se tratan las comisiones. Crucialmente, ambas estrategias que se comparan están comprando el mismo capital total, así que una comisión de porcentaje plano las afecta de forma similar y se cancela en gran medida en la comparación — cambia ambos valores finales pero no mucho la brecha entre ellos. Tus comisiones reales dependen de tu exchange y método de pago.</li><li><b>Costos de retiro / on-chain</b>. Mover monedas a autocustodia conlleva fees de red que un backtest genérico no conoce (dependen de con qué frecuencia retiras y condiciones de red). Presupuesta para ellos tú mismo.</li><li><b>Impuestos</b>. Los impuestos no se modelan, y no pueden modelarse genéricamente, porque son enteramente personales — dependiendo de tu jurisdicción, período de tenencia, ingresos y si ocurren disposiciones. Una estrategia pura de acumulación puede activar poco hasta que vendas, pero eso es asunto tuyo y de un profesional fiscal cualificado, no del backtester.</li></ul><p>La conclusión práctica: usa el backtest para comparar estrategia contra estrategia, donde los costos omitidos mayormente se lavan, en lugar de como pronóstico de tu retorno neto exacto. Los valores finales son ilustrativos y pre-impuestos; tu resultado real será menor después de comisiones e impuestos, y esos son tuyos para estimar para tu propia situación.</p>"}},{"n":"23","q":{"en":"23. Can I change the risk threshold — for example, buy aggressively only when risk is under 0.25 — and immediately see updated backtest results?","es":"23. ¿Puedo cambiar el umbral de riesgo — por ejemplo, comprar agresivamente solo cuando el riesgo está bajo 0.25 — y ver inmediatamente resultados de backtest actualizados?"},"a":{"en":"<p><b>Yes.</b> The backtester is fully interactive and runs <b>in your browser</b>, so adjusting the parameters recomputes the results essentially instantly — no page reload, no server round-trip, no waiting. You can move the risk threshold (say, only buy when risk is below 0.25, or below 0.4, or scale buys smoothly across the range) and immediately watch how the ending Bitcoin held, average cost basis, and value respond.</p> <p>This immediacy is genuinely useful. It lets you build intuition for how <b>sensitive</b> the outcome is to the rule: whether the advantage is broad and robust across many thresholds, or whether it hinges on one narrow, suspiciously perfect setting. That sensitivity check is itself informative — a strategy that only shines at one exact threshold is far less trustworthy than one that helps across a wide band.</p> <div class=\"faq-note\"><b>A caution about tuning.</b>The flip side of easy experimentation is the temptation to <b>cherry-pick</b> the threshold that produced the best historical result and then believe the future will reward it identically. That is textbook overfitting — optimising to the past. Use the interactivity to find a threshold that is <i>reasonable and robust</i>, not the single most flattering one, and remember that whatever margin you see is an in-sample figure that will very likely be smaller going forward (Q21).</div> <p>Used in that spirit — as a way to understand behaviour rather than to mine for the prettiest number — the live threshold control is one of the most instructive parts of the dashboard.</p>","es":"<p>Sí. El backtester es totalmente interactivo y se ejecuta en tu navegador, así que ajustar los parámetros recalcula los resultados esencialmente al instante — sin recarga de página, sin viaje de ida y vuelta al servidor, sin espera. Puedes mover el umbral de riesgo (digamos, solo comprar cuando el riesgo está por debajo de 0.25, o por debajo de 0.4, o escalar compras suavemente a través del rango) y ver inmediatamente cómo responden el Bitcoin final retenido, el cost-basis promedio y el valor.</p><p>Esta inmediatez es genuinamente útil. Te permite construir intuición sobre qué tan <b>sensible</b> es el resultado a la regla: si la ventaja es amplia y robusta a través de muchos umbrales, o si depende de un ajuste estrecho, sospechosamente perfecto. Esa verificación de sensibilidad es en sí misma informativa — una estrategia que solo brilla en un umbral exacto es mucho menos confiable que una que ayuda a través de una banda amplia.</p><div class=\"faq-note\"><b>UNA ADVERTENCIA SOBRE EL AJUSTE.</b> El reverso de la experimentación fácil es la tentación de elegir selectivamente el umbral que produjo el mejor resultado histórico y luego creer que el futuro lo recompensará idénticamente. Eso es sobreajuste de manual — optimizar al pasado. Usa la interactividad para encontrar un umbral que sea razonable y robusto, no el único más halagador, y recuerda que cualquier margen que veas es una figura dentro de la muestra que muy probablemente será menor hacia adelante (Q21).</div><p>Usado en ese espíritu — como una forma de entender comportamiento en lugar de minar el número más bonito — el control de umbral en vivo es una de las partes más instructivas del panel.</p>"}},{"n":"24","q":{"en":"24. How far back does the reliable backtest data extend, and what caveats apply to the earliest years?","es":"24. ¿Qué tan atrás se extiende los datos confiables de backtest, y qué advertencias aplican a los años más tempranos?"},"a":{"en":"<p>The backtest draws on Bitcoin's <b>multi-cycle history</b> — the deep on-chain dataset stretches back to Bitcoin's early years in the <b>early 2010s</b>, which is what allows the tool to reason across several full boom-and-bust cycles. The exact starting point of any given run is shown on the dashboard, since it depends on when each required metric becomes available at usable quality.</p> <p>The earliest years, however, come with serious caveats, and they should be weighted accordingly:</p> <ul> <li><b>Thin, illiquid markets.</b> In Bitcoin's infancy, prices were set on tiny, fragmented venues with enormous spreads. A \"price\" from that era is far less meaningful than today's, and cost-basis ratios built on it are shakier.</li> <li><b>Extreme volatility and small sample.</b> Early moves of hundreds of percent can dominate a backtest and make any dip-buying rule look spectacular for reasons that will not recur at today's scale.</li> <li><b>Sparse and less certain on-chain data.</b> Some metrics are noisier or only approximate in the earliest period, and the proxy signals (Q12) are least reliable when the underlying behaviour data is thinnest.</li> <li><b>A different asset, effectively.</b> A micro-cap curiosity and a globally traded multi-hundred-billion-dollar asset behave differently; lessons from the former transfer imperfectly to the latter.</li> </ul> <p>The honest guidance is to treat the <b>recent, liquid, multi-cycle window</b> as the informative core of any backtest, and to view the earliest-era results as suggestive background rather than firm evidence. The tool includes the long history because context is valuable, but a headline number that leans heavily on 2011–2013 dynamics should be discounted, not taken at face value.</p>","es":"<p>El backtest se basa en la historia multi-ciclo de Bitcoin — el conjunto de datos on-chain profundo se extiende hasta los primeros años de Bitcoin a principios de los 2010s, lo que es lo que permite a la herramienta razonar a través de varios ciclos completos de auge y caída. El punto de inicio exacto de cualquier ejecución dada se muestra en el panel, ya que depende de cuándo cada métrica requerida se vuelve disponible con calidad utilizable.</p><p>Los años más tempranos, sin embargo, vienen con advertencias serias, y deben ponderarse en consecuencia:</p><ul><li><b>Mercados delgados e ilíquidos</b>. En la infancia de Bitcoin, los precios se establecían en mercados diminutos y fragmentados con spreads enormes. Un \"precio\" de esa era es mucho menos significativo que el de hoy, y los ratios de cost-basis construidos sobre él son más temblorosos.</li><li><b>Volatilidad extrema y muestra pequeña</b>. Movimientos tempranos de cientos de por ciento pueden dominar un backtest y hacer que cualquier regla de compra en caídas se vea espectacular por razones que no se repetirán a la escala de hoy.</li><li><b>Datos on-chain escasos y menos ciertos</b>. Algunas métricas son más ruidosas o solo aproximadas en el período más temprano, y las señales proxy (Q12) son menos confiables cuando los datos de comportamiento subyacentes son más delgados.</li><li><b>Un activo diferente, efectivamente</b>. Una curiosidad de micro-cap y un activo negociado globalmente de cientos de miles de millones de dólares se comportan de forma diferente; las lecciones del primero se transfieren imperfectamente al segundo.</li></ul><p>La guía honesta es tratar la ventana reciente, líquida y multi-ciclo como el núcleo informativo de cualquier backtest, y ver los resultados de la era más temprana como fondo sugerente más que evidencia firme. La herramienta incluye la historia larga porque el contexto es valioso, pero un número principal que se apoya fuertemente en dinámicas de 2011-2013 debe descontarse, no tomarse al pie de la letra.</p>"}}]},{"cat":{"en":"Forward Testing & Scenario Analysis","es":"Pruebas forward y análisis de escenarios"},"items":[{"n":"25","q":{"en":"25. What is the purpose of the Monte-Carlo forward-test simulations shown on the dashboard?","es":"25. ¿Cuál es el propósito de las simulaciones de forward-test Monte-Carlo mostradas en el panel?"},"a":{"en":"<p>Their purpose is to make <b>uncertainty visible</b> — to replace the false comfort of a single price forecast with an honest <b>fan of plausible futures</b>. Rather than claim to know where Bitcoin is going, the simulation shows the <i>range and shape</i> of where it could go under a set of assumptions you can see and adjust.</p> <p>A Monte-Carlo simulation works by generating <b>many randomised future price paths</b> — often thousands — each one a different sequence of ups and downs drawn to be statistically consistent with Bitcoin's historical return and volatility characteristics (adjusted by the chosen scenario). Because every run randomises the sequence of moves, no two paths are identical, and together they trace out a probability cloud: a median trajectory in the middle, and widening bands above and below that capture the more optimistic and more pessimistic outcomes.</p> <p>What this is genuinely good for:</p> <ul> <li><b>Calibrating expectations.</b> Seeing how enormously wide the cone of outcomes is — especially for a volatile asset — is a healthy antidote to anchoring on any single \"target price.\"</li> <li><b>Planning and stress-testing.</b> You can ask \"how would my accumulation plan feel along a bad path?\" and prepare emotionally and financially for drawdowns rather than being blindsided.</li> <li><b>Understanding dispersion.</b> The spread between the good and bad paths conveys risk far better than a point estimate ever could.</li> </ul> <p>The crucial framing, repeated deliberately: the simulation is a <b>what-if engine, not a forecaster</b>. It tells you what a range of futures <i>could</i> look like given assumptions — not what <i>will</i> happen. Read the paths as a structured way to think about uncertainty, and see Q26 and Q27 for the scenarios and for why these must never be treated as predictions.</p>","es":"<p>Su propósito es hacer visible la incertidumbre — reemplazar la falsa comodidad de un único pronóstico de precio con un abanico honesto de futuros plausibles. En lugar de afirmar saber hacia dónde va Bitcoin, la simulación muestra el rango y forma de dónde podría ir bajo un conjunto de suposiciones que puedes ver y ajustar.</p><p>Una simulación Monte-Carlo funciona generando muchos caminos de precio futuros aleatorizados — a menudo miles — cada uno una secuencia diferente de subidas y bajadas dibujada para ser estadísticamente consistente con las características históricas de retorno y volatilidad de Bitcoin (ajustadas por el escenario elegido). Porque cada ejecución aleatoriza la secuencia de movimientos, no hay dos caminos idénticos, y juntos trazan una nube de probabilidad: una trayectoria mediana en el medio, y bandas que se ensanchan arriba y abajo que capturan los resultados más optimistas y más pesimistas.</p><p>Para qué es genuinamente bueno esto:</p><ul><li><b>Calibrar expectativas</b>. Ver cuán enormemente ancho es el cono de resultados — especialmente para un activo volátil — es un antídoto saludable contra anclarse en cualquier \"precio objetivo\" único.</li><li><b>Planificar y hacer pruebas de estrés</b>. Puedes preguntar \"¿cómo se sentiría mi plan de acumulación a lo largo de un mal camino?\" y prepararte emocional y financieramente para drawdowns en lugar de ser sorprendido.</li><li><b>Entender la dispersión</b>. La separación entre los caminos buenos y malos transmite riesgo mucho mejor que una estimación puntual podría hacerlo.</li></ul><p>El encuadre crucial, repetido deliberadamente: la simulación es un motor de <b>qué-si</b>, no un pronosticador. Te dice qué podría parecer un rango de futuros dadas las suposiciones — no qué sucederá. Lee los caminos como una forma estructurada de pensar sobre la incertidumbre, y ve Q26 y Q27 para los escenarios y por qué estos nunca deben tratarse como predicciones.</p>"}},{"n":"26","q":{"en":"26. What do the five named macroeconomic scenarios (Hyperbitcoinization, Digital Gold, Base Case, Stagnation, Lost Decade) represent?","es":"26. ¿Qué representan los cinco escenarios macroeconómicos nombrados (Hiperbitcoinización, Oro Digital, Caso Base, Estancamiento, Década Perdida)?"},"a":{"en":"<p>Each named scenario is a <b>narrative assumption about Bitcoin's long-run adoption and return regime</b>, translated into different inputs (broadly, expected drift and volatility) for the Monte-Carlo engine. Instead of one anonymous set of assumptions, you get a spectrum of clearly labelled worldviews, from very bullish to bleak, so you can explore how the fan of outcomes changes as the story changes:</p> <ul> <li><b>Hyperbitcoinization</b> — the most bullish case: Bitcoin captures a large share of global monetary value, implying high long-run appreciation. The optimistic tail of the distribution.</li> <li><b>Digital Gold</b> — Bitcoin matures into a widely held store of value comparable to gold: strong but more moderate growth as it becomes established.</li> <li><b>Base Case</b> — a middle-of-the-road continuation, growth that neither assumes world-changing adoption nor collapse. A reasonable central reference.</li> <li><b>Stagnation</b> — adoption stalls and returns flatten: Bitcoin persists but largely trades sideways in real terms.</li> <li><b>Lost Decade</b> — the bearish case: a prolonged period of decline or malaise. The pessimistic tail, useful for stress-testing.</li> </ul> <p>The point of naming them is to make the assumptions <b>explicit and debatable</b>. Every projection of a volatile asset rests on a view of the future; hiding that view behind a single chart is misleading. Here the views are surfaced so you can choose the one you find credible — or, better, look at several and notice how sensitive the outcome is to which story you believe. Critically, the labels are <b>illustrative narratives, not calibrated probabilities</b>: the dashboard is not claiming that Hyperbitcoinization is X percent likely and Lost Decade Y percent. They are structured \"what ifs\" for thinking about a genuinely unknowable future, and Q27 makes that boundary explicit.</p>","es":"<p>Cada escenario nombrado es una suposición narrativa sobre el régimen de adopción y retorno de largo plazo de Bitcoin, traducida en diferentes entradas (ampliamente, drift esperado y volatilidad) para el motor Monte-Carlo.</p><p>En lugar de un conjunto anónimo de suposiciones, obtienes un espectro de visiones del mundo claramente etiquetadas, de muy alcista a sombría, para que puedas explorar cómo cambia el abanico de resultados a medida que cambia la historia:</p><ul><li><b>Hiperbitcoinización</b> — el caso más alcista: Bitcoin captura una gran parte del valor monetario global, implicando alta apreciación a largo plazo. La cola optimista de la distribución.</li><li><b>Oro Digital</b> — Bitcoin madura en una reserva de valor ampliamente tenida comparable al oro: crecimiento fuerte pero más moderado a medida que se establece.</li><li><b>Caso Base</b> — una continuación de medio camino, crecimiento que no asume adopción que cambie el mundo ni colapso. Una referencia central razonable.</li><li><b>Estancamiento</b> — la adopción se estanca y los retornos se aplanan: Bitcoin persiste pero en gran parte opera de lado en términos reales.</li><li><b>Década Perdida</b> — el caso bajista: un período prolongado de declive o malestar. La cola pesimista, útil para pruebas de estrés.</li></ul><p>El punto de nombrarlos es hacer las suposiciones <b>explícitas y debatibles</b>. Toda proyección de un activo volátil descansa en una visión del futuro; ocultar esa visión detrás de un gráfico único es engañoso. Aquí las visiones se sacan a la superficie para que puedas elegir la que encuentres creíble — o, mejor, mirar varias y notar qué tan sensible es el resultado a qué historia crees. Críticamente, las etiquetas son narrativas ilustrativas, <b>no probabilidades calibradas</b>: el panel no está afirmando que la Hiperbitcoinización tiene X por ciento de probabilidad y la Década Perdida Y por ciento. Son \"qué si\" estructurados para pensar en un futuro genuinamente desconocido, y Q27 hace explícito ese límite.</p>"}},{"n":"27","q":{"en":"27. Should users treat the simulated future price paths as predictions or purely as illustrative scenario analysis?","es":"27. ¿Deben los usuarios tratar los caminos de precio futuro simulados como predicciones o puramente como análisis de escenarios ilustrativos?"},"a":{"en":"<p><b>Purely as illustrative scenario analysis — never as predictions.</b> This is one of the most important cautions in the entire dashboard, and it is worth stating without any hedging: <b>nobody can predict Bitcoin's price</b>, and the simulations make no attempt to. They show what a <i>range</i> of futures could look like <i>if</i> a chosen set of assumptions held, not what the future <i>will</i> be.</p> <p>Several features of the tool are deliberately designed to prevent the \"prediction\" misreading:</p> <ul> <li>Outputs are shown as a <b>wide cone of many paths</b>, not a single confident line — the spread <i>is</i> the message.</li> <li>The assumptions are exposed as <b>named, swappable scenarios</b> (Q26), which advertises that the result is conditional on a story you selected, not an objective forecast.</li> <li>The paths are <b>randomised</b>; refreshing gives different specific trajectories, underlining that no individual path is meaningful on its own.</li> </ul> <p>Where they genuinely help is in <b>preparation, not prophecy</b>: understanding how brutal a bad path can feel, pressure- testing whether your plan survives a Lost-Decade-shaped stretch, and internalising just how wide the range of possibilities really is. Where they would harm you is if you screenshot the median line, treat it as a target, and size your finances around it. Use them to become more humble about the future and more robust to it — not more certain of it. If a projection ever tempts you toward certainty, that is precisely the moment to remember it is a simulation of assumptions, and to re-read the disclaimer.</p>","es":"<p>Puramente como análisis de escenarios ilustrativos — nunca como predicciones. Esta es una de las cautelas más importantes en todo el panel, y vale la pena declararla sin ninguna cobertura: nadie puede predecir el precio de Bitcoin, y las simulaciones no lo intentan. Muestran qué podría parecer un rango de futuros si se mantuviera un conjunto elegido de suposiciones, no qué será el futuro.</p><p>Varias características de la herramienta están diseñadas deliberadamente para prevenir la mala lectura de \"predicción\":</p><ul><li>Las salidas se muestran como un <b>cono ancho de muchos caminos</b>, no una línea única confiada — la dispersión es el mensaje.</li><li>Las suposiciones se exponen como escenarios nombrados e intercambiables (Q26), lo que anuncia que el resultado es condicional a una historia que seleccionaste, no un pronóstico objetivo.</li><li>Los caminos están aleatorizados; refrescar da trayectorias específicas diferentes, subrayando que ningún camino individual es significativo por sí solo.</li></ul><p>Donde genuinamente ayudan es en la <b>preparación</b>, no en la profecía: entender qué tan brutal puede sentirse un mal camino, hacer pruebas de presión sobre si tu plan sobrevive a un tramo con forma de Década Perdida, e internalizar cuán ancho es realmente el rango de posibilidades. Donde te harían daño es si capturas de pantalla la línea mediana, la tratas como objetivo y dimensionas tus finanzas alrededor de ella. Úsalos para volverte más humilde sobre el futuro y más robusto a él — no más seguro de él. Si una proyección alguna vez te tienta hacia la certeza, ese es precisamente el momento de recordar que es una simulación de suposiciones, y volver a leer el descargo.</p>"}},{"n":"28","q":{"en":"28. How are correlations between Bitcoin price and on-chain metrics incorporated into the stochastic model?","es":"28. ¿Cómo se incorporan las correlaciones entre el precio de Bitcoin y las métricas on-chain en el modelo estocástico?"},"a":{"en":"<p>The forward simulation tries to keep the <b>on-chain picture internally consistent with the price path it is imagining</b>, rather than letting price and fundamentals wander off independently. In reality, hashrate, active addresses, transaction activity, and cost-basis ratios do not move in isolation from price — they tend to co-move with it — so a simulation that ignored those relationships would produce incoherent futures (for example, a collapsing price alongside a serenely unchanged valuation).</p> <p>The most consequential piece of this is that the <b>projected risk score is coupled to the projected price</b> instead of being held flat. This matters because a flat-valuation projection would be nonsensical: it would imply that no matter how far price moved, the model considered Bitcoin equally cheap or expensive. By linking valuation to the simulated price, the forward risk becomes <b>expressive and consistent</b> — a simulated deep crash drives the projected risk toward the <i>low</i> (cheap) end of the range, while a simulated euphoric melt-up drives it toward the <i>high</i> (stretched) end, exactly as the live model would read those conditions today. The whole span of the risk scale is available along the paths, which is what makes the forward view believable.</p> <p>Two honest qualifiers apply. First, the co-movement relationships are <b>estimated from history</b>, and historical correlations are not guarantees — relationships can weaken or shift, which is a general limitation of any stochastic model. Second, this is a <b>deliberate simplification</b>: it captures the first-order fact that price and its on-chain context travel together, without pretending to model every feedback loop in the network. The goal is coherence and realism in the scenario analysis, not a claim to have captured the true joint dynamics of the market — and, as with everything in this section, the output remains illustrative rather than predictive.</p>","es":"<p>La simulación forward intenta mantener la imagen on-chain internamente consistente con el camino de precio que está imaginando, en lugar de dejar que el precio y los fundamentales vaguen independientemente. En realidad, hashrate, direcciones activas, actividad de transacciones y ratios de cost-basis no se mueven aislados del precio — tienden a moverse junto con él — así que una simulación que ignorara esas relaciones produciría futuros incoherentes (por ejemplo, un precio colapsando junto a una valoración serenamente sin cambios).</p><p>La pieza más consecuente de esto es que la <b>puntuación de riesgo proyectada está acoplada al precio proyectado</b> en lugar de mantenerse plana. Esto importa porque una proyección de valoración plana sería sin sentido: implicaría que sin importar cuánto se moviera el precio, el modelo consideraría Bitcoin igualmente barato o caro. Al vincular la valoración al precio simulado, el riesgo forward se vuelve expresivo y consistente — un crash profundo simulado impulsa el riesgo proyectado hacia el extremo bajo (barato) del rango, mientras que un melt-up eufórico simulado lo impulsa hacia el extremo alto (sobrevalorado), exactamente como el modelo en vivo leería esas condiciones hoy. Todo el span de la escala de riesgo está disponible a lo largo de los caminos, lo que es lo que hace creíble la vista forward.</p><p>Dos calificadores honestos aplican. Primero, las relaciones de co-movimiento se estiman de la historia, y las correlaciones históricas no son garantías — las relaciones pueden debilitarse o cambiar, que es una limitación general de cualquier modelo estocástico. Segundo, esta es una simplificación deliberada: captura el hecho de primer orden de que el precio y su contexto on-chain viajan juntos, sin pretender modelar cada bucle de retroalimentación en la red. El objetivo es coherencia y realismo en el análisis de escenarios, no una afirmación de haber capturado las verdaderas dinámicas conjuntas del mercado — y, como con todo en esta sección, la salida permanece ilustrativa más que predictiva.</p>"}}]},{"cat":{"en":"Dashboard Interface & Features","es":"Interfaz del panel y características"},"items":[{"n":"29","q":{"en":"29. What practical advantages does the logarithmic price scale offer compared with the linear scale on the main historical chart?","es":"29. ¿Qué ventajas prácticas ofrece la escala de precio logarítmica comparada con la escala lineal en el gráfico histórico principal?"},"a":{"en":"<p>For an asset like Bitcoin, whose price has spanned several <b>orders of magnitude</b> — from cents to tens of thousands of dollars — a logarithmic scale is not a stylistic preference but close to a necessity for seeing anything useful.</p> <p>The core advantage is that a log scale shows <b>equal percentage moves as equal vertical distances</b>. A move from 1 to 2 (a doubling) looks the same size as a move from 10,000 to 20,000 (also a doubling). That is exactly how a long-term holder experiences returns — in percentages, not dollars — so the chart matches the thing you actually care about.</p> <p>Concretely this means:</p> <ul> <li><b>Early history stays visible.</b> On a linear scale, everything before the last major bull run is crushed into a flat line near zero, and years of price action vanish. A log scale keeps early cycles legible and comparable.</li> <li><b>Trends and relative moves become clear.</b> Percentage-based structure — the rhythm of cycles, the slope of the long-run trend — is readable, and log-regression style channels become meaningful.</li> <li><b>Drawdowns are seen in proportion.</b> A 50 percent fall looks equally severe whether it happens at low or high prices, which is the honest way to compare them.</li> </ul> <p>A linear scale is not useless — it can dramatise the sheer dollar magnitude of recent moves, which is occasionally the point — but for understanding Bitcoin's history and placing today in cycle context, log is the default that avoids distortion. The dashboard offers both so you can switch, but the analytical work of comparing eras is what the log scale is built for.</p>","es":"<p>Para un activo como Bitcoin, cuyo precio ha abarcado varios órdenes de magnitud — de centavos a decenas de miles de dólares — una escala logarítmica no es una preferencia estilística sino cercana a una necesidad para ver algo útil.</p><p>La ventaja central es que una escala log muestra movimientos de porcentaje iguales como distancias verticales iguales. Un movimiento de 1 a 2 (una duplicación) se ve del mismo tamaño que un movimiento de 10,000 a 20,000 (también una duplicación). Eso es exactamente cómo un holder a largo plazo experimenta los retornos — en porcentajes, no en dólares — así que el gráfico coincide con lo que realmente te importa.</p><p>Concretamente esto significa:</p><ul><li><b>La historia temprana sigue visible</b>. En una escala lineal, todo antes de la última gran corrida alcista queda aplastado en una línea plana cerca de cero, y años de acción de precio desaparecen. Una escala log mantiene los ciclos tempranos legibles y comparables.</li><li><b>Las tendencias y movimientos relativos se vuelven claros</b>. La estructura basada en porcentajes — el ritmo de los ciclos, la pendiente de la tendencia de largo plazo — es legible, y los canales estilo regresión log se vuelven significativos.</li><li><b>Los drawdowns se ven en proporción</b>. Una caída del 50% se ve igualmente severa ocurra a precios bajos o altos, que es la forma honesta de compararlos.</li></ul><p>Una escala lineal no es inútil — puede dramatizar la magnitud en dólares pura de movimientos recientes, que ocasionalmente es el punto — pero para entender la historia de Bitcoin y situar hoy en contexto de ciclo, log es el default que evita distorsión. El panel ofrece ambas para que puedas cambiar, pero el trabajo analítico de comparar eras es para lo que está construida la escala log.</p>"}},{"n":"30","q":{"en":"30. How can the Risk–Price Matrix be used to set sensible limit buy orders at different risk levels?","es":"30. ¿Cómo puede usarse la Matriz Riesgo-Precio para establecer órdenes de compra límite sensatas en diferentes niveles de riesgo?"},"a":{"en":"<p>The Risk–Price Matrix bridges the two languages you care about: it maps <b>risk levels to approximate price levels</b> given the model's current state. Since the model's verdict ultimately reflects price relative to its on-chain context, you can ask the inverse question — \"at what price would today's model read a risk of, say, 0.3?\" — and get a concrete number to act on.</p> <p>That makes it a natural tool for <b>limit orders</b>. If your plan is to buy more aggressively whenever risk is at or below a chosen band, the matrix translates that band into a price zone, and you can place resting limit buys there rather than watching the chart. It turns an abstract intention (\"accumulate when historically cheap\") into an executable instruction (\"bid at these prices\").</p> <div class=\"faq-note\"><b>Important nuance.</b>The mapping is <b>not fixed</b>. Because the on-chain inputs update daily, the price that corresponds to a given risk level <b>drifts over time</b> — as realised value, miner economics, and demand evolve, the same price can imply a different risk tomorrow than it does today. A \"risk 0.3 price\" is a snapshot, not a permanent line.</div> <p>So the sensible workflow is: use the matrix to set limit orders as <b>living guidance</b>, and refresh it periodically (the daily update is a good rhythm) rather than setting a bid once and forgetting the assumptions behind it. Used that way — as a regularly updated translator between risk bands and prices — it is one of the most directly actionable features for a disciplined accumulator, while remaining, like everything here, an input to your own plan rather than an instruction.</p>","es":"<p>La Matriz Riesgo-Precio conecta los dos lenguajes que te importan: mapea niveles de riesgo a niveles de precio aproximados dado el estado actual del modelo. Dado que el veredicto del modelo en última instancia refleja el precio relativo a su contexto on-chain, puedes hacer la pregunta inversa — \"¿a qué precio leería el modelo de hoy un riesgo de, digamos, 0.3?\" — y obtener un número concreto sobre el que actuar.</p><p>Eso la convierte en una herramienta natural para órdenes límite. Si tu plan es comprar más agresivamente siempre que el riesgo esté en o por debajo de una banda elegida, la matriz traduce esa banda en una zona de precio, y puedes colocar compras límite en reposo allí en lugar de vigilar el gráfico. Convierte una intención abstracta (\"acumular cuando históricamente barato\") en una instrucción ejecutable (\"puja en estos precios\").</p><div class=\"faq-note\"><b>MATIZ IMPORTANTE.</b> El mapeo no es fijo. Porque las entradas on-chain se actualizan diariamente, el precio que corresponde a un nivel de riesgo dado deriva con el tiempo — a medida que el valor realizado, la economía de mineros y la demanda evolucionan, el mismo precio puede implicar un riesgo diferente mañana que hoy. Un \"precio de riesgo 0.3\" es una instantánea, no una línea permanente.</div><p>Así que el flujo de trabajo sensato es: usa la matriz para establecer órdenes límite como <b>guía viva</b>, y refresca periódicamente (la actualización diaria es un buen ritmo) en lugar de establecer una puja una vez y olvidar las suposiciones detrás de ella. Usada de esa forma — como un traductor regularmente actualizado entre bandas de riesgo y precios — es una de las características más directamente accionables para un acumulador disciplinado, mientras permanece, como todo aquí, una entrada a tu propio plan en lugar de una instrucción.</p>"}},{"n":"31","q":{"en":"31. What is the real-world decision-making value of the displayed 7-day and 30-day risk ranges?","es":"31. ¿Cuál es el valor real de toma de decisiones de los rangos de riesgo de 7 y 30 días mostrados?"},"a":{"en":"<p>A single day's risk score is a snapshot; the <b>7-day and 30-day ranges</b> add the missing dimension — <b>direction and recent variability</b> — which is often what actually informs a decision. They show the minimum and maximum the score has touched over those windows, so you can see not just where risk is, but where it has been and how quickly it is moving.</p> <p>Practically, this helps in a few ways:</p> <ul> <li><b>Trend awareness.</b> If today's reading sits at the top of its 30-day range, risk is rising; if it sits at the bottom, risk is cooling. That momentum context shapes whether \"0.6\" feels like it is heading toward stretched or relaxing back toward neutral.</li> <li><b>Perspective on a single print.</b> Seeing that today is well within its recent band discourages overreacting to one day's number, while a reading that has broken clearly outside its recent range is a genuine signal worth noticing.</li> <li><b>A sense of signal volatility.</b> A wide range means conditions are shifting fast; a tight range means the regime is stable. Both are useful for deciding how urgently, if at all, to adjust your buying.</li> </ul> <p>In short, the ranges convert a static reading into a small story about <b>trajectory</b>. For a DCA investor who is adjusting buy intensity rather than making snap trades, knowing that risk is low <i>and falling</i> — or high <i>and still climbing</i> — is more decision-relevant than the bare level alone. They are a lightweight way to answer \"is this a blip or a move?\" before you act.</p>","es":"<p>Una puntuación de riesgo de un solo día es una instantánea; los rangos de 7 y 30 días añaden la dimensión faltante — <b>dirección y variabilidad reciente</b> — que es a menudo lo que realmente informa una decisión. Muestran el mínimo y máximo que la puntuación ha tocado en esas ventanas, así que puedes ver no solo dónde está el riesgo, sino dónde ha estado y qué tan rápido se está moviendo.</p><p>Prácticamente, esto ayuda de varias maneras:</p><ul><li><b>Conciencia de tendencia</b>. Si la lectura de hoy se sitúa en la parte superior de su rango de 30 días, el riesgo está subiendo; si se sitúa en la parte inferior, el riesgo se está enfriando. Ese contexto de momentum moldea si un \"0.6\" se siente como si estuviera dirigiéndose hacia sobrevalorado o relajándose de vuelta a neutral.</li><li><b>Perspectiva sobre una impresión única</b>. Ver que hoy está bien dentro de su banda reciente desalienta sobre-reaccionar a un número de un día, mientras que una lectura que ha roto claramente fuera de su rango reciente es una señal genuina que vale la pena notar.</li><li><b>Un sentido de volatilidad de señal</b>. Un rango ancho significa que las condiciones están cambiando rápido; un rango estrecho significa que el régimen es estable. Ambos son útiles para decidir qué tan urgentemente, si es que lo haces, ajustar tus compras.</li></ul><p>En resumen, los rangos convierten una lectura estática en una pequeña historia sobre trayectoria. Para un inversor DCA que está ajustando la intensidad de compra en lugar de hacer trades rápidos, saber que el riesgo está bajo y cayendo — o alto y todavía subiendo — es más relevante para la decisión que el nivel desnudo solo. Son una forma ligera de responder \"¿es esto un bache o un movimiento?\" antes de actuar.</p>"}},{"n":"32","q":{"en":"32. Is the full dashboard — including the interactive backtest and Monte-Carlo simulations — fully usable on mobile phones and tablets?","es":"32. ¿Es el panel completo — incluyendo el backtest interactivo y las simulaciones Monte-Carlo — totalmente usable en teléfonos móviles y tabletas?"},"a":{"en":"<p><b>Yes.</b> The dashboard is built as a responsive web app, and because the heavy lifting (charts, backtests, and simulations) runs <b>in the browser</b>, all of it works on phones and tablets without any separate app to install. You can open the site on a phone, read today's risk and confidence, run the interactive backtest, adjust thresholds, and view the Monte-Carlo cone — the full analytical toolkit travels with you.</p> <p>An honest, small caveat about ergonomics rather than capability: some of the richer visualisations — a dense multi-cycle log chart, the Risk–Price Matrix, or a wide fan of simulated paths — are simply <b>easier to read and manipulate on a larger screen</b>, where there is more room for detail and fine adjustments. Everything remains usable on a small screen; a few things are just more comfortable on a tablet or desktop. The charting library supports touch interactions (pan, zoom, tap for values), so exploration on mobile is genuinely functional, not a cut-down placeholder. For a quick daily check the phone is perfect; for a deep session of threshold experimentation, a bigger display is a nicety, not a requirement.</p>","es":"<p>Sí. El panel está construido como una aplicación web responsiva, y porque el trabajo pesado (gráficos, backtests y simulaciones) se ejecuta en el navegador, todo funciona en teléfonos y tabletas sin ninguna app separada que instalar. Puedes abrir el sitio en un teléfono, leer el riesgo y confianza de hoy, ejecutar el backtest interactivo, ajustar umbrales y ver el cono Monte-Carlo — todo el conjunto de herramientas analíticas viaja contigo.</p><p>Una advertencia honesta, pequeña, sobre ergonomía más que capacidad: algunas de las visualizaciones más ricas — un gráfico log denso multi-ciclo, la Matriz Riesgo-Precio, o un abanico ancho de caminos simulados — son simplemente más fáciles de leer y manipular en una pantalla más grande, donde hay más espacio para detalle y ajustes finos. Todo sigue siendo usable en una pantalla pequeña; algunas cosas son simplemente más cómodas en una tableta o escritorio. La biblioteca de gráficos soporta interacciones táctiles (pan, zoom, tap para valores), así que la exploración en móvil es genuinamente funcional, no un placeholder recortado. Para una revisión diaria rápida el teléfono es perfecto; para una sesión profunda de experimentación con umbrales, una pantalla más grande es un lujo, no un requisito.</p>"}},{"n":"33","q":{"en":"33. Are there options to export the risk time series, backtest results, or high-resolution chart images for personal records?","es":"33. ¿Hay opciones para exportar la serie temporal de riesgo, resultados de backtest o imágenes de gráficos de alta resolución para registros personales?"},"a":{"en":"<p>Partly yes, with one very natural route and one that depends on the specific feature. Here is the honest, precise picture:</p> <ul> <li><b>High-resolution chart images.</b> The charts are rendered with Plotly, which provides a built-in toolbar that lets you <b>download the current chart as an image (PNG)</b> directly, plus pan and zoom to frame exactly what you want first. So saving a clean picture of the risk chart for your records works out of the box.</li> <li><b>The underlying risk time series.</b> Because the site publishes its data as a static file (<code>data.json</code> / <code>data.js</code>) served alongside the page, the risk history is effectively <b>downloadable and machine-readable</b> already — you can fetch that file to get the series. The honest caveat is that this is the project's <i>internal</i> data format, intended for the site itself, so its structure may change without notice; it is a de-facto export rather than a formally guaranteed one.</li> <li><b>Backtest results.</b> A dedicated one-click CSV export of a specific backtest run is the kind of convenience that may or may not be present as a button; where it is not, you can reproduce and record results by re-running your chosen parameters, and by saving a chart image of the outcome.</li> </ul> <p>So: chart images are easy, the raw series is obtainable via the published data file, and a polished, formally supported export (tidy CSV of the series and of backtest runs, with a stable schema) is a sensible enhancement on the roadmap rather than something this document should overstate as already finished. If a stable data export matters to your workflow, it is worth flagging as a feature request.</p>","es":"<p>Parcialmente sí, con una ruta muy natural y otra que depende de la característica específica. Aquí está el panorama honesto y preciso:</p><ul><li><b>Imágenes de gráficos de alta resolución</b>. Los gráficos se renderizan con Plotly, que proporciona una barra de herramientas integrada que te permite descargar el gráfico actual como imagen (PNG) directamente, más pan y zoom para encuadrar exactamente lo que quieres primero. Así que guardar una imagen limpia del gráfico de riesgo para tus registros funciona de fábrica.</li><li><b>La serie temporal de riesgo subyacente</b>. Porque el sitio publica sus datos como un archivo estático (data.json / data.js) servido junto a la página, la historia de riesgo es efectivamente descargable y legible por máquina ya — puedes obtener ese archivo para conseguir la serie. La advertencia honesta es que este es el formato de datos interno del proyecto, pensado para el sitio mismo, así que su estructura puede cambiar sin aviso; es una exportación de facto más que una garantizada formalmente.</li><li><b>Resultados de backtest</b>. Una exportación CSV dedicada de un clic de una ejecución específica de backtest es el tipo de conveniencia que puede o no estar presente como botón; donde no lo está, puedes reproducir y registrar resultados re-ejecutando tus parámetros elegidos, y guardando una imagen de gráfico del resultado.</li></ul><p>Así que: las imágenes de gráficos son fáciles, la serie cruda es obtenible vía el archivo de datos publicado, y una exportación pulida y formalmente soportada (CSV ordenado de la serie y de ejecuciones de backtest, con un esquema estable) es una mejora sensata en el roadmap más que algo que este documento deba sobrestimar como ya terminado. Si una exportación de datos estable importa a tu flujo de trabajo, vale la pena marcarlo como solicitud de característica.</p>"}}]},{"cat":{"en":"Subscription & Email Alerts","es":"Suscripción y alertas por correo electrónico"},"items":[{"n":"34","q":{"en":"34. What are the three available subscription modes (time-based digest, price-triggered, and strategy-based alerts)?","es":"34. ¿Cuáles son los tres modos de suscripción disponibles (resumen basado en tiempo, activado por precio y alertas basadas en estrategia)?"},"a":{"en":"<p>The optional email service offers three ways to be kept informed, so you can pick the one that matches how you want to engage rather than checking the site manually:</p> <ul> <li><b>Time-based digest.</b> A regular summary — delivered on a set schedule — of the current risk score, confidence, price, and recent context, sent regardless of whether anything dramatic has happened. This suits someone who just wants a dependable periodic pulse without watching the dashboard.</li> <li><b>Price-triggered.</b> A notification sent when Bitcoin's price crosses a level you specify. This suits someone anchored to particular price zones — for instance, \"let me know if we revisit a level I would like to buy.\"</li> <li><b>Strategy-based.</b> A notification tied to a <i>risk</i> or strategy condition rather than a raw price — for example, \"tell me when risk falls into my accumulation band.\" This is the mode most aligned with the dashboard's core idea of acting on historically cheap or stretched conditions.</li> </ul> <p>You can configure the specifics of each (see Q36), so the modes are templates you tailor, not fixed presets. One honest and important detail ties all three together: conditions are checked on the <b>daily data-refresh cadence</b>, so these are <b>daily-resolution</b> alerts, not tick-by-tick intraday triggers. In practice that means you are reliably told when a condition is met on the daily update, rather than within seconds of an intraday spike — a distinction spelled out fully in Q39. For the cycle-timescale decisions this tool is built for, daily resolution is well matched; if you need instant intraday alerts, that is a different tool for a different purpose.</p>","es":"<p>El servicio opcional de correo electrónico ofrece tres formas de mantenerse informado, para que puedas elegir la que coincida con cómo quieres interactuar en lugar de comprobar el sitio manualmente:</p><ul><li><b>Resumen basado en tiempo</b>. Un resumen regular — entregado en un horario establecido — de la puntuación de riesgo actual, confianza, precio y contexto reciente, enviado independientemente de si ha pasado algo dramático. Esto conviene a alguien que simplemente quiere un pulso periódico confiable sin vigilar el panel.</li><li><b>Activado por precio</b>. Una notificación enviada cuando el precio de Bitcoin cruza un nivel que especificas. Esto conviene a alguien anclado a zonas de precio particulares — por ejemplo, \"avísame si revisamos un nivel en el que me gustaría comprar\".</li><li><b>Basado en estrategia</b>. Una notificación vinculada a una condición de riesgo o estrategia en lugar de un precio crudo — por ejemplo, \"avísame cuando el riesgo caiga en mi banda de acumulación\". Este es el modo más alineado con la idea central del panel de actuar sobre condiciones históricamente baratas o sobrevaloradas.</li></ul><p>Puedes configurar los detalles específicos de cada uno (ver Q36), así que los modos son plantillas que adaptas, no presets fijos. Un detalle honesto e importante une a los tres: las condiciones se verifican en el ritmo de actualización diaria de datos, así que estas son alertas de resolución diaria, no disparadores intradía tick por tick. En la práctica eso significa que se te informa confiablemente cuando una condición se cumple en la actualización diaria, en lugar de dentro de segundos de un pico intradía — una distinción detallada completamente en Q39. Para las decisiones a escala de ciclo para las que esta herramienta está construida, la resolución diaria está bien emparejada; si necesitas alertas intradía instantáneas, esa es una herramienta diferente para un propósito diferente.</p>"}},{"n":"35","q":{"en":"35. How does the double opt-in confirmation email work, and why is it used?","es":"35. ¿Cómo funciona el correo electrónico de confirmación de doble opt-in, y por qué se usa?"},"a":{"en":"<p>Double opt-in is a two-step sign-up that confirms you genuinely want the emails before any are sent. The flow is simple:</p> <ul> <li>you enter your email address and choose a mode on the site;</li> <li>the system sends a single <b>confirmation email</b> to that address containing a unique confirm link;</li> <li>you click the link, which <b>activates</b> the subscription; only then does your address become an active recipient.</li> </ul> <p>Until that link is clicked, nothing further is sent. This matters for several reasons, all of which protect you:</p> <ul> <li><b>Proof of ownership.</b> It verifies that the person subscribing actually controls the inbox, so <b>nobody can sign you up without your consent</b> — a common form of harassment with single-step forms.</li> <li><b>Spam and abuse prevention.</b> It stops the service from being used to blast confirmation mail at addresses that never asked for it.</li> <li><b>Deliverability.</b> Confirmed, engaged lists have far better inbox placement, so your alerts are less likely to be marked as spam or silently dropped.</li> <li><b>Clean consent.</b> It is the widely recognised best practice for permission-based email and aligns with modern privacy expectations.</li> </ul> <p>In short, double opt-in is a small extra click that buys real protection — for you against unwanted sign-ups, and for the service against being abused. If you ever submit an address and no alerts arrive, the first thing to check is whether that initial confirmation email was clicked (and your spam folder), because an unconfirmed subscription intentionally stays silent.</p>","es":"<p>El doble opt-in es un registro de dos pasos que confirma que genuinamente quieres los correos antes de que se envíe ninguno. El flujo es simple:</p><ul><li>introduces tu dirección de correo y eliges un modo en el sitio;</li><li>el sistema envía un único correo de confirmación a esa dirección conteniendo un enlace de confirmación único;</li><li>haces clic en el enlace, que <b>activa</b> la suscripción; solo entonces tu dirección se convierte en un destinatario activo.</li></ul><p>Hasta que se hace clic en ese enlace, no se envía nada más. Esto importa por varias razones, todas las cuales te protegen:</p><ul><li><b>Prueba de propiedad</b>. Verifica que la persona que se suscribe realmente controla el buzón, así que nadie puede inscribirte sin tu consentimiento — una forma común de acoso con formularios de un solo paso.</li><li><b>Prevención de spam y abuso</b>. Impide que el servicio se use para bombardear correo de confirmación a direcciones que nunca lo pidieron.</li><li><b>Entregabilidad</b>. Las listas confirmadas y comprometidas tienen una colocación en el buzón mucho mejor, así que tus alertas son menos probables de marcarse como spam o caerse silenciosamente.</li><li><b>Consentimiento limpio</b>. Es la mejor práctica ampliamente reconocida para correo basado en permisos y se alinea con las expectativas modernas de privacidad.</li></ul><p>En resumen, el doble opt-in es un clic extra pequeño que compra protección real — para ti contra inscripciones no deseadas, y para el servicio contra ser abusado. Si alguna vez envías una dirección y no llegan alertas, la primera cosa que revisar es si ese correo de confirmación inicial fue cliqueado (y tu carpeta de spam), porque una suscripción no confirmada intencionalmente permanece silenciosa.</p>"}},{"n":"36","q":{"en":"36. Can I configure custom risk thresholds, specific Bitcoin price targets, or particular strategy rules for my personal alerts?","es":"36. ¿Puedo configurar umbrales de riesgo personalizados, objetivos de precio de Bitcoin específicos o reglas de estrategia particulares para mis alertas personales?"},"a":{"en":"<p><b>Yes — personalisation is the whole point of the alert modes.</b> Rather than receiving one generic notification, you set the parameters that matter to your plan, so the emails fire on <i>your</i> conditions:</p> <ul> <li><b>Custom risk thresholds.</b> For strategy-based alerts, you choose the risk band that triggers a message — for example, \"notify me when risk drops into my accumulation zone,\" with the boundary set where <i>you</i> consider Bitcoin historically attractive.</li> <li><b>Specific price targets.</b> For price-triggered alerts, you specify the Bitcoin price level(s) you care about, so you are told when the market reaches a zone you have in mind.</li> <li><b>Strategy rules.</b> You can align alerts with the way you intend to act on the signal, turning your accumulation plan into conditions the system watches for you.</li> </ul> <p>This means two subscribers can use the same service to receive quite different, individually relevant notifications. The honest caveat carried through this whole section applies here too: your conditions are evaluated on the <b>daily refresh</b> (Q39), so a threshold or price target is checked once per daily cycle rather than continuously. Set your levels with that cadence in mind — it is well suited to the multi-week decisions the tool targets, and it means you are alerted to a <i>condition being true</i> on a given day, not to the exact instant it first became true intraday.</p>","es":"<p>Sí — la personalización es todo el punto de los modos de alerta. En lugar de recibir una notificación genérica, estableces los parámetros que importan a tu plan, así que los correos se disparan en tus condiciones:</p><ul><li><b>Umbrales de riesgo personalizados</b>. Para alertas basadas en estrategia, eliges la banda de riesgo que activa un mensaje — por ejemplo, \"notifícame cuando el riesgo caiga en mi zona de acumulación\", con el límite establecido donde consideras Bitcoin históricamente atractivo.</li><li><b>Objetivos de precio específicos</b>. Para alertas activadas por precio, especificas el/los nivel(es) de precio de Bitcoin que te importan, así que se te avisa cuando el mercado alcanza una zona que tienes en mente.</li><li><b>Reglas de estrategia</b>. Puedes alinear las alertas con la forma en que pretendes actuar sobre la señal, convirtiendo tu plan de acumulación en condiciones que el sistema vigila por ti.</li></ul><p>Esto significa que dos suscriptores pueden usar el mismo servicio para recibir notificaciones bastante diferentes, individualmente relevantes. La advertencia honesta que recorre toda esta sección aplica aquí también: tus condiciones se evalúan en la actualización diaria (Q39), así que un umbral o objetivo de precio se verifica una vez por ciclo diario en lugar de continuamente. Establece tus niveles con ese ritmo en mente — está bien emparejado con las decisiones de varias semanas a las que apunta la herramienta, y significa que se te avisa de que una condición es verdadera en un día dado, no del instante exacto en que se volvió verdadera intradía.</p>"}},{"n":"37","q":{"en":"37. If I want to change my notification preferences or pause alerts temporarily, what is the easiest way to do so?","es":"37. Si quiero cambiar mis preferencias de notificación o pausar alertas temporalmente, ¿cuál es la forma más fácil de hacerlo?"},"a":{"en":"<p>The simplest route is the <b>management link included in every email you receive</b>. Rather than making you log into an account, each notification carries a link that lets you update your settings or stop the alerts — the standard, friction-free pattern for permission-based email.</p> <p>From there you can typically:</p> <ul> <li><b>Adjust your preferences</b> — change your mode, thresholds, or price targets if your plan has evolved;</li> <li><b>Pause or unsubscribe</b> — stop receiving alerts entirely when you want a break;</li> <li><b>Re-subscribe later</b> — sign up again through the site whenever you want them back (a fresh confirmation keeps things clean).</li> </ul> <p>Because there is no password-protected account, this link <i>is</i> your control panel, which keeps the whole system lightweight and privacy-friendly — the only thing the service holds is what you gave it, and you can change or remove it at any time from your own inbox. If you ever cannot find the link, unsubscribing from any single alert email and re-subscribing when ready is always a reliable fallback. The guiding intent is that opting out must be at least as easy as opting in — you are never locked in, and stepping away is a click, not a request.</p>","es":"<p>La ruta más simple es el enlace de gestión incluido en cada correo que recibes. En lugar de hacerte iniciar sesión en una cuenta, cada notificación lleva un enlace que te permite actualizar tus configuraciones o detener las alertas — el patrón estándar y sin fricción para correo basado en permisos.</p><p>Desde allí puedes típicamente:</p><ul><li><b>Ajustar tus preferencias</b> — cambiar tu modo, umbrales o objetivos de precio si tu plan ha evolucionado;</li><li><b>Pausar o dar de baja</b> — dejar de recibir alertas enteramente cuando quieras un descanso;</li><li><b>Volver a suscribirte después</b> — inscribirte de nuevo a través del sitio cuando quieras que vuelvan (una confirmación fresca mantiene las cosas limpias).</li></ul><p>Porque no hay cuenta protegida por contraseña, este enlace es tu panel de control, lo que mantiene todo el sistema ligero y amigable con la privacidad — lo único que el servicio guarda es lo que le diste, y puedes cambiarlo o eliminarlo en cualquier momento desde tu propio buzón. Si alguna vez no puedes encontrar el enlace, dar de baja desde cualquier correo de alerta individual y volver a suscribirte cuando estés listo es siempre una alternativa confiable. La intención rectora es que optar por salir debe ser al menos tan fácil como optar por entrar — nunca estás atrapado, y alejarte es un clic, no una solicitud.</p>"}},{"n":"38","q":{"en":"38. Exactly what subscriber data is stored, and is any of it ever sold or shared with third parties?","es":"38. ¿Exactamente qué datos de suscriptor se almacenan, y se vende o comparte alguno con terceros?"},"a":{"en":"<p>The service stores the <b>minimum needed to deliver the alerts you asked for</b>, and nothing about your finances or identity beyond an email address. Specifically:</p> <ul> <li><b>Your email address</b> — the delivery destination;</li> <li><b>Your chosen mode</b> — digest, price-triggered, or strategy-based;</li> <li><b>Your settings</b> — the thresholds, price targets, or strategy parameters you configured, plus the confirmation status that records you completed double opt-in.</li> </ul> <p>This is held in the project's subscriber database. Email delivery itself is handled by a reputable third-party email provider acting purely as a <b>processor</b> — it transmits your alerts on the service's behalf, which is normal and necessary to actually send mail reliably.</p> <div class=\"faq-note\"><b>On selling and sharing.</b>Your data is <b>not sold</b>, and it is <b>not shared with third parties</b> for their own purposes. It is used solely to operate the subscription you requested — to evaluate your conditions and send your notifications — and for nothing else. There is no advertising business attached to it.</div> <p>The design deliberately keeps the data footprint small precisely so there is little to misuse: no passwords, no browsing profiles, no financial details, no coin holdings — just an address and the alert preferences you set, which you can change or delete yourself at any time (Q37). Minimising what is collected is itself a privacy measure. For the authoritative, current wording, the site's own privacy statement governs; this answer describes the intent and practice in plain terms.</p>","es":"<p>El servicio almacena lo mínimo necesario para entregar las alertas que pediste, y nada sobre tus finanzas o identidad más allá de una dirección de correo. Específicamente:</p><ul><li>Tu dirección de correo — el destino de entrega;</li><li>Tu modo elegido — resumen, activado por precio o basado en estrategia;</li><li>Tus configuraciones — los umbrales, objetivos de precio o parámetros de estrategia que configuraste, más el estado de confirmación que registra que completaste el doble opt-in.</li></ul><p>Esto se guarda en la base de datos de suscriptores del proyecto. La entrega de correo en sí es manejada por un proveedor de correo electrónico de terceros reputado actuando puramente como procesador — transmite tus alertas en nombre del servicio, lo cual es normal y necesario para enviar correo confiablemente.</p><div class=\"faq-note\"><b>SOBRE VENDER Y COMPARTIR.</b> Tus datos <b>no se venden</b>, y <b>no se comparten con terceros</b> para sus propios propósitos. Se usan únicamente para operar la suscripción que solicitaste — para evaluar tus condiciones y enviar tus notificaciones — y para nada más. No hay negocio de publicidad adjunto a ello.</div><p>El diseño mantiene deliberadamente la huella de datos pequeña precisamente para que haya poco que pueda usarse indebidamente: no contraseñas, no perfiles de navegación, no detalles financieros, no tenencias de monedas — solo una dirección y las preferencias de alerta que estableciste, que puedes cambiar o eliminar tú mismo en cualquier momento (Q37). Minimizar lo que se recolecta es en sí mismo una medida de privacidad. Para la redacción autorizada y actual, la declaración de privacidad propia del sitio rige; esta respuesta describe la intención y práctica en términos claros.</p>"}},{"n":"39","q":{"en":"39. How quickly after a risk level, price condition, or strategy signal is triggered will I normally receive an email?","es":"39. ¿Qué tan rápido después de que se active un nivel de riesgo, condición de precio o señal de estrategia normalmente recibiré un correo?"},"a":{"en":"<p>Here is the straight, honest answer, because it is easy to assume \"alert\" means \"instant\" and that would be misleading: notifications are tied to the <b>daily data refresh (around 06:00 UTC)</b>. Each day, when the pipeline recomputes the risk score and updates the data, it evaluates subscriber conditions and dispatches the emails that qualify. So you can normally expect to be notified <b>within that daily cycle — shortly after the day's recompute detects your condition</b> — rather than within seconds or minutes of an intraday move.</p> <p>What this means in practice:</p> <ul> <li><b>Digest emails</b> arrive on their set schedule, as expected.</li> <li><b>Strategy (risk-based) alerts</b> are a natural fit for daily resolution, since the risk score itself updates once per day — there is no faster signal to react to.</li> <li><b>Price-triggered alerts</b> are the case where the daily cadence is most visible: if Bitcoin spikes through your price level and falls back <i>between</i> daily refreshes, the current system evaluates against the daily data rather than watching the live tape tick by tick. You are alerted to the condition on the daily cycle, not to a fleeting intraday wick.</li> </ul> <p>This is a deliberate consequence of the once-daily architecture that keeps the service simple, robust, and free. It is well matched to a tool about <b>cycle-scale</b> accumulation, where being told \"risk entered your band\" on the day is exactly what you need. <b>Near-real-time intraday triggering would require a higher-frequency job</b> and is a reasonable future enhancement — but it is honest to set expectations now: today's alerts operate on a daily heartbeat, not a live stream.</p>","es":"<p>Aquí está la respuesta directa y honesta, porque es fácil asumir que \"alerta\" significa \"instantánea\" y eso sería engañoso: las notificaciones están vinculadas a la <b>actualización diaria de datos</b> (alrededor de las 06:00 UTC). Cada día, cuando el pipeline recalcula la puntuación de riesgo y actualiza los datos, evalúa las condiciones de suscriptores y despacha los correos que califican. Así que normalmente puedes esperar ser notificado dentro de ese ciclo diario — poco después de que el recálculo del día detecte tu condición — en lugar de dentro de segundos o minutos de un movimiento intradía.</p><p>Lo que esto significa en la práctica:</p><ul><li>Los correos de resumen llegan en su horario establecido, como se espera.</li><li>Las alertas de estrategia (basadas en riesgo) encajan naturalmente con resolución diaria, ya que la puntuación de riesgo en sí se actualiza una vez al día — no hay señal más rápida a la que reaccionar.</li><li>Las alertas activadas por precio son el caso donde el ritmo diario es más visible: si Bitcoin sube a través de tu nivel de precio y cae de vuelta entre actualizaciones diarias, el sistema actual evalúa contra los datos diarios en lugar de vigilar la cinta en vivo tick por tick. Se te avisa de la condición en el ciclo diario, no de un wick intradía fugaz.</li></ul><p>Esto es una consecuencia deliberada de la arquitectura de una vez al día que mantiene el servicio simple, robusto y gratuito. Está bien emparejada con una herramienta sobre acumulación a escala de ciclo, donde ser avisado de que \"el riesgo entró en tu banda\" en el día es exactamente lo que necesitas. El disparo intradía casi en tiempo real requeriría un trabajo de mayor frecuencia y es una mejora futura razonable — pero es honesto establecer expectativas ahora: las alertas de hoy operan con un latido diario, no un flujo en vivo.</p>"}},{"n":"40","q":{"en":"40. Besides email, are there any plans to add Telegram, Discord, push notifications, or other delivery channels in the future?","es":"40. ¿Además del correo electrónico, hay planes para añadir Telegram, Discord, notificaciones push u otros canales de entrega en el futuro?"},"a":{"en":"<p><b>Email is the personal delivery channel today</b>, and it covers all three alert modes. There is also a <b>public account on X (Twitter)</b> that posts a daily risk update — including the current score, historical context, and a gauge image — which acts as a broadcast channel anyone can follow, though it is a public feed rather than a personalised alert tuned to your own thresholds.</p> <p>Beyond those, additional channels such as <b>Telegram, Discord, browser/push notifications, or webhooks</b> are <b>not currently offered</b>. They are, however, natural and frequently requested extensions, and the architecture — a daily job that already evaluates conditions and sends notifications — would lend itself to adding new delivery targets without changing the underlying logic.</p> <p>The honest position is to under-promise on timelines: these are sensible candidates for the roadmap rather than committed, dated features, and the same daily-cadence caveat (Q39) would apply to any of them under the current design. If a particular channel would materially improve how you use the tool — a Telegram bot for a community, say, or push alerts on mobile — saying so is genuinely useful input for prioritisation. For now, the reliable answer is: personalised alerts by email, plus a public daily post on X, with other channels an open possibility rather than a promise.</p>","es":"<p>El correo electrónico es el canal de entrega personal hoy, y cubre los tres modos de alerta. También hay una cuenta pública en X (Twitter) que publica una actualización diaria de riesgo — incluyendo la puntuación actual, contexto histórico y una imagen de gauge — que actúa como un canal de difusión que cualquiera puede seguir, aunque es un feed público más que una alerta personalizada ajustada a tus propios umbrales.</p><p>Más allá de esos, canales adicionales como Telegram, Discord, notificaciones push de navegador o webhooks <b>no se ofrecen actualmente</b>. Sin embargo, son extensiones naturales y frecuentemente solicitadas, y la arquitectura — un trabajo diario que ya evalúa condiciones y envía notificaciones — se prestaría a añadir nuevos objetivos de entrega sin cambiar la lógica subyacente.</p><p>La posición honesta es sub-prometer en plazos: estos son candidatos sensatos para el roadmap más que características comprometidas y fechadas, y la misma advertencia de ritmo diario (Q39) aplicaría a cualquiera de ellos bajo el diseño actual. Si un canal particular mejoraría materialmente cómo usas la herramienta — un bot de Telegram para una comunidad, digamos, o alertas push en móvil — decirlo es genuinamente útil como entrada para priorización. Por ahora, la respuesta confiable es: alertas personalizadas por correo electrónico, más una publicación diaria pública en X, con otros canales una posibilidad abierta más que una promesa.</p>"}}]},{"cat":{"en":"Technical Implementation","es":"Implementación técnica"},"items":[{"n":"41","q":{"en":"41. Which frontend technologies and JavaScript libraries power the live charts, interactive backtest engine, and in-browser Monte-Carlo simulations?","es":"41. ¿Qué tecnologías frontend y bibliotecas JavaScript impulsan los gráficos en vivo, el motor de backtest interactivo y las simulaciones Monte-Carlo en el navegador?"},"a":{"en":"<p>The dashboard is a <b>static web front end</b> — standard HTML, CSS, and JavaScript — served as static assets, with no backend server needed to view or interact with it. That architecture is what makes it fast, cheap to host, and login-free.</p> <ul> <li><b>Charts.</b> Interactive plotting is handled by <b>Plotly.js</b>, which provides the pan/zoom/hover behaviour, the log/linear toggle, and the built-in image export on the risk and price charts.</li> <li><b>Backtest engine and Monte-Carlo simulations.</b> These run <b>client-side in JavaScript</b>, computing directly in your browser on the data the page has already loaded. Keeping the computation in the browser is why parameter changes recompute instantly (Q23) and why there is nothing to gate behind an account.</li> <li><b>Presentation.</b> The interface uses the project's typographic system — <b>Space Grotesk</b> for display and body text, with <b>IBM Plex Mono</b> for data and figures — and is <b>fully bilingual (Spanish and English)</b>, with the two language versions kept in strict parity.</li> </ul> <p>The deliberate choice throughout is <b>simplicity and longevity</b>: a static site with in-browser computation has very few moving parts, no server to crash under load, and no per-user infrastructure cost, which is a good fit for a free public tool. It also means the whole client is inspectable — what runs in your browser is the actual logic, not a call to a hidden service. The only server-side component in the whole system is the small, separate machinery behind the optional email subscription (Q43), which is entirely decoupled from the analytical experience.</p>","es":"<p>El panel es un frontend web estático — HTML, CSS y JavaScript estándar — servido como activos estáticos, sin necesidad de servidor backend para ver o interactuar con él. Esa arquitectura es lo que lo hace rápido, barato de alojar y sin login.</p><ul><li><b>Gráficos</b>. El trazado interactivo es manejado por Plotly.js, que proporciona el comportamiento de pan/zoom/hover, el toggle log/lineal y la exportación de imagen integrada en los gráficos de riesgo y precio.</li><li><b>Motor de backtest y simulaciones Monte-Carlo</b>. Estos se ejecutan del lado del cliente en JavaScript, computando directamente en tu navegador en los datos que la página ya ha cargado. Mantener la computación en el navegador es por qué los cambios de parámetros recalculan instantáneamente (Q23) y por qué no hay nada que bloquear detrás de una cuenta.</li><li><b>Presentación</b>. La interfaz usa el sistema tipográfico del proyecto — Space Grotesk para display y texto de cuerpo, con IBM Plex Mono para datos y cifras — y es totalmente bilingüe (español e inglés), con las dos versiones de idioma mantenidas en paridad estricta.</li></ul><p>La elección deliberada a lo largo es <b>simplicidad y longevidad</b>: un sitio estático con computación en el navegador tiene muy pocas partes móviles, ningún servidor que caiga bajo carga y ningún costo de infraestructura por usuario, lo cual es un buen ajuste para una herramienta pública gratuita. También significa que todo el cliente es inspeccionable — lo que se ejecuta en tu navegador es la lógica real, no una llamada a un servicio oculto. El único componente del lado del servidor en todo el sistema es la pequeña maquinaria separada detrás de la suscripción opcional por correo electrónico (Q43), que está enteramente desacoplada de la experiencia analítica.</p>"}},{"n":"42","q":{"en":"42. How is the daily risk recalculation, data.json generation, and dashboard update automated?","es":"42. ¿Cómo se automatiza el recálculo diario de riesgo, la generación de data.json y la actualización del panel?"},"a":{"en":"<p>The daily update is fully automated through a <b>scheduled continuous-integration workflow</b> — a cron job running on <b>GitHub Actions</b> at around 06:00 UTC — so no human has to run anything for the dashboard to stay current. Each morning the workflow performs the full sequence end to end:</p> <ul> <li><b>Fetch</b> the latest price and on-chain data from the public sources (using the hybrid read described in Q15);</li> <li><b>Compute</b> the eleven signals, apply the logistic transforms, blend and lightly smooth the composite, and derive the confidence score and the recent ranges, via the project's Python risk model;</li> <li><b>Generate</b> the updated data file (<code>data.json</code> / <code>data.js</code>) that the static site reads;</li> <li><b>Publish</b> by committing the refreshed data to the project's repository, which the host picks up automatically.</li> </ul> <p>Deployment is <b>push-driven</b>: the site is hosted on <b>Cloudflare Pages</b>, which redeploys automatically whenever the repository updates, so the new data goes live without a manual publish step. The model code and pipeline live in a <b>private repository</b>, so the same reviewed code runs automatically each morning without any manual intervention.</p> <p>A safety rule is woven into this automation: if the freshest data point is more than a few days old, the pipeline <b>aborts</b> rather than publishing a stale reading (Q17, Q45). The net effect is a hands-off daily cycle that keeps the dashboard current on normal days and deliberately holds back on bad ones, with every step visible in the open repository and the workflow's run logs.</p>","es":"<p>La actualización diaria está totalmente automatizada a través de un flujo de trabajo de integración continua programado — un trabajo cron ejecutándose en GitHub Actions alrededor de las 06:00 UTC — así que ningún humano tiene que ejecutar nada para que el panel se mantenga actual. Cada mañana el flujo de trabajo realiza la secuencia completa de extremo a extremo:</p><ul><li>Extrae los últimos datos de precio y on-chain de las fuentes públicas (usando la lectura híbrida descrita en Q15);</li><li>Computa las once señales, aplica las transformaciones logísticas, combina y suaviza ligeramente el compuesto, y deriva la puntuación de confianza y los rangos recientes, vía el modelo de riesgo Python del proyecto;</li><li>Genera el archivo de datos actualizado (data.json / data.js) que lee el sitio estático;</li><li>Publica comprometiendo los datos refrescados al repositorio del proyecto, que el host recoge automáticamente.</li></ul><p>El despliegue es <b>impulsado por push</b>: el sitio está alojado en Cloudflare Pages, que redepliega automáticamente cada vez que el repositorio se actualiza, así que los nuevos datos van en vivo sin un paso de publicación manual. El código del modelo y el pipeline viven en un repositorio privado, así que el mismo código revisado se ejecuta automáticamente cada mañana sin ninguna intervención manual.</p><p>Una regla de seguridad está tejida en esta automatización: si el punto de datos más fresco tiene más de unos pocos días de antigüedad, el pipeline <b>aborta</b> en lugar de publicar una lectura obsoleta (Q17, Q45). El efecto neto es un ciclo diario manos libres que mantiene el panel actual en días normales y se retiene deliberadamente en los malos, con cada paso visible en el repositorio abierto y los registros de ejecución del flujo de trabajo.</p>"}},{"n":"43","q":{"en":"43. Which services handle the subscription database and reliable delivery of notification emails?","es":"43. ¿Qué servicios manejan la base de datos de suscriptores y la entrega confiable de correos de notificación?"},"a":{"en":"<p>Two focused, reputable services sit behind the optional email feature, cleanly separated from the analytical dashboard:</p> <ul> <li><b>Subscriber database — Supabase.</b> Subscriber records (email address, chosen mode, settings, and confirmation status) are stored in a hosted <b>Postgres</b> database provided by Supabase, accessed over its API. This holds the small amount of data described in Q38 and nothing more.</li> <li><b>Email delivery — Resend.</b> The actual sending of confirmation emails, digests, and triggered alerts is handled by <b>Resend</b>, a transactional email provider, sending from the project's own <b>verified sending domain</b>. Using a dedicated provider with a verified domain is what makes delivery reliable and keeps messages out of spam folders.</li> </ul> <p>The integration is intentionally lightweight and dependency-minimal on the project's side, and — importantly for security — any operations that touch the database from the server side use <b>appropriately scoped secret credentials that are never exposed to the browser</b>. Nothing about the subscriber store is reachable from the public front end; the analytical site and the subscription machinery are decoupled, so the login-free dashboard carries no user data at all.</p> <p>This separation is deliberate: the free, public, static dashboard has no server and no personal data, while the small piece of infrastructure that <i>does</i> handle personal data (an address and alert preferences) is isolated behind managed services built for exactly that job. It keeps the privacy surface small (Q38) and the reliability high, without entangling the two very different parts of the system.</p>","es":"<p>Dos servicios enfocados y reputados están detrás de la característica opcional de correo electrónico, limpiamente separados del panel analítico:</p><ul><li><b>Base de datos de suscriptores — Supabase</b>. Los registros de suscriptores (dirección de correo, modo elegido, configuraciones y estado de confirmación) se almacenan en una base de datos Postgres alojada proporcionada por Supabase, accedida a través de su API. Esto guarda la pequeña cantidad de datos descrita en Q38 y nada más.</li><li><b>Entrega de correo — Resend</b>. El envío real de correos de confirmación, resúmenes y alertas activadas es manejado por Resend, un proveedor de correo transaccional, enviando desde el dominio de envío verificado propio del proyecto. Usar un proveedor dedicado con dominio verificado es lo que hace la entrega confiable y mantiene los mensajes fuera de carpetas de spam.</li></ul><p>La integración es intencionalmente ligera y mínima en dependencias del lado del proyecto, y — importante para seguridad — cualquier operación que toque la base de datos desde el lado del servidor usa credenciales secretas con alcance apropiado que nunca se exponen al navegador. Nada sobre el almacén de suscriptores es alcanzable desde el frontend público; el sitio analítico y la maquinaria de suscripción están desacoplados, así que el panel sin login no lleva datos de usuario en absoluto.</p><p>Esta separación es deliberada: el panel estático público y gratuito no tiene servidor ni datos personales, mientras que la pequeña pieza de infraestructura que sí maneja datos personales (una dirección y preferencias de alerta) está aislada detrás de servicios gestionados construidos exactamente para ese trabajo. Mantiene la superficie de privacidad pequeña (Q38) y la fiabilidad alta, sin enredar las dos partes muy diferentes del sistema.</p>"}},{"n":"44","q":{"en":"44. Is there currently, or planned, a public REST/GraphQL API that developers can use to fetch the current risk score or historical series programmatically?","es":"44. ¿Hay actualmente, o planeado, una API REST/GraphQL pública que los desarrolladores puedan usar para obtener la puntuación de riesgo actual o la serie histórica programáticamente?"},"a":{"en":"<p>The honest answer is nuanced: there is <b>no formal, documented, versioned public API</b> today — but in practice the data is already fetchable, with caveats.</p> <p>Because the site is static and publishes its data as a plain file (<code>data.json</code> / <code>data.js</code>) served alongside the pages, a developer can <b>fetch that file directly</b> to obtain the current risk score and the historical series. It is machine-readable and available now, functioning as a de-facto read endpoint. What it is <b>not</b> is a formally supported API:</p> <ul> <li>it is the project's <b>internal data format</b>, shaped for the site's own needs, so its structure may <b>change without notice</b>;</li> <li>there are <b>no stability guarantees</b>, no versioning, no documented schema contract, and no rate-limit or uptime commitments intended for external consumers;</li> <li>it should therefore be used <b>at your own risk</b> for personal or exploratory purposes, not as the backbone of a production service.</li> </ul> <p>A <b>proper public API</b> — a documented, versioned endpoint with a stable schema for the current score and historical series — is a sensible and natural future addition, and the fact that the data is already generated cleanly each day means the groundwork exists. But it would be dishonest to describe it as available today. So: programmatic access is <b>possible now</b> via the published static data file (understanding it may change), while a formal, guaranteed developer API remains a candidate for the roadmap rather than a shipped feature.</p>","es":"<p>La respuesta honesta es matizada: no hay una API pública formal, documentada y versionada hoy — pero en la práctica los datos ya son obtenibles, con advertencias.</p><p>Porque el sitio es estático y publica sus datos como un archivo plano (data.json / data.js) servido junto a las páginas, un desarrollador puede obtener ese archivo directamente para obtener la puntuación de riesgo actual y la serie histórica. Es legible por máquina y disponible ahora, funcionando como un endpoint de lectura de facto. Lo que no es es una API formalmente soportada:</p><ul><li>es el formato de datos interno del proyecto, moldeado para las necesidades propias del sitio, así que su estructura puede cambiar sin aviso;</li><li>no hay garantías de estabilidad, versionado, contrato de esquema documentado ni compromisos de límite de tasa o tiempo de actividad pensados para consumidores externos;</li><li>por lo tanto debe usarse bajo tu propio riesgo para propósitos personales o exploratorios, no como columna vertebral de un servicio de producción.</li></ul><p>Una API pública adecuada — un endpoint documentado y versionado con un esquema estable para la puntuación actual y serie histórica — es una adición futura sensible y natural, y el hecho de que los datos ya se generen limpiamente cada día significa que la base existe. Pero sería deshonesto describirlo como disponible hoy. Así que: el acceso programático es posible ahora vía el archivo de datos estático publicado (entendiendo que puede cambiar), mientras que una API formal y garantizada para desarrolladores permanece como candidata para el roadmap más que una característica enviada.</p>"}},{"n":"45","q":{"en":"45. What fallback mechanisms exist when a data provider experiences an outage or the GitHub Actions workflow encounters an error?","es":"45. ¿Qué mecanismos de respaldo existen cuando un proveedor de datos experimenta una interrupción o el flujo de trabajo de GitHub Actions encuentra un error?"},"a":{"en":"<p>The system is designed to <b>fail safe rather than fail loud</b>, so that outages and errors degrade gracefully instead of showing you something wrong. Several layers work together:</p> <ul> <li><b>Redundant data reads.</b> The hybrid approach (a deep historical file plus a live top-up, Q15) means a single source being briefly unavailable does not necessarily break the day's run.</li> <li><b>The staleness guard.</b> If the newest usable data is more than a few days old, the pipeline <b>aborts the publish and the broadcast</b> rather than presenting an out-of-date score as current — a non-negotiable rule. The public daily post on X obeys the same rule: it <b>refuses to post</b> on stale data.</li> <li><b>Last-good serving.</b> Because the site is static, if a scheduled run fails outright, visitors keep seeing the <b>last successfully generated</b> data file (clearly dated), so the dashboard never goes blank or corrupt — it simply holds the last trustworthy reading until the next good run supersedes it.</li> <li><b>Visible, recoverable errors.</b> A failed workflow surfaces in the CI run logs, where the cause can be diagnosed and fixed; the next successful daily run then quietly brings everything back up to date.</li> </ul> <p>The philosophy, stated plainly, is that on a bad upstream or infrastructure day the system prefers to <b>hold the last correct value and skip rather than mislead</b>. Given that the metrics move slowly, a one-day pause during an outage costs almost nothing, whereas confidently displaying a stale or broken number could genuinely mislead a decision. So the fallbacks are less about clever automatic healing and more about a strict rule set that guarantees you are either seeing recent, valid data or clearly-dated last-known-good data — never a fabricated or silently outdated present.</p>","es":"<p>El sistema está diseñado para fallar de forma segura en lugar de fallar ruidosamente, para que las interrupciones y errores se degraden con gracia en lugar de mostrarte algo equivocado. Varias capas trabajan juntas:</p><ul><li><b>Lecturas de datos redundantes</b>. El enfoque híbrido (un archivo histórico profundo más una recarga en vivo, Q15) significa que una sola fuente siendo brevemente no disponible no necesariamente rompe la ejecución del día.</li><li><b>La guardia de obsolescencia</b>. Si los datos utilizables más nuevos tienen más de unos pocos días de antigüedad, el pipeline aborta la publicación y la difusión en lugar de presentar una puntuación desactualizada como actual — una regla no negociable. La publicación diaria pública en X obedece la misma regla: se niega a publicar en datos obsoletos.</li><li><b>Servicio del último bueno</b>. Porque el sitio es estático, si una ejecución programada falla completamente, los visitantes siguen viendo el último archivo de datos generado exitosamente (claramente fechado), así que el panel nunca queda en blanco o corrupto — simplemente retiene la última lectura confiable hasta que la siguiente ejecución buena la reemplaza.</li><li><b>Errores visibles y recuperables</b>. Una ejecución de flujo de trabajo fallida aparece en los registros de ejecución de CI, donde la causa puede diagnosticarse y arreglarse; la siguiente ejecución diaria exitosa luego trae todo de vuelta a la fecha silenciosamente.</li></ul><p>La filosofía, declarada claramente, es que en un mal día de infraestructura o aguas arriba el sistema prefiere <b>retener el último valor correcto y saltar</b> en lugar de engañar. Dado que las métricas se mueven lentamente, una pausa de un día durante una interrupción cuesta casi nada, mientras que mostrar confiadamente un número obsoleto o roto podría genuinamente engañar una decisión. Así que los respaldos son menos sobre curación automática inteligente y más sobre un conjunto estricto de reglas que garantiza que o estás viendo datos recientes y válidos o datos claramente fechados del último conocido bueno — nunca un presente fabricado o silenciosamente desactualizado.</p>"}}]},{"cat":{"en":"Limitations, Disclaimers & Best Practices","es":"Limitaciones, descargos y mejores prácticas"},"items":[{"n":"46","q":{"en":"46. Is the Bitcoin Risk Dashboard financial advice, and can it tell me when to buy or sell?","es":"46. ¿Es el Bitcoin Risk Dashboard asesoramiento financiero, y puede decirme cuándo comprar o vender?"},"a":{"en":"<p><b>No. It is not financial advice, and it does not tell you when to buy or sell.</b> This needs to be stated plainly and without qualification, because it is the single most important thing to understand about the tool.</p> <p>The dashboard is an <b>educational and informational</b> instrument. It provides context — a transparent, historically grounded read on whether Bitcoin looks cheap or stretched relative to its own past — and nothing more. It does not know your finances, your goals, your time horizon, your tax situation, or your risk tolerance, and it makes no recommendation tailored to you. A low risk score is not a \"buy\" instruction and a high score is not a \"sell\" instruction; they are descriptions of conditions that you must interpret for your own circumstances.</p> <ul> <li>It is <b>not personalised advice</b> — it cannot be, because it knows nothing about you.</li> <li>It is <b>not a recommendation</b> to take any specific action with any specific amount.</li> <li>It is <b>not a guarantee</b> — every signal is probabilistic and rooted in a short history that may not repeat.</li> </ul> <p>The honest framing is that the tool hands you a well-constructed <b>input</b>, and the decision — and its consequences — remain entirely yours. Bitcoin can lose a large share of its value, and this dashboard does not change that. For decisions that materially affect your financial wellbeing, consult a qualified, licensed financial professional who can account for your full situation. Use the risk score to be better informed, never to outsource your judgement.</p>","es":"<p>No. No es asesoramiento financiero, y no te dice cuándo comprar o vender. Esto debe declararse con claridad y sin reservas, porque es lo más importante que entender sobre la herramienta.</p><p>El panel es un instrumento educativo e informativo. Proporciona contexto — una lectura transparente y fundamentada históricamente sobre si Bitcoin parece barato o sobrevalorado en relación con su propio pasado — y nada más. No conoce tus finanzas, tus objetivos, tu horizonte temporal, tu situación fiscal ni tu tolerancia al riesgo, y no hace recomendación personalizada para ti. Una puntuación de riesgo baja no es una instrucción de \"comprar\" y una alta no es una instrucción de \"vender\"; son descripciones de condiciones que debes interpretar para tus propias circunstancias.</p><ul><li>No es asesoramiento personalizado — no puede serlo, porque no sabe nada de ti.</li><li>No es una recomendación para tomar ninguna acción específica con ninguna cantidad específica.</li><li>No es una garantía — cada señal es probabilística y arraigada en una historia corta que puede no repetirse.</li></ul><p>El encuadre honesto es que la herramienta te entrega una entrada bien construida, y la decisión — y sus consecuencias — permanecen enteramente tuyas. Bitcoin puede perder una porción grande de su valor, y este panel no cambia eso. Para decisiones que afectan materialmente tu bienestar financiero, consulta a un profesional financiero cualificado y licenciado que pueda dar cuenta de tu situación completa. Usa la puntuación de riesgo para estar mejor informado, nunca para externalizar tu juicio.</p>"}},{"n":"47","q":{"en":"47. What are the most important limitations of the model that every user must understand?","es":"47. ¿Cuáles son las limitaciones más importantes del modelo que todo usuario debe entender?"},"a":{"en":"<p>A tool is only trustworthy if it is candid about where it is weak. These are the limitations that matter most, and none of them are footnotes — they shape how much weight the score deserves:</p> <ul> <li><b>A very short history.</b> Bitcoin has lived through only a handful of full cycles. Every \"historically cheap\" or \"historically stretched\" judgement rests on a small sample, and small samples can mislead. What looks like an iron regularity may just be a few coincidences.</li> <li><b>Reflexivity and regime change.</b> Markets adapt. The arrival of spot ETFs, large institutions, derivatives, and changing macro conditions can alter how Bitcoin behaves, so relationships that held in the past can weaken or break. A model calibrated on old regimes may misread a genuinely new one.</li> <li><b>Proxy approximation.</b> Four of the eleven signals are proxies for data that is not freely available (Q12). They are down-weighted and flagged, but they are estimates, and estimates can be wrong.</li> <li><b>Parameter sensitivity.</b> The neutral centres and steepness of each signal are modelling choices (Q9, Q13). Reasonable alternative choices would shift the series somewhat, so the absolute level carries model dependence.</li> <li><b>It is not a predictor or a timing tool.</b> The score describes present conditions relative to history; it does not forecast price and cannot call tops or bottoms. High risk can persist and rise; low risk can fall further.</li> <li><b>Single asset, survivorship.</b> The whole framework is built on Bitcoin's specific, so-far-upward history. That history is not a law of nature, and past performance does not guarantee future results.</li> <li><b>Data lag and revisions.</b> On-chain data arrives with a short delay and is occasionally revised, so the very latest point is provisional.</li> </ul> <p>None of this makes the tool useless — a transparent, multi-signal composite is genuinely informative. But it means the honest posture is humility: treat the score as <b>one informed lens</b>, weigh it with the confidence score and your own judgement, and never mistake it for certainty.</p>","es":"<p>Una herramienta solo es confiable si es cándida sobre dónde es débil. Estas son las limitaciones que más importan, y ninguna es una nota al pie — moldean cuánto peso merece la puntuación:</p><ul><li><b>Una historia muy corta</b>. Bitcoin ha vivido solo un puñado de ciclos completos. Cada juicio de \"históricamente barato\" o \"históricamente sobrevalorado\" descansa en una muestra pequeña, y las muestras pequeñas pueden engañar. Lo que parece una regularidad de hierro puede ser solo unas pocas coincidencias.</li><li><b>Reflexividad y cambio de régimen</b>. Los mercados se adaptan. La llegada de ETFs spot, grandes instituciones, derivados y condiciones macro cambiantes puede alterar cómo se comporta Bitcoin, así que relaciones que se mantuvieron en el pasado pueden debilitarse o romperse. Un modelo calibrado en regímenes viejos puede malinterpretar uno genuinamente nuevo.</li><li><b>Aproximación de proxy</b>. Cuatro de las once señales son proxies para datos que no están disponibles gratuitamente (Q12). Tienen peso reducido y están marcadas, pero son estimaciones, y las estimaciones pueden estar equivocadas.</li><li><b>Sensibilidad a parámetros</b>. Los centros neutrales y la pendiente de cada señal son elecciones de modelado (Q9, Q13). Elecciones alternativas razonables moverían la serie algo, así que el nivel absoluto lleva dependencia del modelo.</li><li><b>No es un predictor ni una herramienta de timing</b>. La puntuación describe condiciones presentes relativas a la historia; no pronostica precio y no puede llamar tops o bottoms. El riesgo alto puede persistir y subir; el riesgo bajo puede caer más.</li><li><b>Un solo activo, supervivencia</b>. Todo el marco está construido sobre la historia específica, hasta ahora ascendente, de Bitcoin. Esa historia no es una ley de la naturaleza, y el rendimiento pasado no garantiza resultados futuros.</li><li><b>Retraso y revisiones de datos</b>. Los datos on-chain llegan con un retraso corto y ocasionalmente se revisan, así que el punto más reciente es provisional.</li></ul><p>Ninguna de estas hace la herramienta inútil — un compuesto multi-señal transparente es genuinamente informativo. Pero significa que la postura honesta es humildad: trata la puntuación como una lente informada, pésala con la puntuación de confianza y tu propio juicio, y nunca la confundas con certeza.</p>"}},{"n":"48","q":{"en":"48. Have there been times when the risk metric gave a counter-intuitive reading during a major historical event?","es":"48. ¿Ha habido momentos en que la métrica de riesgo dio una lectura contraintuitiva durante un evento histórico importante?"},"a":{"en":"<p>Honestly, yes — and it would be misleading to claim otherwise. No valuation indicator, however well constructed, is immune to being caught out, because a model built on <b>on-chain valuation</b> reflects <i>conditions</i>, not <i>exogenous shocks</i> it cannot see coming.</p> <p>The general pattern is worth understanding, stated carefully rather than with invented specifics:</p> <ul> <li><b>Sudden liquidity-driven crashes.</b> When a shock hits from outside the network — a broad market deleveraging, or contagion from a failing exchange or lender — price can collapse faster than cost-basis and holder-behaviour metrics register. A valuation-based risk read can therefore look only moderately elevated right before, or during, a violent drop, because the drop is about liquidity and confidence rather than the on-chain fundamentals the model watches. On-chain data cannot foresee a counterparty blowing up.</li> <li><b>Novel demand regimes.</b> Conversely, when a new source of demand appears (for instance, a wave of institutional or ETF-driven buying), traditional valuation ratios can read \"stretched\" while price keeps climbing for longer than history would suggest — because the buyer base and structure have changed. The model can look early or \"too cautious\" in a regime it has never seen.</li> </ul> <p>The honest lessons are consistent with the rest of this document. First, this is exactly why the score is a <b>composite</b> and is paired with a <b>confidence</b> read: breadth and agreement across signals guard against any one blind spot, though not perfectly. Second, it is why the tool is framed as <b>context, not prophecy</b>. Expect surprises, especially around unprecedented events, and never treat the number as a shield against tail risk. Combine it with your own awareness of what is happening in the wider market, and size your exposure so that a counter-intuitive reading before a shock cannot ruin you.</p>","es":"<p>Honestamente, sí — y sería engañoso afirmar lo contrario. Ningún indicador de valoración, por bien construido que esté, es inmune a ser sorprendido, porque un modelo construido sobre valoración on-chain refleja condiciones, no choques exógenos que no puede ver venir.</p><p>El patrón general vale la pena entender, declarado cuidadosamente más que con detalles inventados:</p><ul><li><b>Crashes repentinos impulsados por liquidez</b>. Cuando un choque golpea desde fuera de la red — un desapalancamiento amplio del mercado, o contagio de un exchange o prestamista fallido — el precio puede colapsar más rápido de lo que los ratios de cost-basis y métricas de comportamiento de holders registran. Una lectura de riesgo basada en valoración puede por lo tanto parecer solo moderadamente elevada justo antes, o durante, una caída violenta, porque la caída es sobre liquidez y confianza más que sobre los fundamentales on-chain que el modelo vigila. Los datos on-chain no pueden prever que una contraparte explote.</li><li><b>Regímenes de demanda novedosos</b>. A la inversa, cuando aparece una nueva fuente de demanda (por ejemplo, una ola de compra impulsada por instituciones o ETF), los ratios de valoración tradicionales pueden leer \"sobrevalorado\" mientras el precio sigue subiendo por más tiempo de lo que la historia sugeriría — porque la base de compradores y la estructura han cambiado. El modelo puede parecer temprano o \"demasiado cauteloso\" en un régimen que nunca ha visto.</li></ul><p>Las lecciones honestas son consistentes con el resto de este documento. Primero, esta es exactamente por qué la puntuación es un <b>compuesto</b> y se empareja con una lectura de confianza: la amplitud y acuerdo a través de señales protege contra cualquier punto ciego único, aunque no perfectamente. Segundo, es por qué la herramienta se enmarca como <b>contexto</b>, no profecía. Espera sorpresas, especialmente alrededor de eventos sin precedentes, y nunca trates el número como un escudo contra riesgo de cola. Combínalo con tu propia conciencia de lo que está pasando en el mercado más amplio, y dimensiona tu exposición para que una lectura contraintuitiva antes de un choque no pueda arruinarte.</p>"}},{"n":"49","q":{"en":"49. How sensitive is the risk score to the choice of data sources, proxy implementation, or the number of signals included?","es":"49. ¿Qué tan sensible es la puntuación de riesgo a la elección de fuentes de datos, implementación de proxy o el número de señales incluidas?"},"a":{"en":"<p><b>Somewhat sensitive — honestly so.</b> Like any composite model, the exact risk value depends on its ingredients: a different data vendor, a different formula for a proxy, or adding and removing a signal will all shift the series to some degree. Pretending the number is uniquely \"correct\" to two decimals would be false precision.</p> <p>Where the sensitivity lives:</p> <ul> <li><b>Data sources.</b> Different providers compute on-chain metrics with slightly different methods, so swapping sources would move some inputs and therefore the composite.</li> <li><b>Proxy implementation.</b> The four proxy signals (Q12) could be approximated in more than one reasonable way, and the chosen approximation affects their contribution — which is exactly why they are down-weighted and labelled.</li> <li><b>Signal set and weights.</b> Adding, removing, or reweighting signals changes the blend. The centres and scales of the logistic transforms (Q9, Q13) are choices too.</li> </ul> <p>Two things temper this. First, it is a <b>composite</b>: because eleven signals are blended and the proxies are held to low weight, no single choice swings the result catastrophically — the design is meant to be robust to any one input being imperfect. Second, the parameters and weights are <b>transparent and reviewed conservatively</b> (Q13), so the sensitivity is out in the open rather than hidden, and you can inspect exactly what drives the number. The practical guidance follows directly: focus on the score's <b>relative position and trend</b> — is it historically high or low, rising or falling — rather than treating a specific decimal as sacred. The signal is in the big picture, not the third digit.</p>","es":"<p>Algo sensible — honestamente. Como cualquier modelo compuesto, el valor exacto de riesgo depende de sus ingredientes: un proveedor de datos diferente, una fórmula diferente para un proxy, o añadir y quitar una señal cambiarán la serie en algún grado. Pretender que el número es únicamente \"correcto\" a dos decimales sería falsa precisión.</p><p>Donde vive la sensibilidad:</p><ul><li><b>Fuentes de datos</b>. Diferentes proveedores computan métricas on-chain con métodos ligeramente diferentes, así que intercambiar fuentes movería algunas entradas y por lo tanto el compuesto.</li><li><b>Implementación de proxy</b>. Las cuatro señales proxy (Q12) podrían aproximarse de más de una forma razonable, y la aproximación elegida afecta su contribución — que es exactamente por qué tienen peso reducido y están etiquetadas.</li><li><b>Conjunto de señales y pesos</b>. Añadir, quitar o reponderar señales cambia la mezcla. Los centros y escalas de las transformaciones logísticas (Q9, Q13) también son elecciones.</li></ul><p>Dos cosas lo templan. Primero, es un <b>compuesto</b>: porque once señales se combinan y los proxies tienen peso bajo, ninguna elección única balancea el resultado catastróficamente — el diseño está pensado para ser robusto a que cualquier entrada única sea imperfecta. Segundo, los parámetros y pesos son transparentes y revisados conservadoramente (Q13), así que la sensibilidad está a la vista en lugar de oculta, y puedes inspeccionar exactamente qué impulsa el número. La guía práctica sigue directamente: enfócate en la posición relativa y tendencia de la puntuación — ¿está históricamente alta o baja, subiendo o bajando? — en lugar de tratar un decimal específico como sagrado. La señal está en el panorama grande, no en el tercer dígito.</p>"}},{"n":"50","q":{"en":"50. What practical steps should I take before acting on any signal from the Bitcoin Risk Dashboard?","es":"50. ¿Qué pasos prácticos debo tomar antes de actuar sobre cualquier señal del Bitcoin Risk Dashboard?"},"a":{"en":"<p>Before you let the risk score influence real money, run through a short, sober checklist. It is designed to keep you in control and to prevent the most common mistakes:</p> <ul> <li><b>Do your own research.</b> Understand what the score represents (a historical-relative valuation read) and, just as importantly, what it does not (a prediction or advice). Read the limitations in Q46–Q49.</li> <li><b>Only invest what you can afford to lose.</b> Bitcoin's drawdowns are severe and real. Never commit money you need for living costs, debt, or an emergency fund.</li> <li><b>Size to your own risk tolerance and time horizon.</b> The right position for you depends on your circumstances, not on the score. A long horizon and a stomach for volatility justify different choices than a short horizon.</li> <li><b>Use the confidence score and the factor breakdown, not just the headline.</b> A number backed by broad agreement means more than a fragile one; the breakdown tells you what is driving it. Do not act on the top-line figure alone.</li> <li><b>Do not wait for a perfect zero.</b> Extreme low readings are rare; holding out for them often costs years of steady accumulation. A consistent plan that merely tilts with risk beats all-or-nothing timing.</li> <li><b>Account for fees and taxes yourself.</b> The dashboard does not model your personal costs (Q22); your real net outcome will be lower than any gross illustration.</li> <li><b>Keep it as one input among several.</b> Blend it with your own view of the market and your broader financial plan.</li> <li><b>Consider a professional.</b> For decisions that materially affect your finances, speak with a qualified, licensed adviser who can account for your whole situation.</li> </ul> <p>The through-line of this entire FAQ: the dashboard is a well-built lens for thinking more clearly about Bitcoin's valuation, offered transparently and honestly about its own limits. Use it to be better informed and more disciplined — and keep the judgement, and the responsibility, firmly your own.</p>","es":"<p>Antes de dejar que la puntuación de riesgo influya en dinero real, pasa por una lista de verificación corta y sobria. Está diseñada para mantenerte en control y prevenir los errores más comunes:</p><ul><li><b>Haz tu propia investigación</b>. Entiende qué representa la puntuación (una lectura de valoración relativa histórica) y, igual de importante, qué no (una predicción o consejo). Lee las limitaciones en Q46–Q49.</li><li><b>Solo invierte lo que puedas permitirte perder</b>. Los drawdowns de Bitcoin son severos y reales. Nunca comprometas dinero que necesites para gastos de vida, deudas o un fondo de emergencia.</li><li><b>Dimensiona a tu propia tolerancia al riesgo y horizonte temporal</b>. La posición correcta para ti depende de tus circunstancias, no de la puntuación. Un horizonte largo y un estómago para volatilidad justifican elecciones diferentes que un horizonte corto.</li><li><b>Usa la puntuación de confianza y el desglose de factores, no solo el titular</b>. Un número respaldado por acuerdo amplio significa más que uno frágil; el desglose te dice qué lo está impulsando. No actúes solo sobre la cifra principal.</li><li><b>No esperes por un cero perfecto</b>. Las lecturas extremadamente bajas son raras; esperarlas a menudo cuesta años de acumulación constante. Un plan consistente que simplemente se inclina con el riesgo supera el timing todo-o-nada.</li><li><b>Cuenta las comisiones e impuestos tú mismo</b>. El panel no modela tus costos personales (Q22); tu resultado neto real será menor que cualquier ilustración bruta.</li><li><b>Mantenlo como una entrada entre varias</b>. Combínalo con tu propia visión del mercado y tu plan financiero más amplio.</li><li><b>Considera a un profesional</b>. Para decisiones que afectan materialmente tus finanzas, habla con un asesor cualificado y licenciado que pueda dar cuenta de tu situación completa.</li></ul><p>La línea a través de toda esta FAQ: el panel es una lente bien construida para pensar más claramente sobre la valoración de Bitcoin, ofrecida transparentemente y honestamente sobre sus propios límites. Úsalo para estar mejor informado y más disciplinado — y mantén el juicio, y la responsabilidad, firmemente tuyos.</p>"}}]},{"cat":{"en":"Also frequently asked","es":"Otras preguntas frecuentes"},"items":[{"q":{"en":"How does this compare with a single-indicator tool like an MVRV Z-Score, Puell Multiple, or Mayer Multiple?","es":"¿Cómo se compara esto con una herramienta de indicador único como un MVRV Z-Score, Puell Multiple o Mayer Multiple?"},"a":{"en":"Those excellent metrics each capture one angle and each has blind spots. This dashboard uses several of them (and more) as individual signals inside a blended composite, so a misfire in any one is diluted by the others, and pairs the result with a confidence read. It is best thought of as a transparent way to combine such indicators rather than a competitor to any single one.","es":"<p>Esas métricas excelentes cada una captura un ángulo y cada una tiene puntos ciegos. Este panel usa varias de ellas (y más) como señales individuales dentro de un compuesto combinado, así que un fallo en cualquiera se diluye por las otras, y empareja el resultado con una lectura de confianza. Se piensa mejor como una forma transparente de combinar tales indicadores en lugar de un competidor a cualquiera de ellas.</p>"}},{"q":{"en":"Is the project open source?","es":"¿El proyecto es open source?"},"a":{"en":"No — the source code and exact parameters are kept in a private repository, so the model is not currently open to outside contributions. The dashboard is still transparent about <i>what</i> drives the score (the factor breakdown and proxy disclosures in Q12 and Q14), but the implementation itself is not published. Opening the model, or publishing a full methodology write-up, is a possible future step.","es":"<p>No — el código fuente y parámetros exactos se mantienen en un repositorio privado, así que el modelo no está actualmente abierto a contribuciones externas. El panel sigue siendo transparente sobre lo que impulsa la puntuación (el desglose de factores y divulgaciones de proxies en Q12 y Q14), pero la implementación misma no se publica. Abrir el modelo, o publicar una documentación completa de metodología, es un paso futuro posible.</p>"}},{"q":{"en":"How do I report a bug or a suspicious data point?","es":"¿Cómo reporto un bug o un punto de datos sospechoso?"},"a":{"en":"Because the pipeline can occasionally be affected by upstream data revisions or outages (Q17, Q45), a reading that looks clearly wrong is worth reporting so it can be looked into.","es":"<p>Porque el pipeline ocasionalmente puede verse afectado por revisiones de datos aguas arriba o interrupciones (Q17, Q45), una lectura que parece claramente equivocada vale la pena reportarla para que se investigue.</p>"}},{"q":{"en":"Which languages are supported?","es":"¿Qué idiomas se soportan?"},"a":{"en":"The dashboard is fully bilingual in <b>Spanish and English</b>, with the two versions held in strict parity so nothing is available in one language but missing in the other.","es":"<p>El panel es totalmente bilingüe en español e inglés, con las dos versiones mantenidas en paridad estricta para que nada esté disponible en un idioma pero falte en el otro.</p>"}},{"q":{"en":"Can I export data or use an API?","es":"¿Puedo exportar datos o usar una API?"},"a":{"en":"Chart images export directly from the charting toolbar, and the risk series is available via the published static data file served by the site, with the caveats in Q33 and Q44 (internal format, no formal API yet). The model's source code is not published, so independently reproducing or self-hosting the full pipeline is not currently possible from the outside.","es":"<p>Las imágenes de gráficos se exportan directamente desde la barra de herramientas de gráficos, y la serie de riesgo está disponible vía el archivo de datos estático publicado servido por el sitio, con las advertencias en Q33 y Q44 (formato interno, sin API formal aún). El código fuente del modelo no se publica, así que reproducir o auto-alojar independientemente el pipeline completo no es actualmente posible desde fuera.</p>"}},{"q":{"en":"What is on the roadmap?","es":"¿Qué hay en el roadmap?"},"a":{"en":"Candidate improvements mentioned throughout this document include a formal, versioned public API and tidy data exports, additional or refined signals as better data becomes available, near-real-time intraday alerting, and further notification channels such as Telegram or push. These are directions rather than dated promises; the live site reflects what actually ships.","es":"<p>Las mejoras candidatas mencionadas a lo largo de este documento incluyen una API pública formal y versionada y exportaciones de datos ordenadas, señales adicionales o refinadas a medida que mejores datos se vuelven disponibles, alertas intradía casi en tiempo real y canales de notificación adicionales como Telegram o push. Estas son direcciones más que promesas fechadas; el sitio en vivo refleja lo que realmente se envía.</p>"}},{"q":{"en":"About this edition · not financial advice","es":"SOBRE ESTA EDICIÓN · NO ES ASESORAMIENTO FINANCIERO"},"a":{"en":"This answered edition explains the dashboard faithfully and, where a precise internal figure changes daily or would be guesswork, states the principle and points to the live dashboard rather than inventing a number. Nothing in this document is investment, legal, or tax advice. Bitcoin can lose substantial value; past behaviour of any metric or backtest does not guarantee future results. Always do your own research, and consider a qualified professional before acting. © 2026 Bitcoin Risk · bitcoinrisk.net","es":"<p>Esta edición con respuestas explica el panel fielmente y, donde una figura interna precisa cambia diariamente o sería una conjetura, declara el principio y remite al panel en vivo en lugar de inventar un número. Nada en este documento es asesoramiento de inversión, legal o fiscal. Bitcoin puede perder valor sustancial; el comportamiento pasado de cualquier métrica o backtest no garantiza resultados futuros. Siempre realiza tu propia investigación, y considera a un profesional cualificado antes de actuar. © 2026 Bitcoin Risk · bitcoinrisk.net</p>"}}]}]};

SITE_CONTENT.about={"en": "<p>Bitcoin Risk (bitcoinrisk.net) is a free, bilingual (English/Spanish) dashboard that answers one question every Bitcoin holder quietly asks: how expensive or cheap is Bitcoin right now, relative to its own history? It distills that answer into a single daily risk score from 0 to 1, computed by an 11-signal composite model built on on-chain data — valuation metrics like MVRV, miner economics like the Puell Multiple, security-adjusted valuation (market cap vs. thermocap), holder behaviour, and network demand — blended with two price-trend signals and updated automatically every morning from Coin Metrics data reaching back to 2011.</p><p>The score is designed for regime awareness, not prediction: low readings have historically coincided with accumulation zones, high readings with distribution zones. Around that core number, the site provides an interactive fifteen-year chart of price versus risk, a live gauge with a confidence indicator, interactive backtests comparing standard dollar-cost averaging against risk-weighted DCA strategies, forward tests that track how the model behaves out of sample, and a methodology page that explains every signal — including the honest disclosure that four of the eleven signals are transparent, down-weighted proxies rather than the premium-data originals. The dashboard is transparent about what drives the score — the components table lays out all eleven signals grouped by factor family, with how each is normalized, and every proxy is clearly flagged — while the exact signal formulas, weights, and pipeline stay in a private implementation; what you see charted is exactly what the model computes, with no retroactive adjustments.</p><p>Everything interactive is free, permanently: the chart, backtests, gauge, methodology, and on-site data exports. For those who want the model inside their own tools, there's a public REST API — a free tier covering the last 90 days, and a Pro tier (€0.99/month or €9.99/year) with the full history since 2011, 5,000 requests/day, and component-level data as it's published. A daily automated summary with the latest crypto news also posts to X (@bitcoinrisk).</p><p><b>Who it's for:</b> long-term Bitcoin holders who DCA and want a disciplined, data-grounded sense of when to lean in or ease off; data-driven retail investors who prefer on-chain evidence over sentiment and headlines; quant hobbyists, researchers, and students who want a clean, reproducible daily risk series to study; and developers building bots, dashboards, or portfolio tools who need a reliable risk signal via API. It's equally usable by someone who checks one number once a week and someone piping the full historical series into their own models.</p><p>Bitcoin Risk is independent, ad-free, supported by voluntary donations and Pro subscriptions, and educational in nature — it's a lens on market conditions, not financial advice.</p>", "es": "<p>Bitcoin Risk (bitcoinrisk.net) es un panel gratuito y bilingüe (inglés/español) que responde a una pregunta que todo holder de Bitcoin se hace en silencio: ¿qué tan caro o barato está Bitcoin ahora mismo, en relación con su propia historia? Destila esa respuesta en un único índice de riesgo diario de 0 a 1, calculado por un modelo compuesto de 11 señales construido sobre datos on-chain — métricas de valoración como MVRV, economía de los mineros como el Múltiplo de Puell, valoración ajustada por seguridad (capitalización de mercado frente a thermocap), comportamiento de los holders y demanda de la red — combinadas con dos señales de tendencia de precio y actualizado automáticamente cada mañana con datos de Coin Metrics que se remontan a 2011.</p><p>El índice está diseñado para la conciencia de régimen, no para la predicción: las lecturas bajas han coincidido históricamente con zonas de acumulación, y las altas con zonas de distribución. En torno a ese número central, el sitio ofrece un gráfico interactivo de quince años de precio frente a riesgo, un medidor en vivo con un indicador de confianza, backtests interactivos que comparan el dollar-cost averaging estándar frente a estrategias de DCA ponderado por riesgo, forward tests que siguen cómo se comporta el modelo fuera de muestra, y una página de metodología que explica cada señal — incluida la divulgación honesta de que cuatro de las once señales son proxies transparentes y de bajo peso, en lugar de los originales de datos premium. El panel es transparente sobre qué impulsa el índice — la tabla de componentes muestra las once señales agrupadas por familia de factores, con cómo se normaliza cada una, y cada proxy está claramente señalado — mientras que las fórmulas exactas de las señales, los pesos y el pipeline permanecen en una implementación privada; lo que ves en el gráfico es exactamente lo que calcula el modelo, sin ajustes retroactivos.</p><p>Todo lo interactivo es gratuito, de forma permanente: el gráfico, los backtests, el medidor, la metodología y las exportaciones de datos del sitio. Para quienes quieren el modelo dentro de sus propias herramientas, hay una API REST pública — un nivel gratuito que cubre los últimos 90 días, y un nivel Pro (0,99 €/mes o 9,99 €/año) con el histórico completo desde 2011, 5.000 peticiones/día y datos a nivel de componente según se publican. Un resumen automático diario con las últimas noticias cripto también se publica en X (@bitcoinrisk).</p><p><b>Para quién es:</b> holders de Bitcoin a largo plazo que hacen DCA y quieren un sentido disciplinado y fundamentado en datos de cuándo inclinarse o relajarse; inversores minoristas guiados por datos que prefieren la evidencia on-chain al sentimiento y los titulares; aficionados a lo cuantitativo, investigadores y estudiantes que quieren una serie de riesgo diaria limpia y reproducible para estudiar; y desarrolladores que construyen bots, paneles o herramientas de cartera que necesitan una señal de riesgo fiable vía API. Es igual de útil para alguien que consulta un número una vez por semana como para alguien que canaliza toda la serie histórica hacia sus propios modelos.</p><p>Bitcoin Risk es independiente, sin publicidad, financiado por donaciones voluntarias y suscripciones Pro, y de naturaleza educativa — es una lente sobre las condiciones del mercado, no asesoramiento financiero.</p>"};
function renderContent(){
  var L = (typeof LANG!=="undefined" && SITE_CONTENT.methodology[LANG]) ? LANG : "en";
  var mb = document.getElementById("methBody");
  if(mb) mb.innerHTML = SITE_CONTENT.methodology[L];
  var ab = document.getElementById("aboutBody");
  if(ab && SITE_CONTENT.about) ab.innerHTML = SITE_CONTENT.about[L];
  var fl = document.getElementById("faqList");
  if(fl){
    var idx = '<div class="faq-index">', body = '';
    SITE_CONTENT.faq.forEach(function(cat, ci){
      var cid = "faqc-" + ci;
      var n = cat.items.length, inner = '';
      idx += '<a href="#" data-faq="' + cid + '">' + cat.cat[L] + '</a>';
      cat.items.forEach(function(it){
        inner += '<details class="acc"><summary>' + it.q[L] + '</summary><div class="body">' + it.a[L] + '</div></details>';
      });
      body += '<details class="faq-group" id="' + cid + '"' + (ci===0 ? ' open' : '') + '><summary>' + cat.cat[L] + '<span class="faq-group-n">' + n + '</span></summary><div class="faq-group-body">' + inner + '</div></details>';
    });
    fl.innerHTML = idx + '</div>' + body;
    fl.querySelectorAll('.faq-index a').forEach(function(a){
      a.addEventListener('click', function(e){
        e.preventDefault();
        var target = document.getElementById(a.getAttribute('data-faq'));
        if(target){ target.open = true; target.scrollIntoView({behavior:"smooth", block:"start"}); }
      });
    });
  }
}
function applyLang(){
  document.documentElement.lang = LANG;
  document.querySelectorAll("[data-i18n]").forEach(el=>{ const k=el.getAttribute("data-i18n"); if(I18N[LANG][k]!=null) el.textContent=I18N[LANG][k]; });
  document.querySelectorAll("[data-i18n-html]").forEach(el=>{ const k=el.getAttribute("data-i18n-html"); if(I18N[LANG][k]!=null) el.innerHTML=I18N[LANG][k]; });
  document.querySelectorAll("[data-i18n-ph]").forEach(el=>{ const k=el.getAttribute("data-i18n-ph"); if(I18N[LANG][k]!=null) el.placeholder=I18N[LANG][k]; });
  document.querySelectorAll("[data-i18n-title]").forEach(el=>{ const k=el.getAttribute("data-i18n-title"); if(I18N[LANG][k]!=null) el.title=I18N[LANG][k]; });
  document.getElementById("lang-es").classList.toggle("on", LANG==="es");
  document.getElementById("lang-en").classList.toggle("on", LANG==="en");
  renderContent();
}
function setLang(l){ LANG=l; applyLang(); updateAction(LIVE.risk,LIVE.date,LIVE.live); renderFwdCards(); buildSimScen(); if(SIM_LAST) renderSimResults(SIM_LAST); if(BT_LAST) renderBacktest(BT_LAST); }

/* ---- math (verbatim from the reference model) ---- */
function sig(x,c,b){ return 1/(1+Math.exp(-(x-c)/b)); }
function clip(x,a,b){ return Math.max(a,Math.min(b,x)); }
function mean(a){ let s=0; for(const v of a) s+=v; return s/a.length; }
function stdev(a){ if(a.length<2) return 0; const m=mean(a); let s=0; for(const v of a) s+=(v-m)*(v-m); return Math.sqrt(s/(a.length-1)); }
function riskAt(prices,i,prevRisk,runMax){
  const P=prices[i];
  const m0=Math.max(0,i-(MODEL.smaMayer-1));
  const sMayer=clip(sig(P/mean(prices.slice(m0,i+1)),MODEL.params.mayer[0],MODEL.params.mayer[1]),0,1);
  const sAth=clip(Math.pow(Math.min(P/runMax,1),MODEL.athExp),0,1);
  /* price-trend recomputed live; the 9 on-chain signals (factors A–E) held at their last value */
  const subs={mayer:sMayer,ath:sAth};
  for(const k in MODEL.heldSubs){ subs[k]=MODEL.heldSubs[k]; }
  let num=0,den=0; for(const k in MODEL.weights){ const v=subs[k]; if(v!=null&&!isNaN(v)){ num+=MODEL.weights[k]*v; den+=MODEL.weights[k]; } }
  const raw=den>0?num/den:prevRisk; const alpha=2/(MODEL.emaSpan+1);
  const risk=clip(alpha*raw+(1-alpha)*prevRisk,0,1);
  const arr=Object.values(subs).filter(v=>v!=null&&!isNaN(v)); const disp=stdev(arr);
  const conf=Math.round(clip(10*(0.78*clip(1-2*disp,0,1)+0.22*clip(2*Math.abs(risk-0.5),0,1)),0,10));
  return {risk,conf};
}

/* ---- Plotly loader ---- */
const CDNS=["https://cdnjs.cloudflare.com/ajax/libs/plotly.js/2.27.0/plotly.min.js","https://cdn.plot.ly/plotly-2.27.0.min.js","https://unpkg.com/plotly.js-dist-min@2.27.0/plotly.min.js"];
function loadPlotly(i){ i=i||0; return new Promise((res,rej)=>{ if(window.Plotly) return res(); if(i>=CDNS.length) return rej(new Error("no Plotly")); const s=document.createElement("script"); s.src=CDNS[i]; s.async=true; s.onload=()=>res(); s.onerror=()=>{s.remove(); loadPlotly(i+1).then(res).catch(rej);}; document.head.appendChild(s); }); }

