const C={low2:"#2ea043",acc:"#3fb950",hold:"#e7b53b",d1:"#d2691e",d2:"#e8590c",d3:"#f03e3e",d4:"#ff4d4d"};
function actionFor(r){
  if(r<0.10) return {kind:"buy",mult:5,rk:"regime_acc_max",color:C.low2};
  if(r<0.20) return {kind:"buy",mult:4,rk:"regime_acc_high",color:C.low2};
  if(r<0.30) return {kind:"buy",mult:3,rk:"regime_acc",color:C.acc};
  if(r<0.60) return {kind:"hold",rk:"regime_hold",color:C.hold};
  if(r<0.70) return {kind:"sell",parts:2,rk:"regime_dist",color:C.d1};
  if(r<0.80) return {kind:"sell",parts:3,rk:"regime_dist",color:C.d2};
  if(r<0.90) return {kind:"sell",parts:4,rk:"regime_dist_heavy",color:C.d3};
  return {kind:"sell",parts:5,rk:"regime_dist_max",color:C.d4};
}
