/* ---- live refresh (multi-source) ---- */
async function fetchSpot(){
  const tries=[
    async()=>{const r=await fetch("https://api.coinbase.com/v2/prices/BTC-USD/spot");if(!r.ok)throw 0;const j=await r.json();return parseFloat(j.data.amount);},
    async()=>{const r=await fetch("https://api.kraken.com/0/public/Ticker?pair=XBTUSD");if(!r.ok)throw 0;const j=await r.json();const k=Object.keys(j.result)[0];return parseFloat(j.result[k].c[0]);},
    async()=>{const r=await fetch("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd");if(!r.ok)throw 0;const j=await r.json();return j.bitcoin.usd;}
  ];
  for(const f of tries){ try{ const v=await f(); if(v>0) return v; }catch(e){} }
  return null;
}
async function refresh(){
  try{
    let fresh=[];
    try{
      const r=await fetch("https://api.coingecko.com/api/v3/coins/bitcoin/market_chart?vs_currency=usd&days=365",{cache:"no-store"});
      if(r.ok){ const j=await r.json(); const byDay={};
        const _today=new Date().toISOString().slice(0,10), _yest=new Date(Date.now()-864e5).toISOString().slice(0,10); let _open=null;
        for(const a of j.prices){ const _d=new Date(a[0]).toISOString().slice(0,10); byDay[_d]=a[1]; if(_d===_today&&_open===null) _open=a[1]; }
        DAY_OPEN=(_open!=null)?_open:(byDay[_yest]!=null?byDay[_yest]:DAY_OPEN);   /* today's open; fall back to yesterday's close */
        fresh=Object.keys(byDay).sort().map(d=>({date:d,price:byDay[d]})).filter(p=>p.date>MODEL.lastDate); }
    }catch(e){}
    if(!fresh.length){ const s=await fetchSpot(); if(s){ const d=new Date().toISOString().slice(0,10); if(d>MODEL.lastDate) fresh=[{date:d,price:s}]; } }
    if(!fresh.length) return;
    const tt=DATA.t.slice(),pp=DATA.p.slice(),rr=DATA.r.slice(),cc=DATA.c.slice();
    let prevRisk=MODEL.lastRisk, runMax=MODEL.lastATH, prices=DATA.p.slice(), last=null;
    for(const pt of fresh){ prices.push(pt.price); const i=prices.length-1; runMax=Math.max(runMax,pt.price);
      const o=riskAt(prices,i,prevRisk,runMax); prevRisk=o.risk; tt.push(pt.date); pp.push(pt.price); rr.push(o.risk); cc.push(o.conf); last={date:pt.date,risk:o.risk}; }
    CUR={t:tt,p:pp,r:rr,c:cc};
    LIVE_PX=pp[pp.length-1]; LIVE_CONF=cc[cc.length-1];
    if(window.Plotly) drawChart();
    if(last) updateAction(last.risk,last.date,true);
    if(typeof buildRanges==="function") buildRanges();
    if(typeof buildMatrix==="function") buildMatrix();
  }catch(e){}
}
let autoTimer=null; const REFRESH_MS=300000;
function startAuto(){ if(autoTimer) return; autoTimer=setInterval(refresh,REFRESH_MS); refresh(); }
function stopAuto(){ clearInterval(autoTimer); autoTimer=null; }
