/* ===== PART 1 · live Monte-Carlo stochastic engine (paper §3-4) ===== */
function simulateStochastic(s,nPaths,years,onchain){
  const ep=effParams(s), L=CHOL, dt=7;
  const lastMs=Date.parse(MODEL.lastDate+"T00:00:00Z");
  const dNow=daysSince(lastMs), lastPx=DATA.p[DATA.p.length-1];
  const nS=Math.round(years*365.25/dt), sq=Math.sqrt(dt), thr=3*ep.sigma*sq;
  const nBand=Math.min(nS,90), bandSteps=[];
  for(let b=1;b<=nBand;b++){ const st=Math.round(b*nS/nBand); if(bandSteps[bandSteps.length-1]!==st) bandSteps.push(st); }
  const bandIdx=new Map(); bandSteps.forEach((st,ix)=>bandIdx.set(st,ix));
  const dates=bandSteps.map(st=>new Date(lastMs+st*dt*86400000).toISOString().slice(0,10));
  const det=bandSteps.map(st=>detLevelAt(dNow+st*dt,ep,dNow,lastPx));
  const nSamp=Math.min(nPaths,50);
  const cols=bandSteps.map(()=>new Float64Array(nPaths));
  const samp=[]; for(let i=0;i<nSamp;i++) samp.push(new Float64Array(bandSteps.length));
  const P=new Float64Array(nPaths).fill(lastPx), maxAbsR=new Float64Array(nPaths);
  const onMu=[0,0.00040,0.00020,0.00015], onSig=[0,0.030,0.035,0.040];
  const lvl=onchain?[lastPx,100,100,100]:null;
  const oc=onchain?{price:[],hash:[],addr:[],tx:[]}:null;
  const z=[0,0,0,0];
  for(let k=1;k<=nS;k++){
    const t=dNow+k*dt, mu=hybDrift(t,ep), isBand=bandIdx.has(k), bi=isBand?bandIdx.get(k):-1;
    for(let pi=0;pi<nPaths;pi++){
      z[0]=randn(); let R;
      if(onchain && pi===0){
        z[1]=randn(); z[2]=randn(); z[3]=randn();
        R=mu*dt+ep.sigma*sq*(L[0][0]*z[0]);
        const zc1=L[1][0]*z[0]+L[1][1]*z[1];
        const zc2=L[2][0]*z[0]+L[2][1]*z[1]+L[2][2]*z[2];
        const zc3=L[3][0]*z[0]+L[3][1]*z[1]+L[3][2]*z[2]+L[3][3]*z[3];
        lvl[0]*=Math.exp(R);
        lvl[1]*=Math.exp(onMu[1]*dt+onSig[1]*sq*zc1);
        lvl[2]*=Math.exp(onMu[2]*dt+onSig[2]*sq*zc2);
        lvl[3]*=Math.exp(onMu[3]*dt+onSig[3]*sq*zc3);
      } else { R=mu*dt+ep.sigma*sq*z[0]; }
      const aR=R<0?-R:R; if(aR>maxAbsR[pi]) maxAbsR[pi]=aR;
      P[pi]*=Math.exp(R);
      if(isBand){ cols[bi][pi]=P[pi]; if(pi<nSamp) samp[pi][bi]=P[pi]; }
    }
    if(onchain && bandIdx.has(k)){ oc.price.push(lvl[0]/lastPx*100); oc.hash.push(lvl[1]); oc.addr.push(lvl[2]); oc.tx.push(lvl[3]); }
  }
  const p5=[],p50=[],p95=[];
  for(let ix=0;ix<bandSteps.length;ix++){ const c=Array.from(cols[ix]).sort((a,b)=>a-b); p5.push(pctile(c,.05)); p50.push(pctile(c,.5)); p95.push(pctile(c,.95)); }
  const fin=Array.from(cols[cols.length-1]).sort((a,b)=>a-b);
  let nStress=0; for(let i=0;i<nPaths;i++) if(maxAbsR[i]>thr) nStress++;
  return {dates,p5,p50,p95,det,samples:samp.map(a=>Array.from(a)),
    finalP5:pctile(fin,.05),finalP50:pctile(fin,.5),finalP95:pctile(fin,.95),
    finalMean:fin.reduce((a,b)=>a+b,0)/nPaths,stress:100*nStress/nPaths,
    bEff:ep.b,sigma:ep.sigma,nSteps:nS,oc,anchorDate:MODEL.lastDate,anchorPx:lastPx};
}

