/* ===================== cover dashboard logic ===================== */
const _lastClose=DATA.p[DATA.p.length-1];
/* price-only blend in [0,1] + the four price sub-scores, for a hypothetical "today" price P */
function priceBlend(P){
  const prices=DATA.p, i=prices.length;
  const m0=Math.max(0,i-(MODEL.smaMayer-1)); const mw=prices.slice(m0,i); mw.push(P); const sma=mean(mw);
  const sMayer=clip(sig(P/sma,MODEL.params.mayer[0],MODEL.params.mayer[1]),0,1);
  const runMax=Math.max(MODEL.lastATH,P); const sAth=clip(Math.pow(Math.min(P/runMax,1),MODEL.athExp),0,1);
  const subs={mayer:sMayer,ath:sAth};
  const w={mayer:MODEL.weights.mayer,ath:MODEL.weights.ath};
  let acc=0,wsum=0; for(const k in w){ const v=subs[k]; if(v!=null&&!isNaN(v)){ acc+=w[k]*v; wsum+=w[k]; } }
  return {blend: wsum>0?acc/wsum:0, s:subs};
}
/* ---- risk↔price matrix, pivoted on the LIVE price + LIVE risk ----
   The matrix answers "at what BTC price would the model read X?". It must agree with the
   live gauge at today's price, so the anchor is re-derived from LIVE_PX / LIVE.risk on every
   buildMatrix() (reanchor()), not frozen to the embedded close. On-chain valuation/security (~60% of
   the model) is held at its last-known value AT the anchor price — exactly matching the gauge —
   and only coupled to price for the hypothetical rows away from today, so the full 0–1 range
   stays reachable. Falls back to the embedded close before the first live refresh. */
let MTX_ANCHOR={ px:_lastClose, pb0:priceBlend(_lastClose).blend, raw:0, disp:MODEL.lastRisk };
function couple(anchor,pb){ const PB0=MTX_ANCHOR.pb0;
  return pb>=PB0 ? anchor+(1-anchor)*((pb-PB0)/Math.max(1e-6,1-PB0)) : anchor*(pb/Math.max(1e-6,PB0)); }
function riskRaw(P){
  const pb=priceBlend(P), H=MODEL.heldSubs;
  /* valuation / security / miner / demand track the hypothetical price; holder-behavior (rhodl) held */
  const subs={mayer:pb.s.mayer, ath:pb.s.ath,
    mvrv:couple(H.mvrv,pb.blend), mvrvz:couple(H.mvrvz,pb.blend), sip:couple(H.sip,pb.blend),
    term:couple(H.term,pb.blend), puell:couple(H.puell,pb.blend), mctc:couple(H.mctc,pb.blend),
    mctcmod:couple(H.mctcmod,pb.blend), fees:couple(H.fees,pb.blend), rhodl:H.rhodl};
  let num=0,den=0; for(const k in MODEL.weights){ const v=subs[k]; if(v!=null&&!isNaN(v)){ num+=MODEL.weights[k]*v; den+=MODEL.weights[k]; } }
  return den>0?num/den:0;
}
/* re-pivot the matrix on the latest live price + displayed (live) risk */
function reanchor(){
  MTX_ANCHOR.px  = (typeof LIVE_PX==="number" && isFinite(LIVE_PX) && LIVE_PX>0) ? LIVE_PX : _lastClose;
  MTX_ANCHOR.pb0 = priceBlend(MTX_ANCHOR.px).blend;                 // couple() baseline = anchor price
  MTX_ANCHOR.raw = riskRaw(MTX_ANCHOR.px);                          // raw model value at the anchor
  MTX_ANCHOR.disp= (LIVE && LIVE.risk!=null) ? LIVE.risk : MODEL.lastRisk; // displayed live risk
}
function invRemap(y){ y=clip(y,0,1); const R=MTX_ANCHOR.raw, D=MTX_ANCHOR.disp;
  return y<=D ? R*(y/Math.max(1e-6,D)) : R+(1-R)*((y-D)/Math.max(1e-6,1-D)); }
function priceForRisk(target){
  const rt=invRemap(target), base=MTX_ANCHOR.px; let lo=base/400, hi=base*400;
  if(riskRaw(lo)>=rt) return lo; if(riskRaw(hi)<=rt) return hi;
  for(let k=0;k<60;k++){ const mid=Math.sqrt(lo*hi); if(riskRaw(mid)<rt) lo=mid; else hi=mid; }
  return Math.sqrt(lo*hi);
}
const MTX_LEVELS=[0.05,0.10,0.15,0.20,0.25,0.30,0.40,0.50,0.60,0.70,0.80,0.90,0.95];
function fmtPx(v){ if(v>=1e6) return "$"+(v/1e6).toFixed(2)+"M"; if(v>=1000) return "$"+Math.round(v).toLocaleString(); if(v>=1) return "$"+v.toFixed(0); return "$"+v.toFixed(2); }
let MSS_INIT=false;
function updateMtxSlider(v){
  var r=clip(v,0,1), px=priceForRisk(r), cur=LIVE_PX||_lastClose, chg=(px/cur-1)*100, col=riskColor(r);
  var er=document.getElementById("mssRisk"); if(er){ er.textContent=r.toFixed(2); er.style.color=col; }
  var ep=document.getElementById("mssPx"); if(ep) ep.textContent=fmtPx(px);
  var ec=document.getElementById("mssChg"); if(ec){ var sg=chg>=0?"+":""; ec.textContent=(Math.abs(chg)<0.05?"":"("+sg+chg.toFixed(1)+"%)"); ec.className="mss-chg "+(chg>=0?"up":"down"); }
  var mr=document.getElementById("mtxRange"); if(mr) mr.style.setProperty("--thumb-col",col);
}
function buildMatrix(){
  const body=document.getElementById("mtxBody"); if(!body) return;
  reanchor();
  const cur=LIVE_PX||_lastClose;
  MTX_ROWS=MTX_LEVELS.map(lvl=>({lvl,price:priceForRisk(lvl)}));
  body.innerHTML=MTX_ROWS.map(row=>{
    const chg=(row.price/cur-1)*100, cls=chg>=0?"up":"down", sign=chg>=0?"+":"";
    return '<tr><td class="r-lvl"><span class="sw" style="background:'+riskColor(row.lvl)+'"></span>'+row.lvl.toFixed(2)+'</td>'+
      '<td class="r-px">'+fmtPx(row.price)+'</td>'+
      '<td class="r-chg '+cls+'">'+(Math.abs(chg)<0.05?'·':sign+chg.toFixed(1)+'%')+'</td></tr>';
  }).join("");
  highlightMatrix(LIVE.risk);
  var _mr=document.getElementById("mtxRange");
  if(_mr){ if(!MSS_INIT){ _mr.value=((LIVE.risk!=null?LIVE.risk:0.3)).toFixed(2); MSS_INIT=true; } updateMtxSlider(parseFloat(_mr.value)); }
}
function highlightMatrix(risk){
  const body=document.getElementById("mtxBody"); if(!body||!MTX_ROWS.length) return;
  let best=0,bd=9; MTX_ROWS.forEach((r,k)=>{ const d=Math.abs(r.lvl-risk); if(d<bd){ bd=d; best=k; } });
  Array.prototype.forEach.call(body.children,(tr,k)=>tr.classList.toggle("cur",k===best));
}
/* 7d / 30d risk range bars */
function setRange(p,n){
  const arr=CUR.r.slice(-n); if(!arr.length) return;
  const lo=Math.min.apply(null,arr), hi=Math.max.apply(null,arr);
  const cur=(LIVE.risk!=null)?LIVE.risk:arr[arr.length-1];
  const lop=clip(lo,0,1)*100, hip=clip(hi,0,1)*100, cp=clip(cur,0,1)*100;
  const E=s=>document.getElementById(p+s);
  const c=E("cur"); if(c){ c.textContent=cur.toFixed(2); c.style.background=riskColor(cur); }
  const f=E("fill"); if(f){ f.style.left=lop+"%"; f.style.width=Math.max(1,hip-lop)+"%"; }
  const m=E("mark"); if(m){ m.style.left="calc("+cp+"% - 1.5px)"; }
  const l=E("lo"); if(l) l.textContent=lo.toFixed(2);
  const h=E("hi"); if(h) h.textContent=hi.toFixed(2);
}
