/* ---- notifications (time / price / strategy based, visual) ---- */
(function(){
  let NMODE="time";
  const $=id=>document.getElementById(id);
  function fillRange(sel,a,b){ if(!sel) return; const cur=sel.value; sel.innerHTML=""; for(let i=a;i<=b;i++){ const o=document.createElement("option"); o.value=String(i); o.textContent=String(i); sel.appendChild(o);} if(cur&&+cur>=a&&+cur<=b) sel.value=cur; }
  function monthName(i){ return t("mon_"+["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"][i]); }
  function fillMonths(){ const sel=$("ntYearMonth"); if(!sel) return; const cur=sel.value||"1"; sel.innerHTML=""; for(let m=1;m<=12;m++){ const o=document.createElement("option"); o.value=String(m); o.textContent=monthName(m-1); sel.appendChild(o);} sel.value=cur; }
  function daysInMonth(m){ return [31,29,31,30,31,30,31,31,30,31,30,31][m-1]; }
  function syncFreq(){ const f=$("ntFreq").value;
    $("ntWeekWrap").style.display = f==="weekly"?"":"none";
    $("ntMonthWrap").style.display = f==="monthly"?"":"none";
    $("ntYearWrap").style.display = f==="yearly"?"":"none";
    if(f==="yearly"){ fillRange($("ntYearDay"),1,daysInMonth(+$("ntYearMonth").value||1)); } }
  function setMode(m){ NMODE=m; $("subMsg").textContent="";
    document.querySelectorAll(".nchip").forEach(c=>c.classList.toggle("on",c.dataset.mode===m));
    $("nmodeTime").style.display = m==="time"?"":"none";
    $("nmodePrice").style.display = m==="price"?"":"none";
    $("nmodeStrat").style.display = m==="strategy"?"":"none"; }
  function ord(n){ const s=["th","st","nd","rd"],v=n%100; return n+(s[(v-20)%10]||s[v]||s[0]); }
  function submit(){
  const email = ($("subEmail").value || "").trim();
  const m = $("subMsg");

  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
    m.style.color = "#ef5366";
    m.textContent = t("notif_bad_email");
    return;
  }

  m.style.color = "#d29922";
  m.textContent = "Subscribing...";

  // Collect settings based on current mode
  let settings = {};
  if (NMODE === "time") {
    settings = {
      freq: $("ntFreq").value,
      weekday: $("ntWeekday")?.value,
      dom: $("ntDom")?.value,
      month: $("ntYearMonth")?.value,
      day: $("ntYearDay")?.value
    };
  } else if (NMODE === "strategy") {
    settings = {
      strategy: $("nsStrat").value,
      base: parseFloat($("nsBase").value),
      cadence: $("nsCadence").value
    };
  } else if (NMODE === "price") {
    settings = {
      direction: $("npDir").value,
      threshold: parseFloat($("npThresh").value)
    };
  }

  fetch("/api/subscribe", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email,
      mode: NMODE,
      settings
    })
  })
  .then(res => {
    if (res.ok) {
      m.style.color = "#36c08a";
      m.textContent = "Subscription successful! You will receive emails according to your settings.";
      $("subEmail").value = "";
    } else {
      m.style.color = "#ef5366";
      m.textContent = "Error subscribing. Please try again.";
    }
  })
  .catch(() => {
    m.style.color = "#ef5366";
    m.textContent = "Connection error. Please try again.";
  });
}
  function initNotif(){
    if(!$("ntFreq")) return;
    fillRange($("ntDom"),1,31); fillMonths(); fillRange($("ntYearDay"),1,31);
    document.querySelectorAll(".nchip").forEach(c=>c.addEventListener("click",()=>setMode(c.dataset.mode)));
    $("ntFreq").addEventListener("change",syncFreq);
    $("ntYearMonth").addEventListener("change",()=>fillRange($("ntYearDay"),1,daysInMonth(+$("ntYearMonth").value||1)));
    $("subBtn").addEventListener("click",submit);
    syncFreq();
  }
  window.__initNotif=initNotif;
  window.__notifRelang=function(){ fillMonths(); const f=$("ntFreq"); if(f) syncFreq(); };
})();

