/* ---- Pro plan chooser ---- */
if($id("proCtaBtn"))$id("proCtaBtn").addEventListener("click",()=>{
  closeAux(); /* close the API-access overlay so the Pro modal isn't stacked behind it (both share z-index) */
  $id("proMsg").textContent="";
  $id("proOverlay").classList.add("open");
});
function subscribe(plan,btn){
  const body={type:"subscription",plan};
  const inp=$id("apiEmail");
  const em=inp?(inp.value||"").trim().toLowerCase():"";
  if(EMAIL_RE.test(em))body.email=em; /* prefill Stripe Checkout; Stripe collects it otherwise */
  startCheckout(body,$id("proMsg"),btn);
}
$id("planMonthly").addEventListener("click",function(){subscribe("monthly",this);});
$id("planYearly").addEventListener("click",function(){subscribe("yearly",this);});

/* Returning from Stripe Checkout */
(function(){
  const q=new URLSearchParams(location.search);
  const pm=$id("payMsg"),am=$id("apiMsg");
  if(q.get("pro")==="success"){
    if(pm)pm.textContent=t("pro_welcome");
    if(am)am.textContent=t("pro_welcome");
    if(apiPanel)apiPanel.style.display="";
    history.replaceState(null,"",location.pathname+location.hash);
  }else if(q.get("thanks")==="1"){
    if(pm)pm.textContent=t("don_thanks");
    history.replaceState(null,"",location.pathname+location.hash);
  }
})();

/* ---- contribute + suggestions (visual) ---- */
(function(){
  /* BTC address copy now lives in the donation modal (pmCopyAddr). */
  const sugBtn = document.getElementById("sugBtn");
if(sugBtn){ 
  sugBtn.addEventListener("click", async () => {
    const txt = (document.getElementById("sugText").value || "").trim();
    const email = (document.getElementById("sugEmail").value || "").trim();
    const m = document.getElementById("sugMsg");

    if (txt.length < 12) {
      m.style.color = "#ef5366";
      m.textContent = t("sug_bad");
      return;
    }

    m.style.color = "#d29922";
    m.textContent = "Sending...";

    try {
      const res = await fetch("/api/suggest", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, message: txt })
      });

      if (res.ok) {
        m.style.color = "#36c08a";
        m.textContent = t("sug_ok");
        document.getElementById("sugText").value = "";
        document.getElementById("sugEmail").value = "";
      } else {
        m.style.color = "#ef5366";
        m.textContent = "Error sending suggestion. Please try again.";
      }
    } catch (err) {
      m.style.color = "#ef5366";
      m.textContent = "Connection error. Please try again.";
    }
  });
}
})();
/* ---- boot ---- */
applyLang();
renderFwdCards();
buildSimScen();
updateAction(LIVE.risk,LIVE.date,false);
doBacktest();
/* simulator control wiring */
document.getElementById("simRun").addEventListener("click",runSimulation);
["simPaths","simHorizon","simOnchain"].forEach(id=>document.getElementById(id).addEventListener("change",runSimulation));
loadPlotly().then(()=>{ drawChart().then(attachRangeReset); if(BT_LAST) renderBacktest(BT_LAST); })
  .catch(()=>{ const ce=document.getElementById("chartPlot"); if(ce) ce.innerHTML='<div style="padding:30px;color:#ef5366">'+t("chart_err")+'</div>'; });
const fwdObs=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting && !FWD_DONE){ FWD_DONE=true; loadPlotly().then(()=>{ buildForward(); runSimulation(); }); fwdObs.disconnect(); } }),{threshold:.05});
fwdObs.observe(document.getElementById("forward"));
coverInit();
/* live price + risk refresh runs independently of the chart library, so the gauge and the
   risk↔price matrix reflect live data (and re-anchor to it) even if Plotly is slow or blocked */
if(document.getElementById("autoChk").checked) startAuto();

/* initial view from URL hash (after all defs so FWD_DONE etc. are live) */
routeTo(location.hash);

